const MisEstrellasModal = ({ user, plantilla, jornada, onClose }) => {
    var G = styles.colors;
    var [seleccion, setSeleccion] = useState([]);
    var [guardado, setGuardado] = useState(false);
    var [guardando, setGuardando] = useState(false);
    var [posFiltro, setPosicion] = useState('Todos');
    var [tab, setTab] = useState('elegir'); // 'elegir' | 'puntos'
    var [ahora, setAhora] = useState(new Date());

    useEffect(function() {
        var t = setInterval(function() { setAhora(new Date()); }, 30000);
        return function() { clearInterval(t); };
    }, []);

    // Bloqueo 2 horas antes del partido — para que nadie elija después de
    // saber el 11 inicial (que se suele publicar ~1h antes del kickoff).
    var fechaPartidoObj = jornada && jornada.fechaPartido
        ? (jornada.fechaPartido.toDate ? jornada.fechaPartido.toDate() : new Date(jornada.fechaPartido))
        : null;
    var limiteEstrellas = fechaPartidoObj ? new Date(fechaPartidoObj.getTime() - 2 * 60 * 60 * 1000) : null;
    var estrellasCerradas = !!(limiteEstrellas && ahora >= limiteEstrellas);
    var msHastaBloqueo = limiteEstrellas ? Math.max(0, limiteEstrellas - ahora) : null;
    var horasRestantes = msHastaBloqueo !== null ? Math.floor(msHastaBloqueo / 3600000) : null;
    var minutosRestantes = msHastaBloqueo !== null ? Math.floor((msHastaBloqueo % 3600000) / 60000) : null;

    useEffect(function() {
        if (!jornada) return;
        getDoc(doc(db, "estrellas_seleccion", jornada.id, "jugadores", user)).then(function(snap) {
            if (snap.exists()) { setSeleccion(snap.data().jugadores || []); setGuardado(true); }
        });
    }, [jornada, user]);

    var toggle = function(j) {
        if (estrellasCerradas) return;
        if (jornada && jornada.estado !== 'Abierta') return;
        var ya = seleccion.find(function(s) { return s.nombre === j.nombre; });
        if (ya) { setSeleccion(seleccion.filter(function(s) { return s.nombre !== j.nombre; })); }
        else if (seleccion.length < 5) { setSeleccion([...seleccion, j]); }
    };

    var guardar = async function() {
        if (!jornada || seleccion.length === 0) return;
        if (estrellasCerradas) { alert('El plazo para elegir tus 5 Estrellas ya ha cerrado (2 horas antes del partido).'); return; }
        setGuardando(true);
        try {
            await setDoc(doc(db, "estrellas_seleccion", jornada.id, "jugadores", user), {
                jugadores: seleccion, guardadoEn: serverTimestamp(), usuario: user
            }, { merge: true });
            setGuardado(true);
        } catch(e) { console.error(e); }
        setGuardando(false);
    };

    var posiciones = ['Todos','Portero','Defensa','Centrocampista','Mediapunta','Delantero'];
    var plantillaFiltrada = posFiltro === 'Todos' ? plantilla : plantilla.filter(function(j) { return j.posicion === posFiltro; });

    return (
        <div style={{position:'fixed',inset:0,background:'rgba(0,10,40,0.75)',zIndex:200,display:'flex',alignItems:'flex-end',justifyContent:'center'}}
            onClick={function(e) { if (e.target === e.currentTarget) onClose(); }}>
            <div style={{background:'#fff',borderRadius:'24px 24px 0 0',width:'100%',maxWidth:520,
                maxHeight:'90vh',display:'flex',flexDirection:'column',animation:'slideIn .3s ease'}}>

                {/* Header */}
                <div style={{background:'#001F6B',borderRadius:'24px 24px 0 0',padding:'18px 20px 0'}}>
                    <div style={{display:'flex',alignItems:'center',marginBottom:12}}>
                        <div>
                            <p style={{fontFamily:"'Teko',sans-serif",fontSize:22,fontWeight:700,color:'#FFD700',letterSpacing:2}}>MIS 5 ESTRELLAS</p>
                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(255,255,255,0.4)'}}>
                                J{jornada && jornada.numeroJornada} · {seleccion.length}/5 seleccionados
                            </p>
                        </div>
                        <button onClick={onClose} style={{marginLeft:'auto',background:'none',border:'none',color:'rgba(255,255,255,0.3)',fontSize:22,cursor:'pointer'}}>✕</button>
                    </div>
                    {/* Tabs */}
                    {estrellasCerradas && (
                        <div style={{background:'rgba(230,57,70,0.2)',borderRadius:10,padding:'8px 12px',marginBottom:10}}>
                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'#ff8a8a',textAlign:'center'}}>
                                ⏰ El plazo para elegir tus 5 Estrellas ha cerrado (2h antes del partido). Ya no puedes modificar tu selección.
                            </p>
                        </div>
                    )}
                    {!estrellasCerradas && limiteEstrellas && horasRestantes !== null && (horasRestantes < 4) && (
                        <div style={{background:'rgba(255,215,0,0.15)',borderRadius:10,padding:'6px 12px',marginBottom:10}}>
                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'#FFD700',textAlign:'center'}}>
                                ⏱️ Cierre en {horasRestantes}h {minutosRestantes}m — elige antes de que se publique el 11 inicial
                            </p>
                        </div>
                    )}
                    <div style={{display:'flex',gap:0}}>
                        {[['elegir','Elegir jugadores'],['puntos','Tabla de ⭐']].map(function(t) {
                            return (
                                <button key={t[0]} onClick={function() { setTab(t[0]); }}
                                    style={{flex:1,padding:'10px 0',border:'none',cursor:'pointer',
                                        background:'transparent',borderBottom: tab===t[0] ? '3px solid #FFD700' : '3px solid transparent',
                                        fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:2,textTransform:'uppercase',
                                        color: tab===t[0] ? '#FFD700' : 'rgba(255,255,255,0.35)'}}>
                                    {t[1]}
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* Contenido */}
                <div style={{flex:1,overflowY:'auto',padding:'16px'}}>
                    {tab === 'puntos' ? (
                        <div>
                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:G.deepBlue,opacity:.6,marginBottom:16,lineHeight:1.6}}>
                                Cada acción de tus jugadores elegidos suma o resta estrellas. El ranking de estrellas de la jornada determina cuántos puntos ganas para la clasificación general (1º→5pts, 2º→4pts, ...).
                            </p>
                            {TABLA_PUNTOS_ESTRELLAS.map(function(r,i) {
                                return (
                                    <div key={i} style={{display:'flex',alignItems:'center',gap:12,padding:'10px 0',borderBottom:'1px solid rgba(0,31,107,0.05)'}}>
                                        <span style={{fontFamily:"'Inter',sans-serif",fontSize:13,color:G.deepBlue,flex:1}}>{r.accion}</span>
                                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:18,fontWeight:700,
                                            color: r.estrellas > 0 ? '#FFD700' : G.danger}}>
                                            {r.disponible === false ? 'No disponible en API' : ((r.estrellas > 0 ? '+' : '') + r.estrellas + ' ⭐')}
                                        </span>
                                    </div>
                                );
                            })}
                        </div>
                    ) : (
                        <>
                            {/* Selección actual — con foto */}
                            <div style={{display:'flex',gap:8,flexWrap:'wrap',marginBottom:16,minHeight:36}}>
                                {seleccion.map(function(j,i) {
                                    return (
                                        <span key={i} onClick={function() { toggle(j); }}
                                            style={{display:'inline-flex',alignItems:'center',gap:6,
                                                background:G.golden,color:'#001F6B',borderRadius:20,padding:'4px 12px 4px 4px',
                                                fontFamily:"'Inter',sans-serif",fontSize:12,fontWeight:600,
                                                cursor: (!estrellasCerradas && (!jornada || jornada.estado==='Abierta')) ? 'pointer' : 'default',
                                                opacity: estrellasCerradas ? 0.6 : 1}}>
                                            {getFotoJugador(j) ? (
                                                <img src={getFotoJugador(j)} alt="" style={{width:20,height:20,borderRadius:'50%',objectFit:'cover',background:'#fff'}}
                                                    onError={function(e){e.target.style.display='none';}} />
                                            ) : <span>⭐</span>}
                                            {j.nombre}
                                        </span>
                                    );
                                })}
                                {seleccion.length === 0 && <span style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(0,31,107,0.35)'}}>Ningún jugador seleccionado aún</span>}
                            </div>

                            {/* Filtro posición */}
                            <div style={{display:'flex',gap:6,flexWrap:'wrap',marginBottom:14}}>
                                {posiciones.map(function(p) {
                                    return (
                                        <button key={p} onClick={function() { setPosicion(p); }}
                                            style={{padding:'5px 12px',borderRadius:20,border:'none',cursor:'pointer',
                                                fontFamily:"'Inter',sans-serif",fontSize:11,fontWeight:600,
                                                background: posFiltro===p ? G.deepBlue : '#f0f0f0',
                                                color: posFiltro===p ? '#FFD700' : G.deepBlue}}>
                                            {p}
                                        </button>
                                    );
                                })}
                            </div>

                            {/* Jugadores */}
                            {(!jornada || jornada.estado === 'Abierta') && (
                                <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(130px,1fr))',gap:10,marginBottom:16}}>
                                    {plantillaFiltrada.map(function(j,i) {
                                        var sel = !!seleccion.find(function(s) { return s.nombre===j.nombre; });
                                        var lleno = seleccion.length >= 5 && !sel;
                                        return (
                                            <button key={i} onClick={function() { toggle(j); }} disabled={lleno}
                                                style={{padding:'12px 8px',borderRadius:14,cursor:lleno?'not-allowed':'pointer',
                                                    border: sel?'2px solid #FFD700':'1.5px solid rgba(0,31,107,0.1)',
                                                    background: sel?'rgba(255,215,0,0.1)':'#f8f8f8',
                                                    opacity: lleno?0.4:1,textAlign:'center',display:'flex',flexDirection:'column',alignItems:'center',gap:6}}>
                                                {getFotoJugador(j) ? (
                                                    <img src={getFotoJugador(j)} alt={j.nombre}
                                                        style={{width:44,height:44,borderRadius:'50%',objectFit:'cover',border: sel?'2px solid #FFD700':'2px solid rgba(0,31,107,0.1)'}}
                                                        onError={function(e){e.target.style.display='none';}} />
                                                ) : (
                                                    <div style={{width:44,height:44,borderRadius:'50%',background:'rgba(0,31,107,0.08)',
                                                        display:'flex',alignItems:'center',justifyContent:'center',
                                                        fontFamily:"'Teko',sans-serif",fontSize:16,color:G.deepBlue}}>
                                                        {j.dorsal}
                                                    </div>
                                                )}
                                                <span style={{fontFamily:"'Inter',sans-serif",fontSize:11,fontWeight:600,color:G.deepBlue,lineHeight:1.2}}>{j.nombre}</span>
                                                <span style={{fontFamily:"'Inter',sans-serif",fontSize:9,color:'rgba(0,31,107,0.4)'}}>{j.posicion}</span>
                                                {sel && <span style={{fontSize:14}}>⭐</span>}
                                            </button>
                                        );
                                    })}
                                </div>
                            )}

                            {jornada && jornada.estado !== 'Abierta' ? (
                                <div style={{background:'rgba(0,31,107,0.05)',border:'1px solid rgba(0,31,107,0.12)',borderRadius:12,padding:16,textAlign:'center'}}>
                                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:16,color:G.deepBlue,letterSpacing:2}}>🔒 JORNADA CERRADA</p>
                                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:G.deepBlue,opacity:.5,marginTop:4}}>Tu selección quedó fijada al cerrarse la jornada.</p>
                                </div>
                            ) : seleccion.length > 0 && (
                                <button onClick={guardar} disabled={guardando}
                                    style={{width:'100%',fontFamily:"'Teko',sans-serif",fontSize:'1.1rem',letterSpacing:2,
                                        background: guardado ? '#10b981' : G.deepBlue, color: guardado ? '#fff' : '#FFD700',
                                        border:'none',borderRadius:30,padding:14,cursor:'pointer'}}>
                                    {guardando ? 'GUARDANDO...' : guardado ? '✅ GUARDADO — ACTUALIZAR' : 'CONFIRMAR ' + seleccion.length + ' ESTRELLA' + (seleccion.length>1?'S':'')}
                                </button>
                            )}
                        </>
                    )}
                </div>
            </div>
        </div>
    );
};

const PorraAnualModal = ({ user, onClose }) => {
    var G = styles.colors;
    var [ascenso, setAscenso] = useState('');
    var [puesto, setPuesto] = useState('');
    var [guardado, setGuardado] = useState(false);
    var [cargando, setCargando] = useState(true);
    var [mensaje, setMensaje] = useState('');

    useEffect(function() {
        getDoc(doc(db, "porraAnual2627", user)).then(function(snap) {
            if (snap.exists()) {
                var d = snap.data();
                setAscenso(d.ascenso || '');
                setPuesto(d.puesto || '');
                setGuardado(true);
            }
            setCargando(false);
        });
    }, [user]);

    var guardar = async function() {
        if (!ascenso || !puesto) { setMensaje('Rellena ambas opciones.'); return; }
        try {
            await setDoc(doc(db, "porraAnual2627", user), {
                ascenso: ascenso, puesto: Number(puesto), usuario: user, guardadoEn: serverTimestamp()
            }, { merge: true });
            setGuardado(true);
            setMensaje('✅ Porra anual guardada. Puedes modificarla hasta que empiece la J6.');
        } catch(e) { setMensaje('❌ Error: ' + e.message); }
    };

    return (
        <div style={{position:'fixed',inset:0,background:'rgba(0,10,40,0.7)',zIndex:200,display:'flex',alignItems:'flex-end',justifyContent:'center'}}
            onClick={function(e) { if (e.target === e.currentTarget) onClose(); }}>
            <div style={{background:'#fff',borderRadius:'24px 24px 0 0',padding:'28px 24px 40px',width:'100%',maxWidth:500,animation:'slideIn .3s ease'}}>
                <div style={{display:'flex',alignItems:'center',marginBottom:20}}>
                    <div>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:22,fontWeight:700,color:G.deepBlue,letterSpacing:2}}>PORRA ANUAL 26/27</p>
                        <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:G.deepBlue,opacity:.5}}>Hasta 20 puntos extra · Cierra antes de la Jornada 6</p>
                    </div>
                    <button onClick={onClose} style={{marginLeft:'auto',background:'none',border:'none',fontSize:22,color:'rgba(0,31,107,0.3)',cursor:'pointer'}}>✕</button>
                </div>

                {cargando ? <p style={{textAlign:'center',color:G.deepBlue,fontFamily:"'Teko',sans-serif",letterSpacing:2}}>CARGANDO...</p> : (
                    <>
                        {/* Pregunta 1: ¿Asciende? */}
                        <div style={{marginBottom:20}}>
                            <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:10}}>
                                <p style={{fontFamily:"'Teko',sans-serif",fontSize:15,letterSpacing:2,color:G.deepBlue,textTransform:'uppercase',flex:1}}>¿Asciende la UDLP?</p>
                                <span style={{fontFamily:"'Teko',sans-serif",fontSize:13,background:'rgba(0,31,107,0.08)',color:G.deepBlue,padding:'3px 10px',borderRadius:10}}>5 PTS</span>
                            </div>
                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:G.deepBlue,opacity:.45,marginBottom:10}}>
                                Si asciende por playoff, se cuenta la posición antes del playoff.
                            </p>
                            <div style={{display:'flex',gap:10}}>
                                {['Sí asciende','No asciende'].map(function(op) {
                                    var sel = ascenso === op;
                                    return (
                                        <button key={op} onClick={function() { setAscenso(op); setGuardado(false); }}
                                            style={{flex:1,padding:'14px 0',borderRadius:12,border: sel ? 'none' : '1.5px solid rgba(0,31,107,0.15)',
                                                background: sel ? '#001F6B' : '#f8f8f8',fontFamily:"'Teko',sans-serif",
                                                fontSize:16,fontWeight:700,letterSpacing:1,color: sel ? '#FFD700' : 'rgba(0,31,107,0.4)',cursor:'pointer'}}>
                                            {op}
                                        </button>
                                    );
                                })}
                            </div>
                        </div>

                        {/* Pregunta 2: Puesto */}
                        <div style={{marginBottom:20}}>
                            <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:10}}>
                                <p style={{fontFamily:"'Teko',sans-serif",fontSize:15,letterSpacing:2,color:G.deepBlue,textTransform:'uppercase',flex:1}}>Puesto final en liga</p>
                                <span style={{fontFamily:"'Teko',sans-serif",fontSize:13,background:'rgba(0,31,107,0.08)',color:G.deepBlue,padding:'3px 10px',borderRadius:10}}>10 PTS · o 20 si aciertas ambas</span>
                            </div>
                            <div style={{display:'grid',gridTemplateColumns:'repeat(6,1fr)',gap:6}}>
                                {Array.from({length:22},function(_,i) { return i+1; }).map(function(n) {
                                    var sel = Number(puesto) === n;
                                    return (
                                        <button key={n} onClick={function() { setPuesto(n); setGuardado(false); }}
                                            style={{padding:'10px 0',borderRadius:10,border: sel ? 'none' : '1px solid rgba(0,31,107,0.12)',
                                                background: sel ? '#001F6B' : '#f8f8f8',fontFamily:"'Teko',sans-serif",
                                                fontSize:16,fontWeight:700,color: sel ? '#FFD700' : 'rgba(0,31,107,0.5)',cursor:'pointer'}}>
                                            {n}
                                        </button>
                                    );
                                })}
                            </div>
                        </div>

                        {mensaje && <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color: mensaje.startsWith('✅') ? '#10b981' : G.danger,marginBottom:12,textAlign:'center'}}>{mensaje}</p>}
                        <button onClick={guardar}
                            style={{width:'100%',fontFamily:"'Teko',sans-serif",fontSize:'1.1rem',letterSpacing:2,
                                background: guardado ? '#10b981' : G.deepBlue,color:'#fff',border:'none',borderRadius:30,padding:14,cursor:'pointer'}}>
                            {guardado ? '✅ GUARDADO' : 'GUARDAR PORRA ANUAL'}
                        </button>
                    </>
                )}
            </div>
        </div>
    );
};


// ============================================================================
// --- CIERRE DE JORNADA · PANTALLA DE TRANSICIÓN DE UNA SOLA VISTA -----------
// Aparece una vez por jugador cuando la jornada de Segunda queda Finalizada.
// No sustituye la clasificación: es una pantalla narrativa de cierre.
// Si Primera aún no ha terminado, deja explícitamente el multiplicador de
// El Otro como PENDIENTE y muestra qué partidos quedan por jugar.
// ============================================================================
const CierreJornadaTransicion = ({ user, jornada, userProfiles, teamLogos, onIrEstrellas, onCerrar }) => {
    const G = styles.colors;
    const [visible, setVisible] = useState(false);
    const [cargando, setCargando] = useState(true);
    const [miPronostico, setMiPronostico] = useState(null);
    const [topEstrellas, setTopEstrellas] = useState([]);
    const [partidosPrimera, setPartidosPrimera] = useState([]);
    const [resultadoOtro, setResultadoOtro] = useState(null);
    const [premio, setPremio] = useState('0.00');
    const [ganador, setGanador] = useState(false);
    const [cobroConfirmado, setCobroConfirmado] = useState(false);

    useEffect(function() {
        var activo = true;
        if (!user || !jornada || jornada.estado !== 'Finalizada') { setCargando(false); return function(){}; }
        (async function() {
            try {
                var vistoRef = doc(db, 'cierres_jornada', jornada.id, 'usuarios', user);
                var vistoSnap = await getDoc(vistoRef);
                if (vistoSnap.exists()) { if (activo) { setCargando(false); setVisible(false); if (onCerrar) onCerrar(); } return; }

                var pSnap = await getDoc(doc(db, 'pronosticos', jornada.id, 'jugadores', user));
                var p = pSnap.exists() ? pSnap.data() : null;
                if (activo) setMiPronostico(p);

                var todosSnap = await getDocs(collection(db, 'pronosticos', jornada.id, 'jugadores'));
                var exactos = [];
                todosSnap.forEach(function(d) {
                    var pd = d.data() || {};
                    if (pd.noContabilizado) return;
                    if (parseInt(pd.golesLocal) === parseInt(jornada.resultadoLocal) && parseInt(pd.golesVisitante) === parseInt(jornada.resultadoVisitante)) exactos.push(d.id);
                });
                var costeJornada = jornada.esVip ? APUESTA_VIP : APUESTA_NORMAL;
                var jugadoresValidos = todosSnap.docs.filter(function(d){ return !(d.data() || {}).noContabilizado; });
                var bote = jornada.boteTotal !== undefined ? Number(jornada.boteTotal) : Number(jornada.bote || 0) + jugadoresValidos.length * costeJornada;
                var esGanador = (jornada.ganadores || []).indexOf(user) !== -1 || exactos.indexOf(user) !== -1;
                if (activo) {
                    setGanador(esGanador);
                    var premioOficial = jornada.premioPorGanador !== undefined ? Number(jornada.premioPorGanador) : (exactos.length ? bote / exactos.length : 0);
                    setPremio(esGanador ? premioOficial.toFixed(2) : '0.00');
                }

                var cobroSnap = await getDoc(doc(db,'premios_jornada',jornada.id,'usuarios',user));
                if (activo) setCobroConfirmado(cobroSnap.exists() && !!cobroSnap.data().recibido);

                var estSnap = await getDocs(collection(db, 'estrellas_resultados', jornada.id, 'jugadores'));
                var est = estSnap.docs.map(function(d){ return { id:d.id, ...d.data() }; })
                    .sort(function(a,b){
                        if ((b.estrellasJornada||0) !== (a.estrellasJornada||0)) return (b.estrellasJornada||0)-(a.estrellasJornada||0);
                        return (a.id||'').localeCompare(b.id||'');
                    }).slice(0,5);
                if (activo) setTopEstrellas(est);

                var partidos = await buscarJornadaCompletaPrimera(fechaAString(getFechaPartidoISO(jornada) || new Date().toISOString()), 7);
                if (activo) setPartidosPrimera(partidos || []);

                if (p && p.elOtroActivado && p.elOtroFixtureId && p.elOtroEquipoUsado && API_FOOTBALL_KEY) {
                    try {
                        var rf = await fetch('https://v3.football.api-sports.io/fixtures?id=' + p.elOtroFixtureId, { headers:{'x-apisports-key':API_FOOTBALL_KEY} });
                        var df = await rf.json();
                        if (df.response && df.response[0]) {
                            var fx = df.response[0];
                            var estC = fx.fixture.status.short;
                            var final = ['FT','AET','PEN'].indexOf(estC) !== -1;
                            var esLocal = nombresSonSimilares(fx.teams.home.name, p.elOtroEquipoUsado);
                            var gf = esLocal ? fx.goals.home : fx.goals.away;
                            var gc = esLocal ? fx.goals.away : fx.goals.home;
                            if (activo) setResultadoOtro({ finalizado:final, estado:estC, equipo:p.elOtroEquipoUsado, rival:esLocal?fx.teams.away.name:fx.teams.home.name, golesEquipo:gf, golesRival:gc, resultado: final ? (gf>gc?'gana':gf<gc?'pierde':'empata') : 'pendiente' });
                        }
                    } catch(e) { console.warn('Cierre jornada — error El Otro:', e.message); }
                }
                if (activo) { setCargando(false); setVisible(true); }
            } catch(e) {
                console.warn('Cierre jornada:', e.message);
                if (activo) setCargando(false);
            }
        })();
        return function(){ activo = false; };
    }, [user, jornada, onCerrar]);

    var cerrar = async function() {
        try { await setDoc(doc(db, 'cierres_jornada', jornada.id, 'usuarios', user), { vistoEn: serverTimestamp() }, { merge:true }); } catch(e) {}
        setVisible(false);
        if (onCerrar) onCerrar();
    };

    if (cargando || !visible) return null;
    var pendientes = partidosPrimera.filter(function(p){ return !['FT','AET','PEN'].includes(p.estadoCorto); });
    var terminadoOtro = resultadoOtro && resultadoOtro.finalizado;
    var estadoOtroColor = !resultadoOtro ? 'rgba(255,255,255,.45)' : resultadoOtro.resultado==='gana' ? '#10b981' : resultadoOtro.resultado==='pierde' ? '#e63946' : resultadoOtro.resultado==='empata' ? '#FFD700' : '#FFD700';

    return (
        <div style={{position:'fixed',inset:0,zIndex:99999,background:'linear-gradient(145deg,#00113d 0%,#001F6B 55%,#003da8 100%)',display:'flex',alignItems:'center',justifyContent:'center',padding:18,overflowY:'auto'}}>
            <div style={{width:'100%',maxWidth:520,background:'#f7f9ff',borderRadius:24,boxShadow:'0 30px 80px rgba(0,0,0,.45)',overflow:'hidden',position:'relative'}}>
                <div style={{background:'linear-gradient(135deg,#001F6B,#003da8)',padding:'28px 22px 22px',textAlign:'center'}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:4,color:'rgba(255,255,255,.55)',margin:0}}>CIERRE · JORNADA {jornada.numeroJornada}</p>
                    <div style={{fontSize:48,margin:'6px 0'}}>🏟️</div>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:28,fontWeight:700,color:'#FFD700',letterSpacing:2,margin:0}}>{jornada.resultadoLocal} — {jornada.resultadoVisitante}</p>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(255,255,255,.55)',marginTop:6}}>La UDLP ya ha cerrado su jornada. Esto es lo que tienes que saber.</p>
                </div>

                <div style={{padding:20}}>
                    <div style={{background:ganador?'rgba(255,215,0,.16)':'rgba(0,31,107,.05)',border:'1px solid '+(ganador?'rgba(255,180,0,.35)':'rgba(0,31,107,.08)'),borderRadius:16,padding:16,textAlign:'center',marginBottom:14}}>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:23,fontWeight:700,color:G.deepBlue,letterSpacing:1,marginBottom:4}}>{ganador ? '🏆 ¡HAS GANADO LA JORNADA!' : 'JORNADA CERRADA'}</p>
                        <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:G.deepBlue,opacity:.62,lineHeight:1.5}}>{ganador ? 'Has clavado el resultado y tienes premio.' : 'El reparto económico ya está resuelto. Tus puntos que ves ahora son provisionales hasta el cierre total.'}</p>
                        {ganador && <p style={{fontFamily:"'Teko',sans-serif",fontSize:30,fontWeight:700,color:'#b8860b',marginTop:8}}>{premio}€</p>}
                    </div>
                    {miPronostico && (
                        <div style={{background:'rgba(0,31,107,.05)',border:'1px solid rgba(0,31,107,.08)',borderRadius:14,padding:13,marginBottom:14,textAlign:'center'}}>
                            <p style={{fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:2,color:'#001F6B',marginBottom:3}}>📊 TUS PUNTOS</p>
                            <p style={{fontFamily:"'Teko',sans-serif",fontSize:28,fontWeight:700,color:'#001F6B',margin:0}}>+{Number(miPronostico.puntosProvisionales||miPronostico.puntosObtenidos||0)}</p>
                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(0,31,107,.5)',marginTop:3}}>provisionales hasta el cierre total de la jornada</p>
                        </div>
                    )}

                    {ganador && (
                        <div style={{background:'rgba(16,185,129,.08)',border:'1px solid rgba(16,185,129,.22)',borderRadius:14,padding:13,marginBottom:14}}>
                            <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,color:'#0f8a61',letterSpacing:1,marginBottom:6}}>💸 CONFIRMA TU PREMIO</p>
                            <button disabled={cobroConfirmado} onClick={async function(){try{await setDoc(doc(db,'premios_jornada',jornada.id,'usuarios',user),{jornadaId:jornada.id,usuario:user,importe:Number(premio),recibido:true,recibidoEn:serverTimestamp()},{merge:true});setCobroConfirmado(true);}catch(e){alert('No se pudo registrar el cobro: '+e.message);}}} style={{width:'100%',borderRadius:10,padding:'10px 12px',fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:2,background:cobroConfirmado?'#10b981':'#fff',color:cobroConfirmado?'#fff':'#001F6B',cursor:cobroConfirmado?'default':'pointer',border:cobroConfirmado?'none':'1px solid rgba(0,31,107,.12)'}}>{cobroConfirmado?'✅ INGRESO CONFIRMADO':'HE RECIBIDO EL INGRESO'}</button>
                        </div>
                    )}

                    <div style={{background:'#001F6B',borderRadius:16,padding:15,marginBottom:14}}>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:2,color:'#FFD700',marginBottom:8}}>🛡️ EL OTRO EQUIPO</p>
                        {!miPronostico || !miPronostico.elOtroActivado ? (
                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(255,255,255,.62)',margin:0}}>No activaste El Otro en esta jornada.</p>
                         ) : !jornada.cierreDefinitivo ? (
                            <div>
                                <p style={{fontFamily:"'Teko',sans-serif",fontSize:17,color:'#FFD700',margin:0}}>⏳ RESULTADO PENDIENTE DE CIERRE</p>
                                <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(255,255,255,.65)',lineHeight:1.5,marginTop:5}}>El resultado de El Otro y cualquier multiplicación/división se resolverán cuando cierre por completo la jornada de Primera. Hasta entonces, tus puntos siguen siendo provisionales.</p>
                            </div>
                        ) : !resultadoOtro || !terminadoOtro ? (
                            <div>
                                <p style={{fontFamily:"'Teko',sans-serif",fontSize:17,color:'#FFD700',margin:0}}>⏳ RESULTADO PENDIENTE</p>
                                <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(255,255,255,.65)',lineHeight:1.5,marginTop:5}}>No se pudo cerrar todavía el resultado del equipo asociado.</p>
                            </div>
                        ) : (
                            <div>
                                <p style={{fontFamily:"'Teko',sans-serif",fontSize:17,color:estadoOtroColor,margin:0}}>{resultadoOtro.equipo} · {resultadoOtro.golesEquipo} — {resultadoOtro.golesRival}</p>
                                <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(255,255,255,.65)',marginTop:5}}>Resultado definitivo de El Otro. El multiplicador/divisor de esta jornada ya ha quedado aplicado.</p>
                            </div>
                        )}
                    </div>

                    {pendientes.length > 0 && miPronostico && miPronostico.elOtroActivado && (
                        <div style={{background:'rgba(255,215,0,.08)',border:'1px solid rgba(255,180,0,.25)',borderRadius:14,padding:13,marginBottom:14}}>
                            <p style={{fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:2,color:'#9a6b00',marginBottom:6}}>⏳ PRIMERA AÚN NO HA TERMINADO</p>
                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,.62)',lineHeight:1.5,marginBottom:8}}>La Jornada {jornada.numeroJornada} no se considera completamente cerrada para El Otro hasta que terminen los partidos que siguen pendientes.</p>
                            <div style={{display:'flex',flexDirection:'column',gap:4,maxHeight:125,overflowY:'auto'}}>
                                {pendientes.map(function(p){
                                    return <div key={p.fixtureId} style={{display:'flex',justifyContent:'space-between',gap:8,fontFamily:"'Inter',sans-serif",fontSize:10,color:G.deepBlue}}><span>{p.local} — {p.visitante}</span><span style={{opacity:.45,whiteSpace:'nowrap'}}>{new Date(p.fecha).toLocaleDateString('es-ES',{weekday:'short',day:'numeric',month:'short',timeZone:'Atlantic/Canary'})}</span></div>;
                                })}
                            </div>
                        </div>
                    )}

                    {topEstrellas.length > 0 && (
                        <div style={{marginBottom:14}}>
                            <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:8}}>
                                <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:2,color:G.deepBlue,margin:0}}>⭐ TOP 5 ESTRELLAS · J{jornada.numeroJornada}</p>
                                <span style={{fontFamily:"'Inter',sans-serif",fontSize:9,color:'rgba(0,31,107,.4)'}}>+5 · +4 · +3 · +2 · +1</span>
                            </div>
                            <div style={{display:'flex',flexDirection:'column',gap:5}}>
                                {topEstrellas.map(function(r,i){
                                    var perf=userProfiles[r.id]||{};
                                    var puntos = Number(r.puntosRanking||0);
                                    return <div key={r.id} style={{display:'flex',alignItems:'center',gap:8,padding:'7px 9px',background:i===0?'rgba(255,215,0,.1)':'rgba(0,31,107,.025)',borderRadius:9}}>
                                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:14,fontWeight:700,color:G.deepBlue,width:20,textAlign:'center'}}>{puntos ? '+'+puntos : '—'}</span>
                                        <IconoPerfil perfil={perf} size={24} />
                                        <span style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:G.deepBlue,flex:1}}>{nombreVisible(r.id,perf)}</span>
                                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:14,color:'#b8860b',fontWeight:700}}>{r.estrellasJornada||0}⭐</span>
                                    </div>;
                                })}
                            </div>
                            <button onClick={function(){ onIrEstrellas(); cerrar(); }} style={{marginTop:9,width:'100%',border:'none',background:'rgba(0,31,107,.06)',color:G.deepBlue,borderRadius:10,padding:9,fontFamily:"'Teko',sans-serif",letterSpacing:1,cursor:'pointer'}}>VER LA CLASIFICACIÓN DE ESTRELLAS →</button>
                        </div>
                    )}

                    <button onClick={cerrar} style={{width:'100%',border:'none',background:G.deepBlue,color:'#FFD700',borderRadius:24,padding:13,fontFamily:"'Teko',sans-serif",fontSize:15,letterSpacing:2,cursor:'pointer'}}>CONTINUAR</button>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:9,color:'rgba(0,31,107,.35)',textAlign:'center',marginTop:8}}>Esta pantalla aparece una sola vez para ti.</p>
                </div>
            </div>
        </div>
    );
};


// ============================================================================
// --- RIFAS · helpers globales ----------------------------------------------
// ============================================================================
function numeroPapeleta2Cifras(n) {
    var s = String(n);
    return s.length < 2 ? '0' + s : s;
}

var RIFA_ESTADOS_INFO = {
    abierta:          { label: 'ABIERTA',              color: '#d4a017', emoji: '🟡' },
    casi_completa:    { label: 'CASI COMPLETA',        color: '#e07b28', emoji: '🟠' },
    completa:         { label: 'COMPLETA',             color: '#e63946', emoji: '🔴' },
    pendiente_sorteo: { label: 'PENDIENTE DE SORTEO',  color: '#2563eb', emoji: '🔵' },
    entregada:        { label: 'ENTREGADA · CERRADA', color: '#0f8a61', emoji: '🏁' },
    sorteada:         { label: 'SORTEADA',             color: '#10b981', emoji: '🟢' },
    finalizada:       { label: 'FINALIZADA',           color: '#333333', emoji: '⚫' },
    activa:           { label: 'ABIERTA',              color: '#d4a017', emoji: '🟡' }, // compatibilidad con rifas antiguas
};

function infoEstadoRifa(rifa) {
    var estado = rifa && rifa.estado ? rifa.estado : 'abierta';
    var vendidas = Number(rifa && rifa.papeletasVendidas ? rifa.papeletasVendidas : 0);
    var total = Number(rifa && rifa.totalPapeletas ? rifa.totalPapeletas : 100);
    if ((estado === 'abierta' || estado === 'activa') && vendidas >= total * 0.8 && vendidas < total) estado = 'casi_completa';
    return RIFA_ESTADOS_INFO[estado] || RIFA_ESTADOS_INFO.abierta;
}

// Busca el próximo partido de la UDLP jugando COMO LOCAL — es el partido de
// referencia del sorteo (las dos últimas cifras de la asistencia oficial).
async function buscarProximoPartidoLocalUDLP() {
    if (!API_FOOTBALL_KEY) return null;
    try {
        var url = 'https://v3.football.api-sports.io/fixtures?team=' + API_TEAM_ID_UDLP + '&season=2026&next=10';
        var res = await fetch(url, { headers: { 'x-apisports-key': API_FOOTBALL_KEY } });
        var data = await res.json();
        var lista = data.response || [];
        for (var i = 0; i < lista.length; i++) {
            var p = lista[i];
            if (p.teams && p.teams.home && p.teams.home.id === API_TEAM_ID_UDLP) {
                return { fixtureId: p.fixture.id, fecha: p.fixture.date, local: p.teams.home.name, visitante: p.teams.away.name,
                    estadio: p.fixture.venue && p.fixture.venue.name ? p.fixture.venue.name : '' };
            }
        }
        return null;
    } catch(e) { console.warn('Próximo partido local UDLP:', e.message); return null; }
}

// ============================================================================
// --- RIFAS · PANTALLA DEL JUGADOR ------------------------------------------
// 100 papeletas (00–99). El ganador sale de las dos últimas cifras de la
// asistencia oficial del siguiente partido de la UDLP como LOCAL.
// ============================================================================
const RifasScreen = ({ currentUser, userProfiles }) => {
    var [rifa, setRifa] = useState(null);
    var [historialRifas, setHistorialRifas] = useState([]);
    var [papeletas, setPapeletas] = useState({});         // numero -> {usuario, metodo, ...}
    var [saldo, setSaldo] = useState(0);
    var [seleccion, setSeleccion] = useState([]);          // números elegidos para comprar
    var [comprando, setComprando] = useState(false);
    var [msg, setMsg] = useState('');
    var [cargandoRifa, setCargandoRifa] = useState(true);

    // Rifa "vigente": la más reciente que no esté finalizada.
    useEffect(function() {
        var unsub = onSnapshot(collection(db, 'rifas'), function(snap) {
            var todas = snap.docs.map(function(d) { return { id: d.id, ...d.data() }; });
            todas.sort(function(a, b) {
                var fa = a.creadaEn && a.creadaEn.seconds ? a.creadaEn.seconds : 0;
                var fb = b.creadaEn && b.creadaEn.seconds ? b.creadaEn.seconds : 0;
                return fb - fa;
            });
            var vigente = todas.find(function(r) { return r.estado !== 'finalizada'; }) || null;
            setRifa(vigente);
            setHistorialRifas(todas.filter(function(r) { return r.estado === 'finalizada'; }));
            setCargandoRifa(false);
        }, function() { setCargandoRifa(false); });
        return function() { unsub(); };
    }, []);

    // Papeletas de la rifa vigente, en vivo.
    var rifaIdActual = rifa ? rifa.id : null;
    useEffect(function() {
        if (!rifaIdActual) { setPapeletas({}); return; }
        var unsub = onSnapshot(collection(db, 'rifas', rifaIdActual, 'papeletas'), function(snap) {
            var m = {};
            var ahoraPap = Date.now();
            snap.forEach(function(d) {
                var pd = d.data();
                if (!papeletaExternaCaducada(pd, ahoraPap)) m[d.id] = pd;
            });
            setPapeletas(m);
        }, function(){});
        return function() { unsub(); };
    }, [rifaIdActual]);

    // Saldo de rifas del usuario (dinero de premios destinado voluntariamente).
    useEffect(function() {
        if (!currentUser) return;
        var unsub = onSnapshot(doc(db, 'saldos_rifa', currentUser), function(snap) {
            setSaldo(snap.exists() ? Number(snap.data().saldo || 0) : 0);
        }, function(){});
        return function() { unsub(); };
    }, [currentUser]);

    var precio = rifa ? Number(rifa.precio || 0) : 0;
    var total = rifa ? Number(rifa.totalPapeletas || 100) : 100;
    var vendidas = Object.keys(papeletas).length;
    var costeSeleccion = Number((seleccion.length * precio).toFixed(2));
    var rifaAbierta = !!(rifa && (rifa.estado === 'abierta' || rifa.estado === 'activa' || !rifa.estado ||
        (rifa.estado === 'programada' && Number(rifa.aperturaEn || 0) <= Date.now())));
    var rifaProgramada = !!(rifa && rifa.estado === 'programada' && Number(rifa.aperturaEn || 0) > Date.now());

    var toggleNumero = function(num) {
        if (!rifaAbierta || papeletas[num]) return;
        setSeleccion(function(prev) {
            return prev.indexOf(num) !== -1 ? prev.filter(function(n) { return n !== num; }) : prev.concat([num]);
        });
    };

    // Compra transaccional: ningún número puede comprarse dos veces, y el
    // saldo nunca puede quedar en negativo. Todo o nada.
    var comprar = async function(metodo) {
        // 💶 DOBLE CONFIRMACIÓN: compra con dinero y sin devolución.
        if (seleccion.length) {
            var okCompra = window.confirm('CONFIRMA TU COMPRA:\n\n🎟️ Números: ' + seleccion.join(', ') + '\n💶 Total: ' + costeSeleccion.toFixed(2) + '€ (' + (metodo === 'saldo' ? 'con tu saldo de premios' : 'por Bizum') + ')\n\n⚠️ Las papeletas compradas no se devuelven ni se cambian.\n\n¿Es esto lo que quieres hacer?');
            if (!okCompra) return;
        }
        if (!rifa || !seleccion.length || comprando) return;
        if (metodo === 'saldo' && saldo < costeSeleccion) { setMsg('❌ Saldo insuficiente para esa selección.'); return; }
        setComprando(true); setMsg('');
        try {
            await runTransaction(db, async function(tx) {
                var rifaRef = doc(db, 'rifas', rifa.id);
                var rifaSnap = await tx.get(rifaRef);
                if (!rifaSnap.exists()) throw new Error('La rifa ya no existe.');
                var rd = rifaSnap.data();
                var aperturaOk = rd.estado === 'programada' && Number(rd.aperturaEn || 0) <= Date.now();
                if (rd.estado && rd.estado !== 'abierta' && rd.estado !== 'activa' && !aperturaOk) throw new Error('La rifa ya no admite compras.');
                var refsPapeletas = seleccion.map(function(n) { return doc(db, 'rifas', rifa.id, 'papeletas', n); });
                for (var i = 0; i < refsPapeletas.length; i++) {
                    var pSnap = await tx.get(refsPapeletas[i]);
                    if (pSnap.exists() && !papeletaExternaCaducada(pSnap.data(), Date.now())) throw new Error('El número ' + seleccion[i] + ' acaba de ser comprado por otro jugador.');
                }
                var saldoRef = doc(db, 'saldos_rifa', currentUser);
                var saldoTx = 0;
                if (metodo === 'saldo') {
                    var sSnap = await tx.get(saldoRef);
                    saldoTx = sSnap.exists() ? Number(sSnap.data().saldo || 0) : 0;
                    if (saldoTx < costeSeleccion) throw new Error('Saldo insuficiente.');
                }
                for (var k = 0; k < refsPapeletas.length; k++) {
                    tx.set(refsPapeletas[k], {
                        numero: seleccion[k], usuario: currentUser, precio: precio,
                        metodo: metodo, pagoVerificado: metodo === 'saldo',
                        fecha: serverTimestamp(),
                    });
                }
                if (metodo === 'saldo') {
                    tx.set(saldoRef, { saldo: Number((saldoTx - costeSeleccion).toFixed(2)), actualizadoEn: serverTimestamp() }, { merge: true });
                }
                var nuevasVendidas = Number(rd.papeletasVendidas || 0) + seleccion.length;
                var actualizacion = { papeletasVendidas: nuevasVendidas };
                if (nuevasVendidas >= Number(rd.totalPapeletas || 100)) actualizacion.estado = 'completa';
                tx.set(rifaRef, actualizacion, { merge: true });
            });
            for (var m2 = 0; m2 < seleccion.length; m2++) {
                await addDoc(collection(db, 'saldos_rifa', currentUser, 'movimientos'), {
                    tipo: 'compra_papeleta', importe: -precio, rifaId: rifa.id,
                    numero: seleccion[m2], metodo: metodo, fecha: serverTimestamp(),
                });
            }
            setMsg(metodo === 'saldo' ? '✅ ¡Números comprados con tu saldo de premios!' : '✅ Números reservados. Recuerda enviar el Bizum al administrador.');
            setSeleccion([]);
        } catch(e) { setMsg('❌ ' + e.message); }
        setComprando(false);
    };

    if (cargandoRifa) return <LoadingSkeleton />;

    var estadoInfo = rifa ? infoEstadoRifa({ ...rifa, papeletasVendidas: vendidas }) : null;
    var misNumeros = Object.keys(papeletas).filter(function(n) { return papeletas[n].usuario === currentUser; }).sort();

    return (
        <div style={{paddingBottom:40}}>
            <h2 style={styles.title}>🎟️ RIFAS</h2>

            <button onClick={function(){ window.dispatchEvent(new CustomEvent('reabrirNovedad')); }}
                style={{width:'100%',border:'1px solid rgba(0,31,107,.12)',background:'#fff',color:'#001F6B',borderRadius:12,padding:'9px 12px',fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:2,cursor:'pointer',marginBottom:14}}>
                📢 VER ÚLTIMA NOVEDAD
            </button>

            {!rifa && (
                <div style={{background:'#fff',border:'1px solid rgba(0,31,107,.08)',borderRadius:18,padding:22,textAlign:'center'}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:18,letterSpacing:2,color:'#001F6B',marginBottom:6}}>NO HAY RIFAS ACTIVAS</p>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(0,31,107,.55)',margin:0}}>Cuando se abra una rifa la verás aquí y te avisaremos con una novedad.</p>
                </div>
            )}

            {rifa && currentUser === 'Juanma' && (rifa.estado === 'abierta' || rifa.estado === 'activa') && (
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'#b8860b',background:'rgba(255,215,0,0.1)',border:'1px dashed rgba(255,215,0,0.5)',borderRadius:8,padding:'6px 10px',textAlign:'center',marginBottom:10}}>
                    🔧 SOLO ADMIN: recuerda publicar la novedad de esta rifa (Herramientas → Novedades → tipo Rifa) para que salte el popup a todos.
                </p>
            )}
            {rifa && (
                <>
                {/* 🎽 Hero de producto, diseño nativo de la app */}
                {rifa.imagen === 'camiseta2627' && <RifaHeroCamiseta precio={rifa.precio} />}

                {/* ⏳ Cuenta atrás de apertura */}
                {rifaProgramada && (
                    <div style={{background:'linear-gradient(135deg,#001F6B,#0035b8)',borderRadius:14,padding:'14px 16px',marginBottom:12,textAlign:'center',border:'1px solid rgba(255,215,0,0.4)'}}>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:15,letterSpacing:3,color:'#FFD700',margin:0}}>🔓 LA RIFA ABRE HOY A LAS {new Date(Number(rifa.aperturaEn)).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit',timeZone:'Atlantic/Canary'})}</p>
                        <p style={{fontFamily:"'Inter',sans-serif",fontSize:10.5,color:'rgba(255,255,255,0.65)',margin:'4px 0 0'}}>Ve eligiendo tus números de la suerte… 🍀</p>
                    </div>
                )}

                {/* 📣 Invitar (lo fácil vende papeletas) */}
                <div style={{display:'flex',gap:8,marginBottom:12}}>
                    <a href={'https://wa.me/?text=' + encodeURIComponent('🎟️ ¡RIFA de la camiseta OFICIAL de la UD Las Palmas 26/27! Solo 100 números a ' + Number(rifa.precio||2).toFixed(2) + '€. Elige el tuyo aquí 👉 ' + enlacePublicoRifa(rifa.id))}
                        target="_blank" rel="noopener noreferrer"
                        style={{flex:2,textDecoration:'none',textAlign:'center',background:'#25D366',color:'#fff',borderRadius:12,padding:'11px 10px',fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:1,boxShadow:'0 4px 14px rgba(37,211,102,0.35)'}}>
                        📣 INVITAR POR WHATSAPP
                    </a>
                    <button onClick={function(){
                        try { navigator.clipboard.writeText(enlacePublicoRifa(rifa.id)); setMsg('🔗 Enlace copiado — pégalo donde quieras.'); }
                        catch(e) { window.prompt('Copia el enlace:', enlacePublicoRifa(rifa.id)); }
                    }} style={{flex:1,border:'1px solid rgba(0,31,107,0.2)',background:'#fff',color:'#001F6B',borderRadius:12,padding:'11px 8px',fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:1,cursor:'pointer'}}>🔗 COPIAR</button>
                </div>

                {/* 📅 Fecha oficial del sorteo */}
                {rifa.sorteoFixture && rifa.numeroGanador === undefined && (
                    <div style={{background:'rgba(255,215,0,0.1)',border:'1px solid rgba(212,175,55,0.4)',borderRadius:12,padding:'10px 14px',marginBottom:12}}>
                        <p style={{fontFamily:"'Inter',sans-serif",fontSize:11.5,color:'#001F6B',lineHeight:1.6,margin:0}}>
                            📅 <strong>SORTEO OFICIAL:</strong> {rifa.sorteoFixture.fecha ? new Date(rifa.sorteoFixture.fecha).toLocaleString('es-ES',{weekday:'long',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit',timeZone:'Atlantic/Canary'}) : ''} — <strong>UD Las Palmas vs {rifa.sorteoFixture.rival}</strong>. El número ganador serán las <strong>2 últimas cifras de la asistencia oficial</strong> al estadio.
                        </p>
                    </div>
                )}

                {/* 🔧 SOLO ADMIN: fijar fecha del sorteo cuando se complete la venta */}
                {currentUser === 'Juanma' && !rifa.sorteoFixture && (rifa.estado === 'completa' || rifa.estado === 'pendiente_sorteo' || vendidas >= Number(rifa.totalPapeletas || 100)) && (
                    <button onClick={async function(){
                        try {
                            var res = await fetch('https://v3.football.api-sports.io/fixtures?team=' + API_TEAM_ID_UDLP + '&next=10', { headers: { 'x-apisports-key': API_FOOTBALL_KEY } });
                            var data = await res.json();
                            var casa = (data.response || []).find(function(p) { return p.teams && p.teams.home && p.teams.home.id === API_TEAM_ID_UDLP; });
                            if (!casa) { alert('La API no devolvió un próximo partido en casa. Reintenta más tarde.'); return; }
                            await setDoc(doc(db, 'rifas', rifa.id), {
                                sorteoFixture: { fixtureId: casa.fixture.id, fecha: casa.fixture.date, rival: casa.teams.away.name },
                                estado: 'pendiente_sorteo',
                            }, { merge: true });
                            alert('📅 Sorteo fijado: UD Las Palmas vs ' + casa.teams.away.name);
                        } catch(e) { alert('Error: ' + e.message); }
                    }} style={{width:'100%',border:'1px dashed rgba(255,215,0,0.6)',background:'rgba(255,215,0,0.08)',color:'#8a6a00',borderRadius:12,padding:'10px 12px',marginBottom:12,fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:1,cursor:'pointer'}}>🔧 SOLO ADMIN · 📅 FIJAR FECHA DEL SORTEO (próximo partido en casa vía API)</button>
                )}

                {/* 🏆 Ganador resuelto */}
                {rifa.numeroGanador !== undefined && rifa.numeroGanador !== null && (function(){
                    var pg = papeletas[String(rifa.numeroGanador)] || {};
                    var soyYo = pg.usuario === currentUser;
                    return (
                        <div style={{background: soyYo ? 'linear-gradient(135deg,#FFD700,#f0c000)' : 'linear-gradient(135deg,#001F6B,#0035b8)',borderRadius:16,padding:'16px 18px',marginBottom:12,textAlign:'center',boxShadow:'0 8px 26px rgba(0,31,107,0.3)'}}>
                            <p style={{fontFamily:"'Teko',sans-serif",fontSize:soyYo?24:17,fontWeight:700,letterSpacing:2,color:soyYo?'#001F6B':'#FFD700',margin:0}}>
                                {soyYo ? '🏆 ¡¡TU NÚMERO ' + rifa.numeroGanador + ' HA GANADO LA CAMISETA!! 🏆' : '🏆 NÚMERO GANADOR: ' + rifa.numeroGanador + ' — ' + (pg.nombre || pg.usuario || '')}
                            </p>
                            {rifa.asistenciaOficial !== undefined && <p style={{fontFamily:"'Inter',sans-serif",fontSize:10.5,color:soyYo?'rgba(0,31,107,0.7)':'rgba(255,255,255,0.65)',margin:'4px 0 0'}}>Asistencia oficial: {rifa.asistenciaOficial} espectadores → 2 últimas cifras: {rifa.numeroGanador}</p>}
                            {currentUser === 'Juanma' && pg.telefono && (
                                <a href={'https://wa.me/34' + String(pg.telefono).replace(/[^0-9]/g,'') + '?text=' + encodeURIComponent('🏆 ¡¡ENHORABUENA ' + (pg.nombre || '') + '!! Tu número ' + rifa.numeroGanador + ' ha GANADO la camiseta oficial de la UD Las Palmas 26/27 en la rifa de la Porra 💛💙 Dime tu talla y te la hacemos llegar. 🎉')}
                                    target="_blank" rel="noopener noreferrer"
                                    style={{display:'inline-block',marginTop:10,textDecoration:'none',background:'#25D366',color:'#fff',borderRadius:12,padding:'9px 16px',fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:1}}>📲 AVISAR AL GANADOR POR WHATSAPP</a>
                            )}
                        </div>
                    );
                })()}

                {/* ── Cabecera de la rifa ── */}
                <div style={{background:'linear-gradient(135deg,#001F6B,#003a9e)',borderRadius:20,padding:20,marginBottom:16,position:'relative',overflow:'hidden'}}>
                    <span style={{position:'absolute',top:14,right:14,fontFamily:"'Teko',sans-serif",fontSize:11,letterSpacing:2,background:'rgba(255,255,255,.12)',color:'#fff',padding:'4px 10px',borderRadius:10}}>
                        {estadoInfo.emoji} {estadoInfo.label}
                    </span>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:4,color:'rgba(255,215,0,.6)',textTransform:'uppercase',marginBottom:6}}>RIFA DE LA PORRA</p>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:24,fontWeight:700,color:'#FFD700',letterSpacing:1,marginBottom:4}}>{rifa.titulo}</p>
                    {rifa.subtitulo && <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(255,255,255,.7)',marginBottom:8}}>{rifa.subtitulo}</p>}
                    {rifa.imagenUrl && <img src={rifa.imagenUrl} alt={rifa.titulo} style={{width:'100%',maxHeight:180,objectFit:'cover',borderRadius:12,marginBottom:10}} onError={function(e){e.target.style.display='none';}} />}
                    {rifa.descripcion && <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(255,255,255,.65)',lineHeight:1.6,marginBottom:10}}>{rifa.descripcion}</p>}
                    <div style={{display:'flex',gap:14,flexWrap:'wrap'}}>
                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:15,color:'#fff'}}>🎟️ {precio.toFixed(2)}€ / número</span>
                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:15,color:'#fff'}}>📊 {vendidas}/{total} vendidos</span>
                    </div>
                    <div style={{height:8,background:'rgba(255,255,255,.12)',borderRadius:6,marginTop:10,overflow:'hidden'}}>
                        <div style={{height:'100%',width:Math.min(100,(vendidas/total)*100)+'%',background:'#FFD700',borderRadius:6,transition:'width .5s'}} />
                    </div>
                </div>

                {/* ── Estado del sorteo ── */}
                {(rifa.estado === 'completa' || rifa.estado === 'pendiente_sorteo') && (
                    <div style={{background:'rgba(37,99,235,.07)',border:'1px solid rgba(37,99,235,.2)',borderRadius:14,padding:14,marginBottom:16}}>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:2,color:'#2563eb',textTransform:'uppercase',marginBottom:6,fontWeight:700}}>🔵 RIFA COMPLETA — PENDIENTE DE SORTEO</p>
                        {rifa.partidoReferencia ? (
                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(0,31,107,.7)',lineHeight:1.6,margin:0}}>
                                El número ganador saldrá de las <strong>dos últimas cifras de la asistencia oficial</strong> del partido <strong>{rifa.partidoReferencia.local} — {rifa.partidoReferencia.visitante}</strong>{rifa.partidoReferencia.fecha ? ' (' + new Date(rifa.partidoReferencia.fecha).toLocaleDateString('es-ES',{day:'numeric',month:'long',timeZone:'Atlantic/Canary'}) + ')' : ''}.
                            </p>
                        ) : (
                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(0,31,107,.7)',lineHeight:1.6,margin:0}}>
                                Esperando al <strong>próximo partido de la UD Las Palmas como LOCAL</strong> para determinar el número ganador con las dos últimas cifras de la asistencia oficial.
                            </p>
                        )}
                    </div>
                )}
                {(rifa.estado === 'sorteada') && rifa.numeroGanador !== undefined && (
                    <div style={{background:'linear-gradient(135deg,#0a3d2c,#10b981)',borderRadius:16,padding:18,marginBottom:16,textAlign:'center'}}>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:15,letterSpacing:3,color:'#fff',marginBottom:6}}>🏆 ¡TENEMOS GANADOR!</p>
                        {rifa.asistenciaOficial !== undefined && <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(255,255,255,.75)',marginBottom:8}}>ASISTENCIA OFICIAL: {Number(rifa.asistenciaOficial).toLocaleString('es-ES')}</p>}
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:44,fontWeight:700,color:'#FFD700',letterSpacing:6,margin:'0 0 6px'}}>{numeroPapeleta2Cifras(rifa.numeroGanador)}</p>
                        {rifa.ganadorUserId && <p style={{fontFamily:"'Teko',sans-serif",fontSize:20,color:'#fff',margin:0}}>{nombreVisible(rifa.ganadorUserId, userProfiles[rifa.ganadorUserId] || {})}</p>}
                        <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(255,255,255,.8)',marginTop:6}}>PREMIO: {rifa.descripcion || rifa.titulo}</p>
                    </div>
                )}

                {/* ── Mi saldo y mis números ── */}
                <div style={{display:'flex',gap:10,marginBottom:16}}>
                    <div style={{flex:1,background:'#fff',border:'1px solid rgba(0,31,107,.08)',borderRadius:14,padding:12}}>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:11,letterSpacing:2,color:'rgba(0,31,107,.45)',marginBottom:4}}>MI SALDO DE PREMIOS</p>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:22,fontWeight:700,color:'#001F6B',margin:0}}>{saldo.toFixed(2)}€</p>
                    </div>
                    <div style={{flex:1,background:'#fff',border:'1px solid rgba(0,31,107,.08)',borderRadius:14,padding:12}}>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:11,letterSpacing:2,color:'rgba(0,31,107,.45)',marginBottom:4}}>MIS NÚMEROS</p>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:16,fontWeight:700,color:'#001F6B',margin:0,lineHeight:1.4}}>{misNumeros.length ? misNumeros.join(' · ') : '—'}</p>
                    </div>
                </div>

                {/* ── Tablero de 100 papeletas ── */}
                <div style={{background:'#fff',border:'1px solid rgba(0,31,107,.08)',borderRadius:16,padding:14,marginBottom:16}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:2,color:'#001F6B',textTransform:'uppercase',marginBottom:10,fontWeight:700}}>ELIGE TUS NÚMEROS</p>
                    <div style={{display:'grid',gridTemplateColumns:'repeat(10,1fr)',gap:4}}>
                        {Array.from({length:total},function(_,i){return numeroPapeleta2Cifras(i);}).map(function(num){
                            var duenyo = papeletas[num];
                            var esMia = duenyo && duenyo.usuario === currentUser;
                            var sel = seleccion.indexOf(num) !== -1;
                            var fondo = esMia ? '#FFD700' : duenyo ? 'rgba(0,31,107,.85)' : sel ? '#10b981' : 'rgba(0,31,107,.05)';
                            var colorTxt = esMia ? '#001F6B' : duenyo ? 'rgba(255,255,255,.85)' : sel ? '#fff' : 'rgba(0,31,107,.55)';
                            return (
                                <button key={num} onClick={function(){toggleNumero(num);}}
                                    disabled={!rifaAbierta || !!duenyo}
                                    title={duenyo ? (esMia ? 'Tuyo' : nombreVisible(duenyo.usuario, userProfiles[duenyo.usuario] || {})) : 'Disponible'}
                                    style={{aspectRatio:'1',border:'none',borderRadius:8,background:fondo,color:colorTxt,
                                        fontFamily:"'Teko',sans-serif",fontSize:13,fontWeight:700,cursor:(!rifaAbierta||duenyo)?'default':'pointer',padding:0}}>
                                    {num}
                                </button>
                            );
                        })}
                    </div>
                    <div style={{display:'flex',gap:12,marginTop:10,flexWrap:'wrap'}}>
                        <span style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(0,31,107,.5)'}}>🟨 Tuyos</span>
                        <span style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(0,31,107,.5)'}}>🟦 Ocupados</span>
                        <span style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(0,31,107,.5)'}}>🟩 Tu selección</span>
                    </div>
                </div>

                {/* ── Panel de compra ── */}
                {rifaAbierta && seleccion.length > 0 && (
                    <div style={{background:'linear-gradient(135deg,#001F6B,#003a9e)',borderRadius:16,padding:16,marginBottom:16}}>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:2,color:'#FFD700',marginBottom:8}}>
                            {seleccion.length} NÚMERO{seleccion.length>1?'S':''} · TOTAL {costeSeleccion.toFixed(2)}€
                        </p>
                        <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(255,255,255,.65)',marginBottom:10}}>Seleccionados: {seleccion.slice().sort().join(' · ')}</p>
                        <p style={{fontFamily:"'Inter',sans-serif",fontSize:10.5,color:'rgba(0,31,107,0.55)',textAlign:'center',marginBottom:8}}>😏 ¿Seguro que no quieres <strong>algún número más</strong>? Cada uno es una oportunidad extra…</p>
                        <button onClick={function(){comprar('saldo');}} disabled={comprando || saldo < costeSeleccion}
                            style={{width:'100%',border:'none',borderRadius:10,padding:'11px 12px',fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:2,background:saldo>=costeSeleccion?'#FFD700':'rgba(255,255,255,.15)',color:saldo>=costeSeleccion?'#001F6B':'rgba(255,255,255,.4)',cursor:saldo>=costeSeleccion?'pointer':'default',marginBottom:8}}>
                            💰 PAGAR CON MI SALDO ({saldo.toFixed(2)}€)
                        </button>
                        <button onClick={function(){comprar('bizum');}} disabled={comprando}
                            style={{width:'100%',border:'1px solid rgba(255,255,255,.25)',borderRadius:10,padding:'11px 12px',fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:2,background:'transparent',color:'#fff',cursor:'pointer'}}>
                            📲 RESERVAR Y PAGAR POR BIZUM
                        </button>
                    </div>
                )}
                {msg && <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:msg.indexOf('✅')===0?'#10b981':'#e63946',marginBottom:14,textAlign:'center'}}>{msg}</p>}

                {/* ── Normas y condiciones ── */}
                <AcordeonAyuda icono="📜" titulo="Normas de la rifa" abiertoPorDefecto={false}>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(0,0,0,.65)',lineHeight:1.7,whiteSpace:'pre-wrap',margin:0}}>
                        {rifa.normas || ('· ' + total + ' números (00–' + numeroPapeleta2Cifras(total-1) + ').\n· La rifa solo se sortea cuando estén vendidos todos los números.\n· El ganador sale de las DOS ÚLTIMAS CIFRAS de la asistencia oficial del siguiente partido de la UD Las Palmas como LOCAL tras completarse la rifa.\n· Si la rifa se completa en jornada a domicilio, se espera al siguiente partido en casa.\n· Puedes pagar con tu saldo de premios de la Porra o por Bizum.')}
                    </p>
                </AcordeonAyuda>
                {rifa.fechaApertura && <p style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(0,31,107,.4)',textAlign:'center',marginTop:10}}>Rifa abierta desde el {rifa.fechaApertura}</p>}
                </>
            )}

            {/* ── Historial de rifas finalizadas ── */}
            {historialRifas.length > 0 && (
                <div style={{marginTop:20}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:3,color:'rgba(0,31,107,.4)',textTransform:'uppercase',marginBottom:10}}>Rifas anteriores</p>
                    {historialRifas.map(function(r){
                        return (
                            <div key={r.id} style={{background:'#fff',border:'1px solid rgba(0,31,107,.08)',borderRadius:14,padding:12,marginBottom:8,display:'flex',alignItems:'center',gap:10}}>
                                <span style={{fontSize:18}}>⚫</span>
                                <div style={{flex:1}}>
                                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:15,color:'#001F6B',margin:0}}>{r.titulo}</p>
                                    {r.ganadorUserId && <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,.5)',margin:0}}>🏆 {nombreVisible(r.ganadorUserId, userProfiles[r.ganadorUserId] || {})} · nº {numeroPapeleta2Cifras(r.numeroGanador)}</p>}
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
    );
};

const PremioMiJornadaCard = ({ user, jornada }) => {
    var [importe,setImporte]=useState(0), [cargando,setCargando]=useState(true);
    var [premioDoc,setPremioDoc]=useState(null);      // documento premios_jornada del usuario
    var [rifaActiva,setRifaActiva]=useState(null);    // rifa abierta a la que se puede destinar dinero
    var [modoReparto,setModoReparto]=useState(false); // selector de reparto abierto
    var [eurosARifa,setEurosARifa]=useState(0);
    var [eurosAAcumular,setEurosAAcumular]=useState(0);
    var [guardandoDestino,setGuardandoDestino]=useState(false);

    useEffect(function(){
        var activo=true;
        (async function(){
            try{
                var mi=0;
                // FUENTE DE VERDAD: el reparto guardado por el admin al cerrar
                // la jornada. Solo si la jornada es antigua y no lo tiene, se
                // recalcula como antes (comportamiento de respaldo).
                if (jornada.premioPorGanador !== undefined && Array.isArray(jornada.ganadores)) {
                    mi = jornada.ganadores.indexOf(user) !== -1 ? Number(jornada.premioPorGanador||0) : 0;
                } else {
                    var ps=await getDocs(collection(db,'pronosticos',jornada.id,'jugadores'));
                    var vals=ps.docs.map(function(d){return {id:d.id,...d.data()};}).filter(function(x){return !x.noContabilizado;});
                    var exactos=vals.filter(function(x){return parseInt(x.golesLocal)===parseInt(jornada.resultadoLocal)&&parseInt(x.golesVisitante)===parseInt(jornada.resultadoVisitante);});
                    var bote=parseFloat(jornada.bote||0)+vals.length*(jornada.esVip?APUESTA_VIP:APUESTA_NORMAL);
                    mi=exactos.some(function(x){return x.id===user})&&exactos.length?Number((bote/exactos.length).toFixed(2)):0;
                }
                var cs=await getDoc(doc(db,'premios_jornada',jornada.id,'usuarios',user));
                if(activo){setImporte(mi);setPremioDoc(cs.exists()?cs.data():null);setCargando(false);}
            }catch(e){if(activo)setCargando(false);}
        })(); return function(){activo=false;};
    },[user,jornada?.id,jornada?.premioPorGanador,jornada?.ganadores,jornada?.resultadoLocal,jornada?.resultadoVisitante,jornada?.bote,jornada?.esVip]);

    // Rifa vendible (si la hay) para poder ofrecer el destino 🎟️.
    // OJO: antes solo buscaba estado 'abierta' y las rifas creadas como
    // 'programada' (apertura con hora) o 'activa' quedaban fuera, así que el
    // botón de destinar premio a la rifa no aparecía nunca. Ahora se lee la
    // colección y se acepta cualquier rifa que YA admita compras.
    useEffect(function(){
        var unsub=onSnapshot(collection(db,'rifas'),function(snap){
            var ahora=Date.now();
            var vendible=null;
            snap.forEach(function(d){
                var r={id:d.id,...d.data()};
                var e=r.estado;
                var abiertaYa=(e!=='entregada'&&e!=='cerrada')&&(e==='abierta'||e==='activa'||!e||(e==='programada'&&Number(r.aperturaEn||0)<=ahora));
                if(abiertaYa&&!vendible)vendible=r;
            });
            setRifaActiva(vendible);
        },function(){});
        return function(){unsub();};
    },[]);

    var registrarDestino=async function(aRifa,aAcumular,aCobro){
        if(guardandoDestino)return;
        // 💶 DOBLE CONFIRMACIÓN: esta decisión mueve dinero y el usuario no
        // puede modificarla después (solo el admin puede anularla).
        var resumen=[];
        if(aCobro>0)resumen.push('💰 Recibir por Bizum: '+aCobro.toFixed(2)+'€');
        if(aAcumular>0)resumen.push('📦 Acumular para próximas jornadas: '+aAcumular.toFixed(2)+'€');
        if(aRifa>0)resumen.push('🎟️ Destinar a la rifa: '+aRifa.toFixed(2)+'€');
        var okConfirm=window.confirm('CONFIRMA LA GESTIÓN DE TU PREMIO ('+importe.toFixed(2)+'€):\n\n'+resumen.join('\n')+'\n\n⚠️ Esta decisión implica dinero y NO podrás cambiarla tú después — solo el admin puede anularla para que elijas de nuevo.\n\n¿Es esto lo que quieres hacer?');
        if(!okConfirm)return;
        setGuardandoDestino(true);
        try{
            var partes=[];
            if(aCobro>0)partes.push('cobro');
            if(aAcumular>0)partes.push('acumular');
            if(aRifa>0)partes.push('rifa');
            var datos={
                jornadaId:jornada.id,usuario:user,importe:importe,
                importeRifa:Number(aRifa.toFixed(2)),
                importeAcumular:Number(aAcumular.toFixed(2)),
                importeCobro:Number(aCobro.toFixed(2)),
                destinoElegido:partes.length>1?'mixto':(partes[0]||'cobro'),
                rifaId:aRifa>0&&rifaActiva?rifaActiva.id:null,
                recibido:false,decididoEn:serverTimestamp(),
            };
            await setDoc(doc(db,'premios_jornada',jornada.id,'usuarios',user),datos,{merge:true});
            if(aAcumular>0){
                // El dinero acumulado se convierte en saldo para pagar
                // próximas jornadas: el sistema lo descuenta solo.
                await runTransaction(db,async function(tx){
                    var aRef=doc(db,'saldos_jornadas',user);
                    var aSnap=await tx.get(aRef);
                    var saldoAct=aSnap.exists()?Number(aSnap.data().saldo||0):0;
                    tx.set(aRef,{saldo:Number((saldoAct+aAcumular).toFixed(2)),actualizadoEn:serverTimestamp()},{merge:true});
                });
                await addDoc(collection(db,'saldos_jornadas',user,'movimientos'),{
                    tipo:'ingreso_premio',importe:Number(aAcumular.toFixed(2)),
                    jornadaId:jornada.id,fecha:serverTimestamp(),
                });
            }
            if(aRifa>0){
                // El dinero destinado se convierte en saldo de rifas, con su
                // movimiento registrado para que todo quede trazable.
                await runTransaction(db,async function(tx){
                    var sRef=doc(db,'saldos_rifa',user);
                    var sSnap=await tx.get(sRef);
                    var saldoActual=sSnap.exists()?Number(sSnap.data().saldo||0):0;
                    tx.set(sRef,{saldo:Number((saldoActual+aRifa).toFixed(2)),actualizadoEn:serverTimestamp()},{merge:true});
                });
                await addDoc(collection(db,'saldos_rifa',user,'movimientos'),{
                    tipo:'ingreso_premio',importe:Number(aRifa.toFixed(2)),
                    jornadaId:jornada.id,rifaId:rifaActiva?rifaActiva.id:null,fecha:serverTimestamp(),
                });
            }
            setPremioDoc(datos);setModoReparto(false);
        }catch(e){alert('No se pudo registrar el destino del premio: '+e.message);}
        setGuardandoDestino(false);
    };

    var confirmarCobro=async function(){
        try{
            await setDoc(doc(db,'premios_jornada',jornada.id,'usuarios',user),{recibido:true,recibidoEn:serverTimestamp()},{merge:true});
            setPremioDoc(function(p){return {...(p||{}),recibido:true};});
        }catch(e){alert('No se pudo registrar el cobro: '+e.message);}
    };

    if(cargando) return null;

    var precioPapeleta=rifaActiva?Number(rifaActiva.precio||0):0;
    var destinoDecidido=!!(premioDoc&&premioDoc.destinoElegido);
    var importeCobroPend=destinoDecidido?Number(premioDoc.importeCobro||0):importe;
    var importeRifaUsado=destinoDecidido?Number(premioDoc.importeRifa||0):0;

    var estiloBtn=function(bg,color,borde){return {width:'100%',border:borde||'none',borderRadius:10,padding:'11px 12px',fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:2,background:bg,color:color,cursor:'pointer',marginBottom:8};};

    return <div style={{background:importe>0?'rgba(255,215,0,.12)':'rgba(0,31,107,.04)',border:'1px solid '+(importe>0?'rgba(212,175,55,.35)':'rgba(0,31,107,.08)'),borderRadius:16,padding:16,marginBottom:16}}>
        <p style={{fontFamily:"'Teko',sans-serif",fontSize:15,letterSpacing:2,color:'#001F6B',textTransform:'uppercase',marginBottom:5,fontWeight:700}}>{importe>0?'🏆 PREMIO DE LA JORNADA '+(jornada.numeroJornada?'· J'+jornada.numeroJornada:''):'📊 JORNADA RESUELTA'}</p>
        {importe>0 ? <>
            <p style={{fontFamily:"'Teko',sans-serif",fontSize:28,fontWeight:700,color:'#001F6B',marginBottom:8}}>HAS GANADO {importe.toFixed(2)}€</p>

            {/* ── PASO 1: gestionar el premio (aviso + reparto libre) ── */}
            {!destinoDecidido && <>
                <div style={{background:'rgba(230,57,70,.07)',border:'1px dashed rgba(230,57,70,.35)',borderRadius:10,padding:'8px 12px',marginBottom:10}}>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'#b02a35',lineHeight:1.5,margin:0}}>📣 <strong>Recuerda avisar al admin de cómo gestionar tu premio</strong> — elige aquí abajo y le llegará directo a su panel.</p>
                </div>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,.6)',lineHeight:1.5,marginBottom:10}}>Reparte tu premio como quieras entre las opciones (puedes combinarlas):</p>
                {(function(){
                    var restante=Number((importe-eurosARifa-eurosAAcumular).toFixed(2));
                    var paso=0.5;
                    var Fila=function(props){
                        return <div style={{display:'flex',alignItems:'center',gap:8,background:'#fff',border:'1px solid rgba(0,31,107,.1)',borderRadius:10,padding:'8px 10px',marginBottom:6}}>
                            <span style={{fontSize:15,flexShrink:0}}>{props.icono}</span>
                            <div style={{flex:1}}>
                                <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:1,color:'#001F6B',margin:0}}>{props.titulo}</p>
                                {props.sub && <p style={{fontFamily:"'Inter',sans-serif",fontSize:9,color:'rgba(0,31,107,.45)',margin:0}}>{props.sub}</p>}
                            </div>
                            {props.control}
                        </div>;
                    };
                    var Stepper=function(props){
                        return <div style={{display:'flex',alignItems:'center',gap:6}}>
                            <button onClick={props.menos} disabled={props.valor<=0} style={{width:26,height:26,borderRadius:8,border:'1px solid rgba(0,31,107,.2)',background:'#fff',color:'#001F6B',fontSize:14,cursor:'pointer',opacity:props.valor<=0?0.3:1}}>−</button>
                            <span style={{fontFamily:"'Teko',sans-serif",fontSize:15,fontWeight:700,color:'#001F6B',minWidth:44,textAlign:'center'}}>{props.valor.toFixed(2)}€</span>
                            <button onClick={props.mas} disabled={!props.puedeMas} style={{width:26,height:26,borderRadius:8,border:'none',background:props.puedeMas?'#001F6B':'rgba(0,31,107,.1)',color:'#FFD700',fontSize:14,cursor:'pointer'}}>+</button>
                        </div>;
                    };
                    return <div style={{marginBottom:8}}>
                        {rifaActiva && precioPapeleta>0 && <Fila icono="🎟️" titulo="A LA RIFA" sub={'papeleta a '+precioPapeleta.toFixed(2)+'€'}
                            control={<Stepper valor={eurosARifa}
                                menos={function(){setEurosARifa(Math.max(0,Number((eurosARifa-precioPapeleta).toFixed(2))));}}
                                mas={function(){setEurosARifa(Number((eurosARifa+precioPapeleta).toFixed(2)));}}
                                puedeMas={restante>=precioPapeleta} />} />}
                        <Fila icono="📦" titulo="ACUMULAR PARA PRÓXIMAS JORNADAS" sub="el sistema paga tus jornadas solo, hasta agotarlo"
                            control={<Stepper valor={eurosAAcumular}
                                menos={function(){setEurosAAcumular(Math.max(0,Number((eurosAAcumular-paso).toFixed(2))));}}
                                mas={function(){setEurosAAcumular(Number((eurosAAcumular+Math.min(paso,restante)).toFixed(2)));}}
                                puedeMas={restante>0.001} />} />
                        <Fila icono="💰" titulo="RECIBIR POR BIZUM" sub="lo que no repartas, se cobra"
                            control={<span style={{fontFamily:"'Teko',sans-serif",fontSize:17,fontWeight:700,color:'#0f8a61'}}>{restante.toFixed(2)}€</span>} />
                        <button onClick={function(){registrarDestino(eurosARifa,eurosAAcumular,restante);}} disabled={guardandoDestino||restante<-0.001}
                            style={estiloBtn('#10b981','#fff')}>{guardandoDestino?'GUARDANDO…':'✅ CONFIRMAR GESTIÓN DEL PREMIO'}</button>
                        <button onClick={function(){setEurosARifa(0);setEurosAAcumular(0);registrarDestino(0,0,importe);}} disabled={guardandoDestino}
                            style={estiloBtn('#fff','rgba(0,31,107,.6)','1px solid rgba(0,31,107,.15)')}>💰 TODO A COBRAR, SIN REPARTIR</button>
                    </div>;
                })()}
            </>}

            {/* ── PASO 2: desglose trazable + confirmación de cobro ── */}
            {destinoDecidido && <>
                <div style={{background:'#fff',border:'1px solid rgba(0,31,107,.08)',borderRadius:12,padding:12,marginBottom:10}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:2,color:'rgba(0,31,107,.5)',textTransform:'uppercase',marginBottom:6}}>DESTINO DE TU PREMIO</p>
                    {importeRifaUsado>0 && <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'#001F6B',marginBottom:4}}>🎟️ {importeRifaUsado.toFixed(2)}€ → saldo para la rifa{rifaActiva?' «'+(rifaActiva.titulo||'')+'»':''}</p>}
                    {Number(premioDoc.importeAcumular||0)>0 && <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'#001F6B',marginBottom:4}}>📦 {Number(premioDoc.importeAcumular||0).toFixed(2)}€ → saldo para próximas jornadas (se descuenta solo al abrirse cada jornada)</p>}
                    {importeCobroPend>0 && <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'#001F6B',marginBottom:0}}>💰 {importeCobroPend.toFixed(2)}€ → {premioDoc.recibido?'✅ premio recibido':'pendiente de cobro'}</p>}
                    {importeCobroPend===0 && importeRifaUsado>0 && <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,.5)',margin:0}}>Premio destinado íntegramente a la rifa.</p>}
                </div>
                {importeRifaUsado>0 && <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,.55)',marginBottom:8}}>Entra en la sección 🎟️ RIFAS para elegir tus números.</p>}
                {importeCobroPend>0 && !premioDoc.recibido && (
                    <button onClick={confirmarCobro} style={estiloBtn('#001F6B','#fff')}>💰 HE RECIBIDO {importeCobroPend.toFixed(2)}€</button>
                )}
                {importeCobroPend>0 && premioDoc.recibido && (
                    <button disabled style={{...estiloBtn('#10b981','#fff'),cursor:'default'}}>✅ COBRO CONFIRMADO</button>
                )}
            </>}
        </> : <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,.55)',margin:0}}>Esta jornada no tienes premio económico. El resultado y los puntos se gestionan por separado.</p>}
    </div>;
};

// ============================================================================
// 🔎 PREVIA DEL PARTIDO — forma de los DOS equipos + cara a cara (H2H)
// ============================================================================
// Muestra los últimos partidos de la UDLP Y del rival de la jornada, con la
// competición de cada uno (Liga, Copa, amistoso…), y el histórico directo
// entre ambos. Se consulta a la API UNA vez por jornada y queda cacheado en
// el documento de la jornada (jornadas/{id}.previa) para no gastar llamadas.
// ============================================================================
// 📊 RESULTADOS DE LA JORNADA — puntos de todos, leídos en directo
// ============================================================================
// Lee los pronósticos de la jornada finalizada y muestra qué sumó cada uno,
// sin depender del historial local (que a veces aún no está cargado y dejaba
// los puntos a 0). Sirve también para el propio usuario: su fila destacada.
// ============================================================================
// ⏱️ AUTOMATISMO DE APERTURA Y CIERRE DE JORNADA + CUENTA ATRÁS
// ============================================================================
// Las fechas de apertura y cierre que fija el admin ya no son decorativas:
// este componente las vigila y cambia el estado de la jornada solo.
//   · Pre-apertura → Abierta   al llegar la fechaApertura
//   · Abierta      → Cerrada   al llegar la fechaCierre
// Además pinta la cuenta atrás para el jugador ("faltan 52 min para el cierre"
// o "la porra abre en 3 h 20 min").
function msDesdeFecha(f) {
    if (!f) return null;
    try {
        var d = f && f.toDate ? f.toDate() : new Date(f);
        var t = d.getTime();
        return isNaN(t) ? null : t;
    } catch(e) { return null; }
}

function formatearCuentaAtras(ms) {
    if (ms <= 0) return '0s';
    var seg = Math.floor(ms / 1000);
    var d = Math.floor(seg / 86400);
    var h = Math.floor((seg % 86400) / 3600);
    var m = Math.floor((seg % 3600) / 60);
    var s = seg % 60;
    if (d > 0) return d + 'd ' + h + 'h ' + m + 'min';
    if (h > 0) return h + 'h ' + m + 'min';
    if (m > 0) return m + 'min ' + s + 's';
    return s + 's';
}

// ============================================================================
// 🎫 BOLETO DE PAGO — recordatorio de Bizum tras guardar la apuesta
// ============================================================================
// Se muestra DESPUÉS de guardar (la apuesta ya está a salvo). Sirve para
// declarar el Bizum y que le llegue al admin a su bandeja de confirmación.
const BoletoPagoJornada = ({ jornada, user, pronostico, elOtroActivado, onCerrar }) => {
    var [bizumCfg, setBizumCfg] = useState(null);
    var [enviando, setEnviando] = useState(false);
    useEffect(function() {
        var u = onSnapshot(doc(db, 'configuracion', 'bizum'), function(s) { setBizumCfg(s.exists() ? s.data() : null); }, function(){});
        return function() { u(); };
    }, []);
    if (!jornada) return null;
    var importe = jornada.esVip ? APUESTA_VIP : APUESTA_NORMAL;

    var declararBizum = async function() {
        if (enviando) return;
        if (!window.confirm('¿Confirmas que has hecho el Bizum de ' + importe.toFixed(2) + '€?\n\nQuedará pendiente de que el admin lo verifique.')) return;
        setEnviando(true);
        try {
            await addDoc(collection(db, 'pagos'), {
                jugador: user, pagoBy: user,
                tipo: jornada.esVip ? 'jornada_vip' : 'jornada_normal',
                jornada: 'J' + jornada.numeroJornada,
                importe: importe,
                descripcion: 'Jornada ' + jornada.numeroJornada + ' · declarado desde el boleto',
                metodo: 'bizum', estado: 'pendiente_confirmacion', creadoEn: serverTimestamp(),
            });
            alert('✅ Pago declarado. El admin lo verificará en breve.');
            onCerrar();
        } catch(e) { alert('❌ ' + e.message); }
        setEnviando(false);
    };

    return (
        <CapaEmergente>
        <div onClick={onCerrar} style={{position:'fixed',top:0,left:0,right:0,bottom:0,zIndex:10700,background:'rgba(4,10,38,0.85)',display:'flex',alignItems:'center',justifyContent:'center',padding:20}}>
            <div onClick={function(e){ e.stopPropagation(); }} style={{maxWidth:360,width:'100%',background:'#fff',borderRadius:18,overflow:'hidden',boxShadow:'0 20px 50px rgba(0,0,0,0.5)'}}>
                <div style={{background:'linear-gradient(135deg,#001F6B,#0035b8)',padding:'14px 16px'}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:16,letterSpacing:2,color:'#FFD700',margin:0}}>🎫 TU BOLETO · JORNADA {jornada.numeroJornada}</p>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(255,255,255,0.6)',margin:'2px 0 0'}}>Apuesta guardada ✅ — falta el pago</p>
                </div>
                <div style={{padding:'14px 16px'}}>
                    <div style={{background:'rgba(0,31,107,0.04)',borderRadius:12,padding:'10px 12px',marginBottom:10}}>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:22,fontWeight:700,color:'#001F6B',margin:'0 0 2px'}}>{jornada.equipoLocal} {pronostico.golesLocal} – {pronostico.golesVisitante} {jornada.equipoVisitante}</p>
                        <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,0.6)',margin:0}}>1X2: <strong>{pronostico.resultado1x2}</strong>{elOtroActivado ? ' · 🛡️ El Otro activado' : ''}</p>
                    </div>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(0,31,107,0.75)',lineHeight:1.7,marginBottom:10}}>
                        Para que tu apuesta CUENTE, haz el <strong>Bizum de {importe.toFixed(2)}€</strong>{bizumCfg && bizumCfg.telefono ? <span> al <strong>{bizumCfg.telefono}</strong>{bizumCfg.titular ? ' (' + bizumCfg.titular + ')' : ''}</span> : ''} con concepto <strong>"J{jornada.numeroJornada} · {user}"</strong> antes del cierre.
                    </p>
                    <button onClick={declararBizum} disabled={enviando}
                        style={{width:'100%',border:'none',borderRadius:12,padding:13,background:'#10b981',color:'#fff',fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:2,fontWeight:700,cursor:'pointer',marginBottom:8}}>
                        {enviando ? 'ENVIANDO…' : '✅ YA HE HECHO EL BIZUM'}
                    </button>
                    <button onClick={onCerrar} style={{width:'100%',border:'1px solid rgba(0,31,107,0.15)',borderRadius:12,padding:10,background:'#fff',color:'rgba(0,31,107,0.6)',fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:1,cursor:'pointer'}}>LO PAGO LUEGO</button>
                </div>
            </div>
        </div>
        </CapaEmergente>
    );
};

// Recordatorio con cuenta atrás para elegir las 5 Estrellas: se apoya en el
// mismo cierre real que usa la pantalla de Estrellas (2h antes del partido,
// o el cierre manual que fije el admin).
// ============================================================================
// 🔴 RANKING EN VIVO DE LAS 5 ESTRELLAS
// ============================================================================
// Durante el partido: cada participante con las fotos de sus 5 elegidos, las
// estrellas que lleva cada uno y el total, ordenado en tiempo real. Se
// reordena solo cada vez que la sincronización trae datos nuevos.
const RankingEstrellasEnVivo = ({ jornada, currentUser, userProfiles, plantilla, excluidos }) => {
    var [selecciones, setSelecciones] = useState({});
    useEffect(function() {
        if (!jornada || !jornada.id) return;
        var u = onSnapshot(collection(db, 'estrellas_seleccion', jornada.id, 'jugadores'), function(snap) {
            var m = {};
            snap.forEach(function(d) { m[d.id] = d.data() || {}; });
            setSelecciones(m);
        }, function(){});
        return function() { u(); };
    }, [jornada]);

    if (!jornada) return null;
    var live = jornada.liveEstrellas && jornada.liveEstrellas.puntosPorNombre ? jornada.liveEstrellas.puntosPorNombre : null;

    var jugadorPorNombre = {};
    (plantilla || []).forEach(function(j) { jugadorPorNombre[j.nombre] = j; });

    var fuera = excluidos || [];
    var filas = Object.keys(selecciones)
        .filter(function(uid) { return fuera.indexOf(uid) === -1; })
        .map(function(uid) {
            var sel = selecciones[uid] || {};
            var elegidos = (sel.jugadores || []).map(function(j) {
                var pts = live ? Number(live[j.nombre] || 0) : null;
                return { nombre: j.nombre, pts: pts, obj: jugadorPorNombre[j.nombre] || j };
            });
            var total = elegidos.reduce(function(acc, e) { return acc + Number(e.pts || 0); }, 0);
            return { uid: uid, elegidos: elegidos, total: total };
        })
        .sort(function(a, b) { return b.total - a.total; });

    if (!filas.length) {
        return <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(0,31,107,0.45)',textAlign:'center',padding:'22px 10px'}}>Nadie ha elegido estrellas en esta jornada.</p>;
    }

    return (
        <div style={{marginBottom:20}}>
            <div style={{display:'flex',alignItems:'center',gap:7,marginBottom:10}}>
                <span style={{width:9,height:9,borderRadius:'50%',background:'#ff4444',display:'inline-block',animation:'latidoVivo 1.4s infinite'}} />
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:2,color:'#001F6B',margin:0}}>RANKING EN VIVO · JORNADA {jornada.numeroJornada}</p>
            </div>
            <style>{'@keyframes latidoVivo{0%,100%{opacity:1;transform:scale(1);}50%{opacity:.35;transform:scale(.8);}}'}</style>

            <div style={{display:'flex',flexDirection:'column',gap:7}}>
                {filas.map(function(f, i) {
                    var perf = (userProfiles || {})[f.uid] || {};
                    var esMio = f.uid === currentUser;
                    var medalla = i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : (i + 1);
                    return (
                        <div key={f.uid} style={{background: esMio ? 'linear-gradient(135deg,rgba(255,215,0,0.14),rgba(255,215,0,0.04))' : '#fff',
                            border: '1px solid ' + (esMio ? 'rgba(212,175,55,0.5)' : (i < 3 ? 'rgba(0,31,107,0.14)' : 'rgba(0,31,107,0.07)')),
                            borderRadius:14,padding:'9px 11px',transition:'all 0.4s ease'}}>
                            {/* Cabecera de la fila: puesto, jugador, total */}
                            <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:7}}>
                                <span style={{fontFamily:"'Teko',sans-serif",fontSize:15,fontWeight:700,width:22,textAlign:'center',
                                    color: i === 0 ? '#d4a017' : 'rgba(0,31,107,0.35)'}}>{medalla}</span>
                                <IconoPerfil perfil={perf} size={26} />
                                <span style={{flex:1,minWidth:0,fontFamily:"'Inter',sans-serif",fontSize:12,fontWeight: esMio ? 700 : 500,color:'#001F6B',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>
                                    {nombreVisible(f.uid, perf)}{esMio ? ' (tú)' : ''}
                                </span>
                                <span style={{fontFamily:"'Teko',sans-serif",fontSize:22,fontWeight:700,color: f.total > 0 ? '#b8860b' : 'rgba(0,31,107,0.25)',lineHeight:1}}>
                                    ⭐{live ? f.total : '–'}
                                </span>
                            </div>
                            {/* Sus 5 estrellas: foto + puntos de cada una */}
                            <div style={{display:'flex',gap:6,paddingLeft:30,flexWrap:'wrap'}}>
                                {f.elegidos.map(function(e, k) {
                                    var foto = e.obj ? getFotoJugador(e.obj) : null;
                                    var suma = Number(e.pts || 0);
                                    return (
                                        <div key={k} style={{position:'relative',width:38,textAlign:'center'}} title={e.nombre + ' · ' + (live ? suma + '⭐' : 'sin datos')}>
                                            {foto ? (
                                                <img src={foto} alt={e.nombre}
                                                    style={{width:34,height:34,borderRadius:'50%',objectFit:'cover',background:'#f0f0f0',
                                                        border: suma > 0 ? '2px solid #FFD700' : (suma < 0 ? '2px solid #e63946' : '2px solid rgba(0,31,107,0.12)'),
                                                        filter: live && suma === 0 ? 'grayscale(0.6)' : 'none',transition:'all 0.4s'}}
                                                    onError={function(ev){ ev.target.style.display='none'; }} />
                                            ) : (
                                                <div style={{width:34,height:34,borderRadius:'50%',background:'rgba(0,31,107,0.06)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:14}}>⭐</div>
                                            )}
                                            {live && (
                                                <span style={{position:'absolute',top:-3,right:-1,minWidth:16,height:16,borderRadius:8,padding:'0 3px',
                                                    background: suma > 0 ? '#FFD700' : (suma < 0 ? '#e63946' : 'rgba(0,31,107,0.15)'),
                                                    color: suma < 0 ? '#fff' : '#001F6B',
                                                    fontFamily:"'Teko',sans-serif",fontSize:10,fontWeight:700,
                                                    display:'flex',alignItems:'center',justifyContent:'center',boxShadow:'0 1px 3px rgba(0,0,0,0.25)'}}>
                                                    {suma}
                                                </span>
                                            )}
                                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:7.5,color:'rgba(0,31,107,0.5)',margin:'1px 0 0',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>
                                                {String(e.nombre || '').split(' ').pop()}
                                            </p>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    );
                })}
            </div>
            <p style={{fontFamily:"'Inter',sans-serif",fontSize:9,color:'rgba(0,31,107,0.45)',textAlign:'center',margin:'8px 0 0'}}>
                {live
                    ? 'Provisional · se actualiza solo durante el partido' + (jornada.liveEstrellas && jornada.liveEstrellas.actualizadoEn ? ' (últimos datos: ' + new Date(jornada.liveEstrellas.actualizadoEn).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'}) + ')' : '')
                    : 'Esperando las primeras estadísticas del partido…'}
            </p>
        </div>
    );
};

const CronometroEstrellasMJ = ({ jornada, user }) => {
    var [ahora, setAhora] = useState(Date.now());
    var [yaElegidas, setYaElegidas] = useState(null);
    useEffect(function() {
        var iv = setInterval(function() { setAhora(Date.now()); }, 1000);
        return function() { clearInterval(iv); };
    }, []);
    useEffect(function() {
        if (!jornada || !jornada.id || !user) return;
        var u = onSnapshot(doc(db, 'estrellas_seleccion', jornada.id, 'jugadores', user), function(s) {
            setYaElegidas(s.exists() ? ((s.data().jugadores || []).length) : 0);
        }, function(){ setYaElegidas(0); });
        return function() { u(); };
    }, [jornada, user]);

    if (!jornada || jornada.estado !== 'Abierta') return null;
    var cierreMs = getCierreEstrellasMs(jornada);
    if (!cierreMs) return null;
    var restante = cierreMs - ahora;
    if (restante <= 0) return null;
    var completo = yaElegidas >= 5;
    var urgente = restante < 3 * 3600 * 1000;

    return (
        <div style={{background: completo ? 'rgba(16,185,129,0.07)' : (urgente ? 'linear-gradient(135deg,rgba(230,57,70,0.1),rgba(230,57,70,0.04))' : 'linear-gradient(135deg,rgba(255,215,0,0.14),rgba(255,215,0,0.04))'),
            border: '1px solid ' + (completo ? 'rgba(16,185,129,0.3)' : (urgente ? 'rgba(230,57,70,0.35)' : 'rgba(212,175,55,0.4)')),
            borderRadius:14,padding:'11px 14px',marginBottom:12,display:'flex',alignItems:'center',gap:12}}>
            <span style={{fontSize:26,flexShrink:0}}>{completo ? '✅' : '⭐'}</span>
            <div style={{flex:1,minWidth:0}}>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:1.5,color: completo ? '#0f8a61' : (urgente ? '#b02a35' : '#8a6a00'),margin:0,textTransform:'uppercase'}}>
                    {completo ? 'TUS 5 ESTRELLAS ESTÁN ELEGIDAS' : (urgente ? '🚨 ÚLTIMAS HORAS PARA TUS 5 ESTRELLAS' : 'NO OLVIDES TUS 5 ESTRELLAS')}
                </p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:10.5,color:'rgba(0,31,107,0.6)',margin:'2px 0 0',lineHeight:1.5}}>
                    {completo
                        ? 'Puedes cambiarlas hasta el cierre. Suman puntos extra a la clasificación.'
                        : 'Elige 5 jugadores de la UD y gana puntos EXTRA en esta jornada (5/4/3/2/1 al top 5).'}
                </p>
            </div>
            <div style={{textAlign:'right',flexShrink:0}}>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:19,fontWeight:700,color: urgente && !completo ? '#e63946' : '#001F6B',margin:0,lineHeight:1}}>{formatearCuentaAtras(restante)}</p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:8.5,color:'rgba(0,31,107,0.45)',margin:0}}>para elegir</p>
            </div>
        </div>
    );
};

// ============================================================================
// ============================================================================
// 🏆 MODO VIP — azul metalizado y oro premium
// ============================================================================
// Se enciende cuando la jornada marcada como VIP entra en Pre-apertura y se
// apaga cuando arranca la siguiente. Cambia el tema de TODA la app.
var PALETA_VIP = {
    fondoApp: 'linear-gradient(160deg,#0E1B3D 0%,#152449 45%,#0B1530 100%)',
    fondoTop: 'rgba(14,27,61,0.88)',
    textoTop: '#E8C34A',
    hairline: 'rgba(201,162,39,0.28)',
    iconoMenu: '#C9A227',
    oro: '#C9A227',
    oroClaro: '#E8C34A',
    tarjeta: 'linear-gradient(150deg,rgba(255,255,255,0.08),rgba(255,255,255,0.02))',
    bordeTarjeta: '1px solid rgba(201,162,39,0.3)',
    textoSuave: '#93A2C8',
};

// Hook global: ¿estamos en modo VIP ahora mismo? y ¿por qué jornada?
function useModoVip() {
    var [vip, setVip] = useState(null);
    useEffect(function() {
        var u = onSnapshot(
            collection(db, 'jornadas'),
            function(snap) {
                var ahora = Date.now();
                var activa = null;
                snap.docs.filter(function(d){ return (d.data()||{}).esVip; })
                    .sort(function(a,b){ return ((a.data()||{}).numeroJornada||0) - ((b.data()||{}).numeroJornada||0); })
                    .forEach(function(d) {
                    var j = { id: d.id, ...d.data() };
                    // VIP visible desde Pre-apertura hasta que la jornada acaba
                    var estadosVip = ['Próximamente', 'Pre-apertura', 'Abierta', 'Cerrada', 'En vivo'];
                    if (estadosVip.indexOf(j.estado) !== -1) { activa = j; return; }
                    // También si ya está finalizada pero es la última jugada
                    if (j.estado === 'Finalizada' && getKickoffMs(j) && (ahora - getKickoffMs(j)) < 24 * 3600 * 1000) activa = j;
                });
                setVip(activa);
            }, function(){});
        return function() { u(); };
    }, []);
    return vip;
}

// ============================================================================
// 💰 MOTOR DE BOTE ACUMULADO
// ============================================================================
// Cuando una jornada se cierra SIN acertantes del marcador exacto, su bote
// pasa automáticamente a la siguiente jornada pendiente. Antes había que
// arrastrarlo a mano y se perdía.
const MotorBoteAcumulado = () => {
    var hechoRef = useRef({});
    useEffect(function() {
        var vivo = true;
        (async function() {
            try {
                var snap = await getDocs(query(collection(db, 'jornadas'), where('estado', '==', 'Finalizada'),
                    orderBy('numeroJornada', 'desc'), limit(6)));
                for (var i = 0; i < snap.docs.length && vivo; i++) {
                    var j = { id: snap.docs[i].id, ...snap.docs[i].data() };
                    if (!j.cierreDefinitivo) continue;           // solo jornadas ya cerradas
                    if (j.boteTrasladado) continue;              // ya se hizo
                    var ganadores = Array.isArray(j.ganadores) ? j.ganadores : [];
                    if (ganadores.length > 0) {                  // hubo acertante: no se acumula
                        await setDoc(doc(db, 'jornadas', j.id), { boteTrasladado: true }, { merge: true });
                        continue;
                    }
                    var importe = Number(j.boteTotal !== undefined ? j.boteTotal : (j.bote || 0));
                    if (!(importe > 0)) { await setDoc(doc(db, 'jornadas', j.id), { boteTrasladado: true }, { merge: true }); continue; }
                    if (hechoRef.current[j.id]) continue;
                    hechoRef.current[j.id] = true;

                    // Siguiente jornada aún no finalizada
                    var sig = await getDocs(query(collection(db, 'jornadas'),
                        where('numeroJornada', '==', Number(j.numeroJornada) + 1), limit(1)));
                    if (sig.empty) continue;
                    var jSig = { id: sig.docs[0].id, ...sig.docs[0].data() };
                    if (jSig.estado === 'Finalizada') continue;

                    await setDoc(doc(db, 'jornadas', jSig.id), {
                        bote: Number((Number(jSig.bote || 0) + importe).toFixed(2)),
                        boteHeredadoDe: j.numeroJornada,
                        boteHeredadoImporte: importe,
                    }, { merge: true });
                    await setDoc(doc(db, 'jornadas', j.id), { boteTrasladado: true, boteTrasladadoEn: serverTimestamp() }, { merge: true });
                    console.log('%c💰 Bote de ' + importe.toFixed(2) + '€ trasladado de J' + j.numeroJornada + ' a J' + jSig.numeroJornada,
                        'background:#001F6B;color:#FFD700;padding:2px 6px;border-radius:4px');
                }
            } catch(e) { /* se reintenta en la siguiente carga */ }
        })();
        return function() { vivo = false; };
    }, []);
    return null;
};

// ── Aviso al admin de los botes trasladados solos, para verificarlos ──
const BotesHeredadosAdmin = ({ jornadas }) => {
    var conHerencia = (jornadas || []).filter(function(j) { return j.boteHeredadoDe; })
        .sort(function(a, b) { return (b.numeroJornada || 0) - (a.numeroJornada || 0); });
    var vipsProgramadas = (jornadas || []).filter(function(j) { return j.esVip && j.estado !== 'Finalizada'; });
    return (
        <div style={ADMIN_STYLES.card}>
            <p style={{fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:2,color:'#001F6B',textTransform:'uppercase',marginBottom:8,fontWeight:600}}>💰 Botes y jornadas VIP</p>
            {conHerencia.length === 0 ? (
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:11.5,color:'rgba(0,31,107,0.5)',margin:'0 0 8px'}}>Sin botes arrastrados por ahora. Cuando una jornada cierre sin acertantes, su bote pasará solo a la siguiente.</p>
            ) : conHerencia.map(function(j) {
                return (
                    <p key={j.id} style={{fontFamily:"'Inter',sans-serif",fontSize:11.5,color:'#0f8a61',background:'rgba(16,185,129,0.08)',borderRadius:8,padding:'8px 10px',margin:'0 0 6px',lineHeight:1.5}}>
                        ✅ <strong>J{j.numeroJornada}</strong> arrastra <strong>{Number(j.boteHeredadoImporte || 0).toFixed(2)} €</strong> de la J{j.boteHeredadoDe}. Bote actual: {Number(j.bote || 0).toFixed(2)} €.
                    </p>
                );
            })}
            <div style={{background:'rgba(201,162,39,0.1)',border:'1px solid rgba(201,162,39,0.35)',borderRadius:9,padding:'8px 10px',marginTop:4}}>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:1,color:'#8a6a00',margin:'0 0 3px'}}>🏆 JORNADAS VIP PROGRAMADAS</p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,0.65)',margin:0,lineHeight:1.5}}>
                    {vipsProgramadas.length
                        ? vipsProgramadas.map(function(j){ return 'J' + j.numeroJornada; }).join(' · ') + ' — el tema dorado se enciende solo al llegar a Pre-apertura.'
                        : 'Ninguna marcada. Activa la casilla VIP en la jornada que quieras y el tema premium se aplicará solo.'}
                </p>
            </div>
        </div>
    );
};

// ── Rótulo de avisos con acceso, solo en Mi Jornada ──
const RotuloAvisosMJ = ({ jornada, user, misEstrellas, pagada, onIr }) => {
    var avisos = [];
    if (jornada) {
        var bote = Number(jornada.bote || 0);
        if (bote > 0) avisos.push({ ic:'💰', t:'Bote acumulado de ' + bote.toFixed(2) + ' €' + (jornada.boteHeredadoDe ? ' (viene de la J' + jornada.boteHeredadoDe + ')' : ''), d:null });
        if (!pagada && jornada.estado === 'Abierta') avisos.push({ ic:'💳', t:'Te falta pagar esta jornada', d:'pagos' });
        if (misEstrellas !== null && misEstrellas < 5) avisos.push({ ic:'⭐', t:'Aún no has elegido tus 5 Estrellas', d:'estrellas' });
    }
    if (!avisos.length) return null;
    return (
        <div style={{background:'#fff',border:'1px solid rgba(0,31,107,0.1)',borderRadius:14,overflow:'hidden',marginBottom:12}}>
            {avisos.map(function(a, i) {
                return (
                    <div key={i} onClick={function(){ if (a.d && onIr) onIr(a.d); }}
                        style={{display:'flex',alignItems:'center',gap:10,padding:'10px 13px',
                            borderBottom: i < avisos.length - 1 ? '1px solid rgba(0,31,107,0.05)' : 'none',
                            cursor: a.d ? 'pointer' : 'default'}}>
                        <span style={{fontSize:15,flexShrink:0}}>{a.ic}</span>
                        <span style={{flex:1,fontFamily:"'Inter',sans-serif",fontSize:12,color:'#001F6B'}}>{a.t}</span>
                        {a.d && <span style={{fontSize:13,color:'rgba(0,31,107,0.3)'}}>›</span>}
                    </div>
                );
            })}
        </div>
    );
};

// ============================================================================
// 💬 TABLÓN DE DEDICATORIAS — la "cámara del estadio" de la porra
// ============================================================================
// Mensajes cortos de la peña que se intercalan con los avisos de la app en la
// marquesina. Publicación directa (sin espera), pero con registro completo,
// filtro de contenido, botón de reporte y control total del admin.
var TABLON_MAX_CARACTERES = 90;
var TABLON_ESPERA_HORAS = 12;

// Filtro básico: bloquea insultos y contenido ofensivo evidente. No pretende
// ser infalible — la red de seguridad real es el reporte + el panel de admin.
var PALABRAS_VETADAS = [
    'gilipollas','imbecil','imbécil','subnormal','retrasado','maricon','maricón','puta','puto',
    'cabron','cabrón','hijoputa','hijo de puta','mierda','coño','joder','follar','polla','zorra',
    'negrata','moro','sudaca','maracas','malparido','pendejo','verga','mogolico','mongolico','mongólico',
];
function revisarTextoTablon(texto) {
    var limpio = String(texto || '').trim();
    if (limpio.length < 3) return { ok: false, motivo: 'El mensaje es demasiado corto.' };
    if (limpio.length > TABLON_MAX_CARACTERES) return { ok: false, motivo: 'Máximo ' + TABLON_MAX_CARACTERES + ' caracteres.' };
    var normal = limpio.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
    for (var i = 0; i < PALABRAS_VETADAS.length; i++) {
        var p = PALABRAS_VETADAS[i].normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
        if (normal.indexOf(p) !== -1) return { ok: false, motivo: 'Ese mensaje contiene lenguaje que no se admite. Aquí se viene a dedicar, no a faltar. 💛' };
    }
    if (/(https?:\/\/|www\.)/i.test(limpio)) return { ok: false, motivo: 'No se pueden poner enlaces.' };
    if (/(\d[\s-]?){9,}/.test(limpio)) return { ok: false, motivo: 'No pongas números de teléfono ni cuentas.' };
    return { ok: true, texto: limpio };
}

// Formulario para dejar la dedicatoria (vive en Mi Jornada)
const TablonDedicatorias = ({ user, userProfiles, comoVentana, onCerrar }) => {
    var [texto, setTexto] = useState('');
    var [mios, setMios] = useState([]);
    var [ultimos, setUltimos] = useState([]);
    var [enviando, setEnviando] = useState(false);
    var [aviso, setAviso] = useState('');
    var [bloqueado, setBloqueado] = useState(false);

    useEffect(function() {
        var u1 = onSnapshot(collection(db, 'tablon'), function(snap) {
            var todos = snap.docs.map(function(d) { return { id: d.id, ...d.data() }; })
                .filter(function(m) { return !m.oculto; })
                .sort(function(a, b) {
                    var ta = a.creadoEn && a.creadoEn.seconds ? a.creadoEn.seconds : 0;
                    var tb = b.creadoEn && b.creadoEn.seconds ? b.creadoEn.seconds : 0;
                    return tb - ta;
                });
            setUltimos(todos.slice(0, 6));
            setMios(todos.filter(function(m) { return m.autor === user; }));
        }, function(){});
        var u2 = onSnapshot(doc(db, 'configuracion', 'tablonBloqueados'), function(s) {
            var lista = s.exists() ? (s.data().nombres || []) : [];
            setBloqueado(lista.indexOf(user) !== -1);
        }, function(){});
        return function() { u1(); u2(); };
    }, [user]);

    var ultimoMio = mios.length ? mios[0] : null;
    var msRestantes = 0;
    if (ultimoMio && ultimoMio.creadoEn && ultimoMio.creadoEn.seconds) {
        msRestantes = (ultimoMio.creadoEn.seconds * 1000 + TABLON_ESPERA_HORAS * 3600 * 1000) - Date.now();
    }
    var puedeEscribir = !bloqueado && msRestantes <= 0;

    var publicar = async function() {
        if (enviando) return;
        var rev = revisarTextoTablon(texto);
        if (!rev.ok) { setAviso(rev.motivo); return; }
        setEnviando(true); setAviso('');
        try {
            await addDoc(collection(db, 'tablon'), {
                autor: user, texto: rev.texto, creadoEn: serverTimestamp(),
                reportes: 0, oculto: false,
            });
            setTexto('');
            setAviso('💛 ¡Publicado! Tu mensaje ya rota por la app.');
        } catch(e) { setAviso('No se pudo publicar: ' + e.message); }
        setEnviando(false);
    };

    var reportar = async function(m) {
        if (!window.confirm('¿Reportar este mensaje al admin?\n\n"' + m.texto + '"')) return;
        try {
            await setDoc(doc(db, 'tablon', m.id), {
                reportes: increment(1),
                reportadoPor: arrayUnion(user),
            }, { merge: true });
            alert('Gracias. El admin lo revisará.');
        } catch(e) { alert('No se pudo reportar: ' + e.message); }
    };

    var contenido = (
        <div style={{background:'#fff',border:'1px solid rgba(0,31,107,0.1)',borderRadius:14,padding:'13px 14px',marginBottom: comoVentana ? 0 : 12,
            maxHeight: comoVentana ? '80vh' : 'none', overflowY: comoVentana ? 'auto' : 'visible'}}>
            <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:3}}>
                <p style={{flex:1,fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:2,color:'#001F6B',margin:0}}>💬 DEJA TU DEDICATORIA</p>
                {comoVentana && <button onClick={onCerrar} style={{border:'none',background:'rgba(0,31,107,0.07)',color:'rgba(0,31,107,0.6)',borderRadius:16,padding:'4px 12px',fontFamily:"'Teko',sans-serif",fontSize:11,letterSpacing:1,cursor:'pointer'}}>CERRAR ✕</button>}
            </div>
            <p style={{fontFamily:"'Inter',sans-serif",fontSize:10.5,color:'rgba(0,31,107,0.55)',lineHeight:1.5,margin:'0 0 9px'}}>
                Como la cámara del estadio: dedica la victoria a alguien, felicita al ganador o suelta tu pique sano. Tu mensaje irá rotando por la app.
            </p>

            {bloqueado ? (
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:11.5,color:'#e63946',background:'rgba(230,57,70,0.07)',borderRadius:8,padding:'8px 10px',margin:0}}>
                    Tienes el tablón bloqueado. Habla con el admin si crees que es un error.
                </p>
            ) : !puedeEscribir ? (
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:11.5,color:'rgba(0,31,107,0.55)',background:'rgba(0,31,107,0.04)',borderRadius:8,padding:'8px 10px',margin:0}}>
                    ⏳ Ya has publicado. Podrás dejar otra dedicatoria en <strong>{formatearCuentaAtras(msRestantes)}</strong>.
                </p>
            ) : (
                <>
                <textarea value={texto} onChange={function(e){ setTexto(e.target.value.slice(0, TABLON_MAX_CARACTERES)); setAviso(''); }}
                    placeholder="Ej.: Esta victoria va por mi padre 💛💙"
                    style={{width:'100%',boxSizing:'border-box',border:'1px solid rgba(0,31,107,0.15)',borderRadius:10,padding:'9px 11px',
                        fontSize:13,fontFamily:"'Inter',sans-serif",resize:'none',height:60,marginBottom:6}} />
                <div style={{display:'flex',alignItems:'center',gap:8}}>
                    <span style={{flex:1,fontFamily:"'Inter',sans-serif",fontSize:10,color: texto.length > TABLON_MAX_CARACTERES - 15 ? '#e63946' : 'rgba(0,31,107,0.4)'}}>
                        {texto.length}/{TABLON_MAX_CARACTERES} · una cada {TABLON_ESPERA_HORAS} h
                    </span>
                    <button onClick={publicar} disabled={enviando || !texto.trim()}
                        style={{border:'none',borderRadius:10,padding:'8px 16px',background: texto.trim() ? '#001F6B' : 'rgba(0,31,107,0.1)',
                            color: texto.trim() ? '#FFD700' : 'rgba(0,31,107,0.3)',fontFamily:"'Teko',sans-serif",fontSize:12.5,letterSpacing:1.5,cursor:'pointer'}}>
                        {enviando ? 'ENVIANDO…' : 'PUBLICAR'}
                    </button>
                </div>
                </>
            )}
            {aviso && <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color: aviso.indexOf('💛') !== -1 ? '#0f8a61' : '#e63946',margin:'7px 0 0'}}>{aviso}</p>}

            {ultimos.length > 0 && (
                <div style={{marginTop:11,borderTop:'1px solid rgba(0,31,107,0.07)',paddingTop:9}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:11,letterSpacing:2,color:'rgba(0,31,107,0.4)',margin:'0 0 6px'}}>ÚLTIMAS DEDICATORIAS</p>
                    {ultimos.map(function(m) {
                        var perf = (userProfiles || {})[m.autor] || {};
                        return (
                            <div key={m.id} style={{display:'flex',alignItems:'center',gap:8,padding:'6px 0',borderBottom:'1px solid rgba(0,31,107,0.04)'}}>
                                <IconoPerfil perfil={perf} size={22} />
                                <div style={{flex:1,minWidth:0}}>
                                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:11.5,color:'#001F6B',margin:0,lineHeight:1.4}}>💬 {m.texto}</p>
                                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:9,color:'rgba(0,31,107,0.4)',margin:0}}>{nombreVisible(m.autor, perf)}</p>
                                </div>
                                {m.autor !== user && (
                                    <button onClick={function(){ reportar(m); }} title="Reportar"
                                        style={{border:'none',background:'transparent',color:'rgba(0,31,107,0.25)',fontSize:13,cursor:'pointer',padding:4}}>⚑</button>
                                )}
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
    );

    if (!comoVentana) return contenido;
    return (
        <CapaEmergente>
            <div onClick={onCerrar} style={{position:'fixed',top:0,left:0,right:0,bottom:0,zIndex:10800,
                background:'rgba(4,10,38,0.8)',display:'flex',alignItems:'center',justifyContent:'center',padding:18}}>
                <div onClick={function(e){ e.stopPropagation(); }} style={{maxWidth:400,width:'100%'}}>
                    {contenido}
                </div>
            </div>
        </CapaEmergente>
    );
};

// ── Panel de admin: registro, reportes y bloqueos del tablón ──
const TablonAdmin = () => {
    var [mensajes, setMensajes] = useState([]);
    var [bloqueados, setBloqueados] = useState([]);
    var [userProfiles, setUserProfiles] = useState({});
    var [soloReportados, setSoloReportados] = useState(false);

    useEffect(function() {
        var u1 = onSnapshot(collection(db, 'tablon'), function(snap) {
            setMensajes(snap.docs.map(function(d) { return { id: d.id, ...d.data() }; })
                .sort(function(a, b) {
                    var ta = a.creadoEn && a.creadoEn.seconds ? a.creadoEn.seconds : 0;
                    var tb = b.creadoEn && b.creadoEn.seconds ? b.creadoEn.seconds : 0;
                    return tb - ta;
                }));
        }, function(){});
        var u2 = onSnapshot(doc(db, 'configuracion', 'tablonBloqueados'), function(s) {
            setBloqueados(s.exists() ? (s.data().nombres || []) : []);
        }, function(){});
        var u3 = onSnapshot(collection(db, 'perfiles'), function(s) {
            var m = {}; s.forEach(function(d) { m[d.id] = d.data() || {}; }); setUserProfiles(m);
        }, function(){});
        return function() { u1(); u2(); u3(); };
    }, []);

    var ocultar = async function(m, valor) {
        try { await setDoc(doc(db, 'tablon', m.id), { oculto: valor }, { merge: true }); }
        catch(e) { alert('❌ ' + e.message); }
    };
    var alternarBloqueo = async function(nombre) {
        var esta = bloqueados.indexOf(nombre) !== -1;
        if (!window.confirm((esta ? 'DESBLOQUEAR' : 'BLOQUEAR') + ' el tablón para ' + nombre + '?')) return;
        try {
            await setDoc(doc(db, 'configuracion', 'tablonBloqueados'),
                { nombres: esta ? arrayRemove(nombre) : arrayUnion(nombre) }, { merge: true });
        } catch(e) { alert('❌ ' + e.message); }
    };

    var lista = soloReportados ? mensajes.filter(function(m) { return Number(m.reportes || 0) > 0; }) : mensajes;
    var conReportes = mensajes.filter(function(m) { return Number(m.reportes || 0) > 0; }).length;

    return (
        <div style={{...ADMIN_STYLES.card, border: conReportes ? '2px solid rgba(230,57,70,0.5)' : ADMIN_STYLES.card.border}}>
            <p style={{fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:2,color:'#001F6B',textTransform:'uppercase',marginBottom:6,fontWeight:600}}>
                💬 Tablón de dedicatorias {conReportes > 0 && <span style={{background:'#e63946',color:'#fff',borderRadius:10,padding:'1px 8px',fontSize:12,marginLeft:5}}>{conReportes} reportado(s)</span>}
            </p>
            <div style={{display:'flex',gap:6,marginBottom:9}}>
                <button onClick={function(){ setSoloReportados(false); }}
                    style={{flex:1,border:'none',borderRadius:8,padding:'7px 8px',cursor:'pointer',background: !soloReportados ? '#001F6B' : 'rgba(0,31,107,0.06)',color: !soloReportados ? '#FFD700' : 'rgba(0,31,107,0.5)',fontFamily:"'Teko',sans-serif",fontSize:11}}>TODOS ({mensajes.length})</button>
                <button onClick={function(){ setSoloReportados(true); }}
                    style={{flex:1,border:'none',borderRadius:8,padding:'7px 8px',cursor:'pointer',background: soloReportados ? '#e63946' : 'rgba(0,31,107,0.06)',color: soloReportados ? '#fff' : 'rgba(0,31,107,0.5)',fontFamily:"'Teko',sans-serif",fontSize:11}}>REPORTADOS ({conReportes})</button>
            </div>
            {bloqueados.length > 0 && (
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:10.5,color:'#b02a35',background:'rgba(230,57,70,0.07)',borderRadius:8,padding:'7px 9px',margin:'0 0 9px'}}>
                    🚫 Bloqueados: {bloqueados.join(', ')}
                </p>
            )}
            <div style={{maxHeight:300,overflowY:'auto'}}>
                {lista.length === 0 && <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,0.4)',margin:0}}>Sin mensajes.</p>}
                {lista.map(function(m) {
                    var perf = (userProfiles || {})[m.autor] || {};
                    var rep = Number(m.reportes || 0);
                    return (
                        <div key={m.id} style={{background: rep > 0 ? 'rgba(230,57,70,0.06)' : (m.oculto ? 'rgba(0,31,107,0.04)' : '#fff'),
                            border:'1px solid ' + (rep > 0 ? 'rgba(230,57,70,0.3)' : 'rgba(0,31,107,0.08)'),
                            borderRadius:10,padding:'8px 10px',marginBottom:6}}>
                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:11.5,color:'#001F6B',margin:'0 0 3px',lineHeight:1.4,
                                textDecoration: m.oculto ? 'line-through' : 'none', opacity: m.oculto ? 0.5 : 1}}>💬 {m.texto}</p>
                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:9.5,color:'rgba(0,31,107,0.45)',margin:'0 0 6px'}}>
                                {nombreVisible(m.autor, perf)} · {m.creadoEn && m.creadoEn.seconds ? new Date(m.creadoEn.seconds*1000).toLocaleString('es-ES',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Atlantic/Canary'}) : ''}
                                {rep > 0 ? ' · ⚑ ' + rep + ' reporte(s)' : ''}
                            </p>
                            <div style={{display:'flex',gap:5}}>
                                <button onClick={function(){ ocultar(m, !m.oculto); }}
                                    style={{flex:1,border:'1px solid rgba(0,31,107,0.15)',borderRadius:7,padding:'5px 7px',background:'#fff',color:'rgba(0,31,107,0.7)',fontFamily:"'Teko',sans-serif",fontSize:10.5,cursor:'pointer'}}>
                                    {m.oculto ? 'MOSTRAR' : 'OCULTAR'}
                                </button>
                                <button onClick={function(){ alternarBloqueo(m.autor); }}
                                    style={{flex:1,border:'1px solid rgba(230,57,70,0.3)',borderRadius:7,padding:'5px 7px',background:'#fff',color:'#e63946',fontFamily:"'Teko',sans-serif",fontSize:10.5,cursor:'pointer'}}>
                                    {bloqueados.indexOf(m.autor) !== -1 ? 'DESBLOQUEAR' : 'BLOQUEAR AUTOR'}
                                </button>
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

// ── Cabecera VIP: insignia con el baremo doble y el precio ──
