// ============================================================================
// 🎬 GALA · CIERRE DE LA JORNADA 1 — presentación épica de fin de edición
// ============================================================================
// Estructura ESTABLE: los datos del partido, ganadores, reparto y
// multiplicadores se leen de Firebase (no hay nada que retocar en código en
// los próximos meses), y los textos fijos (norma J22, plaza libre) pueden
// ajustarse opcionalmente desde configuracion/gala_j1 sin tocar el código.
// ============================================================================
// 🕐 PLAZOS POR ESTRUCTURA — cada pantalla marca sus propios plazos
// ============================================================================
// Fechas dinámicas desde configuracion/plazos (las rellena la Auditoría de
// plazos del admin); si no existen, se muestra la norma fija igualmente.
function formatearFechaPlazoCorta(iso) {
    try {
        return new Date(iso).toLocaleString('es-ES', { weekday:'short', day:'numeric', month:'short', hour:'2-digit', minute:'2-digit', timeZone:'Atlantic/Canary' });
    } catch(e) { return ''; }
}

const PlazosCard = ({ tipo, fechaPartidoUDLP }) => {
    var [plazos, setPlazos] = useState(null);
    useEffect(function() {
        var unsub = onSnapshot(doc(db, 'configuracion', 'plazos'), function(snap) {
            setPlazos(snap.exists() ? snap.data() : null);
        }, function(){});
        return function() { unsub(); };
    }, []);

    var lineas = [];
    if (tipo === 'porra') {
        lineas.push(['🎯', 'Apuesta y pago de la jornada: hasta el cierre publicado de cada jornada.']);
        var limOtroP = plazos && plazos.primeraJ2LimiteOtro ? ' Próximo límite: ' + formatearFechaPlazoCorta(plazos.primeraJ2LimiteOtro) + '.' : '';
        lineas.push(['🛡️', 'El Otro Equipo: hasta 1 HORA antes del primer partido de la jornada de Primera División.' + limOtroP]);
        lineas.push(['🏆', 'Porra Anual: apuesta si la UDLP ASCIENDE y en qué PUESTO acaba — da puntos para la clasificación general (modificable hasta la J6).']);
    } else if (tipo === 'otro') {
        var limOtro = plazos && plazos.primeraJ2LimiteOtro ? ' Próximo límite (J2): ' + formatearFechaPlazoCorta(plazos.primeraJ2LimiteOtro) + '.' : '';
        lineas.push(['🛡️', 'El plazo para marcar tu Otro Equipo cierra 1 HORA ANTES de que empiece el primer partido de la jornada de Primera División.' + limOtro]);
        lineas.push(['⚖️', 'Las activaciones fuera de plazo no aplican multiplicador en esa jornada.']);
    } else if (tipo === 'estrellas') {
        var limEst = '';
        if (fechaPartidoUDLP) {
            try {
                var f = new Date(fechaPartidoUDLP);
                if (!isNaN(f.getTime())) limEst = ' Esta jornada: hasta las ' + new Date(f.getTime() - 2*3600*1000).toLocaleString('es-ES', { weekday:'short', day:'numeric', month:'short', hour:'2-digit', minute:'2-digit', timeZone:'Atlantic/Canary' }) + '.';
            } catch(e) {}
        }
        lineas.push(['⭐', 'Tus 5 Estrellas se pueden elegir y cambiar hasta 2 HORAS ANTES del partido de la UDLP de la jornada.' + limEst]);
    }

    return (
        <div style={{background:'rgba(0,31,107,0.035)',border:'1px dashed rgba(0,31,107,0.22)',borderRadius:12,padding:'10px 12px',marginBottom:16}}>
            <p style={{fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:3,color:'rgba(0,31,107,0.55)',textTransform:'uppercase',marginBottom:6,fontWeight:700}}>🕐 PLAZOS DE ESTA SECCIÓN</p>
            {lineas.map(function(l, i) {
                return (
                    <p key={i} style={{fontFamily:"'Inter',sans-serif",fontSize:10.5,color:'rgba(0,31,107,0.65)',lineHeight:1.55,margin:'0 0 4px',display:'flex',gap:6}}>
                        <span style={{flexShrink:0}}>{l[0]}</span><span>{l[1]}</span>
                    </p>
                );
            })}
        </div>
    );
};

// ============================================================================
// 📣 CIERRE EXTENDIDO DE LA JORNADA 1 — visible hasta el 20/08 a las 22:00
// ============================================================================
const CierreExtendidoJ1 = ({ userProfiles, currentUser }) => {
    var [clasif, setClasif] = useState([]);
    var [plazos, setPlazos] = useState(null);
    var [estrellasPendCE, setEstrellasPendCE] = useState({});
    useEffect(function() {
        var unsub1 = onSnapshot(collection(db, 'clasificacion'), function(snap) {
            var datos = snap.docs.map(function(d) { return { id: d.id, ...d.data() }; });
            setClasif(datos);
        }, function(){});
        var unsub2 = onSnapshot(doc(db, 'configuracion', 'plazos'), function(snap) {
            setPlazos(snap.exists() ? snap.data() : null);
        }, function(){});
        // Puntos de 5 Estrellas de jornadas aún sin cierre definitivo: se
        // suman al total mostrado para que la tabla los refleje YA.
        (async function() {
            try {
                var pend = {};
                var jSnap = await getDocs(query(collection(db, 'jornadas'), where('estado', '==', 'Finalizada')));
                var sumarPend = function(docs) {
                    docs.forEach(function(d) {
                        pend[d.id] = (pend[d.id] || 0) + Number((d.data() || {}).puntosRanking || 0);
                    });
                };
                var sumarBase = function(docs) {
                    docs.forEach(function(d) {
                        var p = d.data() || {};
                        if (p.noContabilizado) return;
                        pend[d.id] = (pend[d.id] || 0) + Number(p.puntosBaseSinOtro || 0);
                    });
                };
                for (var i = 0; i < jSnap.docs.length; i++) {
                    if ((jSnap.docs[i].data() || {}).cierreDefinitivo) continue;
                    var jidPend = jSnap.docs[i].id;
                    var rSnap = await getDocs(collection(db, 'estrellas_resultados', jidPend, 'jugadores'));
                    sumarPend(rSnap.docs);
                    var pSnapCE = await getDocs(collection(db, 'pronosticos', jidPend, 'jugadores'));
                    sumarBase(pSnapCE.docs);
                }
                setEstrellasPendCE(pend);
            } catch(e) {}
        })();
        return function() { unsub1(); unsub2(); };
    }, []);
    var clasifMostrada = clasif.map(function(j) {
        return { ...j, puntosTotales: (j.puntosTotales || 0) + Number(estrellasPendCE[j.id] || 0) };
    }).sort(function(a, b) { return (b.puntosTotales || 0) - (a.puntosTotales || 0); });

    var finJ1 = plazos && plazos.primeraJ1UltimoPartido ? formatearFechaPlazoCorta(plazos.primeraJ1UltimoPartido) : '';
    var limJ2 = plazos && plazos.primeraJ2LimiteOtro ? formatearFechaPlazoCorta(plazos.primeraJ2LimiteOtro) : '';

    return (
        <div style={{background:'#fff',border:'1px solid rgba(255,215,0,0.5)',borderRadius:18,overflow:'hidden',marginBottom:18,boxShadow:'0 4px 16px rgba(0,31,107,0.08)'}}>
            <div style={{background:'linear-gradient(120deg,#001F6B,#0035b8)',padding:'12px 16px'}}>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:15,letterSpacing:3,color:'#FFD700',textTransform:'uppercase',margin:0,fontWeight:700}}>📣 JORNADA 1 · CIERRE EXTENDIDO</p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(255,255,255,0.6)',margin:'3px 0 0'}}>Alargamos la exposición de la J1 tras el arranque con mantenimiento. Esto es lo que hay y lo que viene:</p>
            </div>
            <div style={{padding:'14px 16px'}}>
                {/* Clasificación total actual */}
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:2,color:'rgba(0,31,107,0.5)',textTransform:'uppercase',marginBottom:8,fontWeight:700}}>CLASIFICACIÓN TOTAL HASTA AHORA *</p>
                <div style={{border:'1px solid rgba(0,31,107,0.08)',borderRadius:12,overflow:'hidden',marginBottom:10}}>
                    {clasifMostrada.map(function(j, i) {
                        var perf = userProfiles[j.id] || {};
                        return (
                            <div key={j.id} style={{display:'flex',alignItems:'center',gap:8,padding:'6px 12px',borderBottom:'1px solid rgba(0,31,107,0.04)',background: j.id === currentUser ? 'rgba(255,215,0,0.07)' : 'transparent'}}>
                                <span style={{fontFamily:"'Teko',sans-serif",fontSize:13,fontWeight:700,width:20,textAlign:'center',color: i===0?'#FFD700':i===1?'#C0C0C0':i===2?'#CD7F32':'rgba(0,31,107,0.3)'}}>{i===0?'🥇':i===1?'🥈':i===2?'🥉':(i+1)}</span>
                                <IconoPerfil perfil={perf} size={22} />
                                <span style={{flex:1,fontFamily:"'Inter',sans-serif",fontSize:11.5,fontWeight: j.id === currentUser ? 700 : 500,color:'#001F6B'}}>{nombreVisible(j.id, perf)}</span>
                                <span style={{fontFamily:"'Teko',sans-serif",fontSize:17,fontWeight:700,color:'#001F6B'}}>{j.puntosTotales || 0}</span>
                            </div>
                        );
                    })}
                </div>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(0,31,107,0.55)',lineHeight:1.6,marginBottom:12}}>
                    * <strong>Quedan cambios pendientes:</strong> la J1 no se cierra del todo hasta que se resuelvan los Otros Equipos, al terminar la jornada 1 de Primera División{finJ1 ? ' (último partido: ' + finJ1 + ')' : ' la próxima semana'}. Los multiplicadores y divisores pueden mover esta tabla.
                </p>

                {/* Agenda */}
                <div style={{background:'rgba(0,31,107,0.04)',borderRadius:12,padding:'10px 12px',marginBottom:12}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:2,color:'rgba(0,31,107,0.55)',textTransform:'uppercase',marginBottom:6,fontWeight:700}}>🗓️ LO QUE VIENE</p>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:10.5,color:'rgba(0,31,107,0.7)',lineHeight:1.7,margin:0}}>
                        · <strong>Mañana 22:00</strong> — preapertura de la Jornada 2.<br/>
                        · <strong>Viernes 18:00</strong> — apertura de apuestas de la J2.<br/>
                        · <strong>El Otro Equipo</strong> — límite 1 HORA antes del primer partido de la J2 de Primera{limJ2 ? ' (' + limJ2 + ')' : ''}.<br/>
                        · <strong>5 Estrellas</strong> — límite 2 HORAS antes del partido de la UDLP de la jornada.
                    </p>
                </div>

                {/* Porra anual */}
                <div style={{background:'rgba(255,215,0,0.08)',border:'1px solid rgba(255,215,0,0.3)',borderRadius:12,padding:'10px 12px'}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:2,color:'#8a6a00',textTransform:'uppercase',marginBottom:4,fontWeight:700}}>🏆 NO OLVIDES LA PORRA ANUAL</p>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:10.5,color:'rgba(0,31,107,0.7)',lineHeight:1.6,margin:0}}>
                        Apuesta si la UDLP <strong>ASCIENDE o no</strong> y en <strong>qué puesto acaba</strong> la temporada: da puntos para la clasificación general. La tienes en Mi Jornada y puedes modificarla hasta la J6.
                    </p>
                </div>
            </div>
        </div>
    );
};

// ============================================================================
// 📣 BANNER DE CAPTACIÓN — plazas libres + equipos de Primera sin dueño
// ============================================================================
// Cierra el ciclo de las vacantes: no basta con registrar que hay huecos, hay
// que enseñarlos y que la peña los comparta. Se calcula solo con datos reales
// y desaparece cuando el grupo se completa.
const BannerPlazasLibres = () => {
    var [plazas, setPlazas] = useState(null);
    var [equiposLibres, setEquiposLibres] = useState(null);

    useEffect(function() {
        var unsub1 = onSnapshot(doc(db, 'configuracion', 'plazasLibres'), function(s) {
            setPlazas(s.exists() ? Number(s.data().cantidad || 0) : null);
        }, function(){});
        var unsub2 = onSnapshot(collection(db, 'elOtro'), function(snap) {
            var cogidos = {};
            snap.forEach(function(d) { var dd = d.data() || {}; if (dd.equipo) cogidos[dd.equipo] = true; });
            setEquiposLibres(Math.max(0, 20 - Object.keys(cogidos).length));
        }, function(){});
        return function() { unsub1(); unsub2(); };
    }, []);

    if (plazas === null || plazas <= 0) return null;
    var textoWa = '⚽ ¡Se buscan jugadores para la PORRA UDLP 26/27! Quedan ' + plazas + ' plaza' + (plazas === 1 ? '' : 's') +
        (equiposLibres ? ' y ' + equiposLibres + ' equipos de Primera SIN DUEÑO para elegir' : '') +
        '. Acierta el resultado de cada jornada, premios, rifas y liga de estrellas. Pide tu plaza aquí 👉 https://porra2026.netlify.app';

    return (
        <div style={{background:'linear-gradient(135deg,#001F6B,#0035b8)',border:'1px solid rgba(255,215,0,0.4)',borderRadius:16,padding:'14px 16px',marginBottom:14,boxShadow:'0 6px 20px rgba(0,31,107,0.25)'}}>
            <p style={{fontFamily:"'Teko',sans-serif",fontSize:11,letterSpacing:4,color:'rgba(255,215,0,0.6)',textTransform:'uppercase',margin:'0 0 2px'}}>📣 BUSCAMOS REFUERZOS</p>
            <p style={{fontFamily:"'Teko',sans-serif",fontSize:26,fontWeight:700,color:'#FFD700',letterSpacing:1,lineHeight:1,margin:'0 0 6px'}}>
                {plazas} PLAZA{plazas === 1 ? '' : 'S'} LIBRE{plazas === 1 ? '' : 'S'}
            </p>
            <p style={{fontFamily:"'Inter',sans-serif",fontSize:11.5,color:'rgba(255,255,255,0.72)',lineHeight:1.6,margin:'0 0 10px'}}>
                {equiposLibres > 0
                    ? <span>🛡️ Y quedan <strong style={{color:'#FFD700'}}>{equiposLibres} equipos de Primera sin dueño</strong>: quien entre ahora elige de lo que queda de la élite.</span>
                    : <span>Trae a quien creas que puede aguantar el ritmo de la porra 😏</span>}
            </p>
            <a href={'https://wa.me/?text=' + encodeURIComponent(textoWa)} target="_blank" rel="noopener noreferrer"
                style={{display:'block',textAlign:'center',textDecoration:'none',background:'#25D366',color:'#fff',borderRadius:12,padding:'10px',fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:1}}>
                📲 INVITAR A ALGUIEN POR WHATSAPP
            </a>
        </div>
    );
};

const PresentacionGalaJ1 = ({ onClose, userProfiles }) => {
    var [slide, setSlide] = useState(0);
    var [j1, setJ1] = useState(null);
    var [multiplicadores, setMultiplicadores] = useState([]);
    var [configGala, setConfigGala] = useState({});
    var [plazosGala, setPlazosGala] = useState({});
    var [equiposLibresPrimera, setEquiposLibresPrimera] = useState(null);
    var [cargando, setCargando] = useState(true);

    useEffect(function() {
        (async function() {
            try {
                var snap = await getDocs(query(collection(db, 'jornadas'), where('numeroJornada', '==', 1), limit(1)));
                if (!snap.empty) setJ1({ id: snap.docs[0].id, ...snap.docs[0].data() });
                var otroSnap = await getDocs(collection(db, 'elOtro'));
                var lista = [];
                var equiposCogidos = {};
                otroSnap.forEach(function(d) {
                    var dd = d.data();
                    if (dd.equipo) equiposCogidos[dd.equipo] = true;
                    var h = (dd.historial || []).find(function(x) { return x.jornada === 1; });
                    if (h) lista.push({ usuario: d.id, multiplicador: Number(h.multiplicador || 1) });
                });
                setEquiposLibresPrimera(Math.max(0, 20 - Object.keys(equiposCogidos).length));
                lista.sort(function(a, b) { return b.multiplicador - a.multiplicador; });
                setMultiplicadores(lista);
                var cfg = await getDoc(doc(db, 'configuracion', 'gala_j1'));
                if (cfg.exists()) setConfigGala(cfg.data());
                var plz = await getDoc(doc(db, 'configuracion', 'plazos'));
                if (plz.exists()) setPlazosGala(plz.data());
            } catch(e) { console.warn('Gala J1:', e.message); }
            setCargando(false);
        })();
    }, []);

    var ganadores = j1 && Array.isArray(j1.ganadores) ? j1.ganadores : [];
    var premioCada = j1 && j1.premioPorGanador !== undefined ? Number(j1.premioPorGanador) : null;
    var boteTotal = j1 && j1.boteTotal !== undefined ? Number(j1.boteTotal) : null;
    var jugadorSeVa = configGala.jugadorSeVa || '';

    var slides = [
        // 0 · PORTADA
        function() { return (
            <div style={{textAlign:'center'}}>
                <p style={{fontSize:40,marginBottom:8}}>🎬</p>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:15,letterSpacing:6,color:'rgba(255,215,0,0.55)',textTransform:'uppercase',marginBottom:8}}>PORRA UDLP 26/27</p>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:32,fontWeight:700,letterSpacing:3,color:'#FFD700',lineHeight:1.05,marginBottom:10}}>LA GALA DE LA<br/>JORNADA 1</p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:13,color:'rgba(255,255,255,0.65)',lineHeight:1.7}}>
                    La primera edición ya es historia.<br/>Resultado, premios, multiplicadores…<br/>y lo que viene. 👀
                </p>
            </div>
        ); },
        // 1 · EL PARTIDO
        function() { return (
            <div style={{textAlign:'center'}}>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:5,color:'rgba(255,215,0,0.5)',textTransform:'uppercase',marginBottom:16}}>⚽ EL PARTIDO</p>
                {j1 ? (
                    <>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:20,color:'#fff',marginBottom:4}}>{j1.equipoLocal}</p>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:52,fontWeight:700,color:'#FFD700',letterSpacing:7,lineHeight:1,margin:'5px 0'}}>{j1.resultadoLocal} – {j1.resultadoVisitante}</p>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:20,color:'#fff',marginBottom:16}}>{j1.equipoVisitante}</p>
                    {j1.primerGoleador && <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(255,255,255,0.6)'}}>Primer goleador: <strong style={{color:'#FFD700'}}>{j1.primerGoleador}</strong></p>}
                    </>
                ) : <p style={{fontFamily:"'Inter',sans-serif",fontSize:13,color:'rgba(255,255,255,0.6)'}}>Cargando el resultado…</p>}
            </div>
        ); },
        // 2 · GANADORES Y REPARTO
        function() { return (
            <div style={{textAlign:'center'}}>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:5,color:'rgba(255,215,0,0.5)',textTransform:'uppercase',marginBottom:16}}>🏆 LOS GANADORES</p>
                {ganadores.length ? (
                    <>
                    <div style={{display:'flex',flexDirection:'column',gap:8,alignItems:'center',marginBottom:18}}>
                        {ganadores.map(function(g) {
                            var perf = userProfiles[g] || {};
                            return (
                                <div key={g} style={{display:'flex',alignItems:'center',gap:10,background:'rgba(255,215,0,0.08)',border:'1px solid rgba(255,215,0,0.25)',borderRadius:30,padding:'6px 18px 6px 6px'}}>
                                    <IconoPerfil perfil={perf} size={32} />
                                    <span style={{fontFamily:"'Teko',sans-serif",fontSize:19,color:'#FFD700',letterSpacing:1}}>{nombreVisible(g, perf)}</span>
                                </div>
                            );
                        })}
                    </div>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(255,255,255,0.7)',lineHeight:1.8}}>
                        {ganadores.length === 1 ? 'Único acertante del resultado exacto.' : ganadores.length + ' acertantes del resultado exacto.'}<br/>
                        {boteTotal !== null && <span>Bote de la jornada: <strong style={{color:'#FFD700'}}>{boteTotal.toFixed(2)}€</strong><br/></span>}
                        {premioCada !== null && <span>Premio: <strong style={{color:'#FFD700'}}>{premioCada.toFixed(2)}€ para cada uno</strong> 💰<br/></span>}
                        El premio espera en <strong>Mi Jornada</strong>: cobrarlo, usarlo en la rifa… o repartirlo.
                    </p>
                    </>
                ) : (
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:13,color:'rgba(255,255,255,0.65)',lineHeight:1.8}}>Nadie clavó el resultado exacto esta vez.<br/>El bote sigue creciendo para la próxima. 🍯</p>
                )}
            </div>
        ); },
        // 3 · PRIMERA CERRADA · MULTIPLICADORES
        function() { return (
            <div style={{textAlign:'center'}}>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:5,color:'rgba(255,215,0,0.5)',textTransform:'uppercase',marginBottom:10}}>🛡️ EL OTRO EQUIPO</p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(255,255,255,0.7)',lineHeight:1.7,marginBottom:14}}>
                    La jornada 1 de Primera División quedó cerrada y con ella se aplicaron los multiplicadores y divisores de <strong>El Otro Equipo</strong>:
                </p>
                {multiplicadores.length ? (
                    <div style={{display:'flex',flexDirection:'column',gap:6,maxHeight:'34dvh',overflowY:'auto',marginBottom:12}}>
                        {multiplicadores.map(function(m) {
                            var perf = userProfiles[m.usuario] || {};
                            var sube = m.multiplicador > 1;
                            var baja = m.multiplicador < 1;
                            return (
                                <div key={m.usuario} style={{display:'flex',alignItems:'center',gap:10,background:'rgba(255,255,255,0.04)',borderRadius:12,padding:'6px 12px'}}>
                                    <IconoPerfil perfil={perf} size={26} />
                                    <span style={{flex:1,textAlign:'left',fontFamily:"'Inter',sans-serif",fontSize:12,color:'#fff'}}>{nombreVisible(m.usuario, perf)}</span>
                                    <span style={{fontFamily:"'Teko',sans-serif",fontSize:18,fontWeight:700,color: sube ? '#FFD700' : baja ? '#ff6b6b' : 'rgba(255,255,255,0.4)'}}>
                                        {sube ? '×' + m.multiplicador : baja ? '÷2' : '—'}
                                    </span>
                                </div>
                            );
                        })}
                    </div>
                ) : (
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(255,255,255,0.55)',marginBottom:14}}>Esta jornada nadie activó su Otro Equipo.</p>
                )}
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'#FFD700',lineHeight:1.7,background:'rgba(255,215,0,0.08)',border:'1px solid rgba(255,215,0,0.25)',borderRadius:10,padding:'8px 12px',marginBottom:8}}>
                    ⏳ <strong>Pendiente de resolver:</strong> los multiplicadores de esta jornada se aplican cuando termine la J1 de Primera{plazosGala.primeraJ1UltimoPartido ? ' — último partido: ' + formatearFechaPlazoCorta(plazosGala.primeraJ1UltimoPartido) : ', la próxima semana'}.
                </p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(255,255,255,0.45)',lineHeight:1.7,background:'rgba(255,255,255,0.04)',borderRadius:10,padding:'8px 12px'}}>
                    📋 Recordatorio de norma: solo cuentan las elecciones confirmadas <strong>antes del inicio del primer partido de Primera</strong>. Las realizadas fuera de plazo no aplican multiplicador en esa jornada.
                </p>
            </div>
        ); },
        // 4 · NUEVA NORMA · JORNADA 22
        function() { return (
            <div style={{textAlign:'center'}}>
                <p style={{fontSize:40,marginBottom:10}}>📜</p>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:5,color:'rgba(255,215,0,0.5)',textTransform:'uppercase',marginBottom:10}}>NUEVA NORMA OFICIAL</p>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:26,fontWeight:700,color:'#FFD700',letterSpacing:2,marginBottom:14}}>EL RE-DRAFT DE LA JORNADA 22</p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:13,color:'rgba(255,255,255,0.75)',lineHeight:1.9}}>
                    Cuando arranque la <strong>segunda vuelta (jornada 22)</strong>, todos volveréis a elegir vuestro Otro Equipo.<br/><br/>
                    El orden de elección será <strong style={{color:'#FFD700'}}>el inverso a la clasificación global</strong> en ese momento:<br/>
                    el <strong>último</strong> de la tabla elegirá <strong>primero</strong>…<br/>
                    y el <strong>líder</strong> elegirá <strong>el último</strong>. ⚖️
                </p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(255,255,255,0.45)',marginTop:14}}>Ir mal en la tabla nunca tuvo tanto premio.</p>
            </div>
        ); },
        // 5 · 6 PLAZAS LIBRES · RECLUTAMIENTO
        function() { return (
            <div style={{textAlign:'center'}}>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:5,color:'rgba(255,215,0,0.5)',textTransform:'uppercase',marginBottom:8}}>📣 BUSCAMOS REFUERZOS</p>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:44,fontWeight:700,color:'#FFD700',letterSpacing:2,lineHeight:1,marginBottom:4}}>6 PLAZAS<br/>LIBRES</p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:12.5,color:'rgba(255,255,255,0.75)',lineHeight:1.8,marginBottom:12}}>
                    Ahora mismo somos <strong style={{color:'#FFD700'}}>14 jugadores</strong> y queremos completar el vestuario esta temporada.
                </p>
                <div style={{background:'rgba(255,255,255,0.05)',borderRadius:12,padding:'10px 14px',marginBottom:12}}>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(255,255,255,0.75)',lineHeight:1.7,margin:0}}>
                        🛡️ Y ojo, que hay chollo: {equiposLibresPrimera !== null && equiposLibresPrimera > 0 ? <span>todavía quedan <strong style={{color:'#FFD700'}}>{equiposLibresPrimera} equipos de Primera SIN DUEÑO</strong></span> : <span>todavía quedan <strong style={{color:'#FFD700'}}>equipos de Primera SIN DUEÑO</strong></span>} para El Otro Equipo — quien entre ahora elige entre lo que queda de la élite para multiplicar sus puntos.
                    </p>
                </div>
                <div style={{background:'rgba(255,215,0,0.08)',border:'1px solid rgba(255,215,0,0.25)',borderRadius:14,padding:14}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:17,color:'#FFD700',letterSpacing:1,marginBottom:6}}>📣 TRAE A LOS TUYOS</p>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(255,255,255,0.7)',lineHeight:1.7,margin:0}}>
                        Familia, amigos, compañeros con hambre de porra: que soliciten su plaza desde la pantalla de inicio de la app. <strong>Primero en llegar, primero en elegir equipo.</strong> Comparte esta gala y que corra la voz. 💛💙
                    </p>
                </div>
            </div>
        ); },
        // 6 · CIERRE
        function() { return (
            <div style={{textAlign:'center'}}>
                <p style={{fontSize:40,marginBottom:8}}>🏁</p>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:30,fontWeight:700,color:'#FFD700',letterSpacing:3,lineHeight:1.15,marginBottom:10}}>QUE EMPIECE<br/>LA LIGA</p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:13,color:'rgba(255,255,255,0.65)',lineHeight:1.8,marginBottom:14}}>
                    41 jornadas por delante.<br/>Estrellas, rifas, multiplicadores…<br/>y una porra que ganar.<br/><br/>Suerte a todos. 💙💛
                </p>
                <div style={{background:'rgba(255,215,0,0.08)',border:'1px solid rgba(255,215,0,0.25)',borderRadius:12,padding:'10px 14px'}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:14,color:'#FFD700',letterSpacing:2,marginBottom:4}}>🏆 Y NO OLVIDES LA PORRA ANUAL</p>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(255,255,255,0.7)',lineHeight:1.6,margin:0}}>¿Asciende la UDLP? ¿En qué puesto acaba? Tu apuesta anual da puntos para la clasificación general — la tienes en Mi Jornada (modificable hasta la J6).</p>
                </div>
            </div>
        ); },
    ];

    var esUltima = slide >= slides.length - 1;

    return (
        <CapaEmergente>
        <div style={{position:'fixed',top:0,left:0,right:0,bottom:0,zIndex:10500,background:'linear-gradient(160deg,#060614,#0d1b3e 55%,#001F6B)',display:'flex',flexDirection:'column',padding:'14px 18px calc(12px + env(safe-area-inset-bottom))',height:'100dvh',maxHeight:'100dvh',boxSizing:'border-box',overflow:'hidden'}}>
            <style>{'@keyframes galaIn{0%{opacity:0;transform:translateY(16px);}100%{opacity:1;transform:translateY(0);}}'}</style>
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',flexShrink:0}}>
                <span style={{fontFamily:"'Teko',sans-serif",fontSize:11,letterSpacing:3,color:'rgba(255,255,255,0.35)'}}>PORRA UDLP · GALA J1</span>
                <button onClick={onClose} style={{border:'none',background:'rgba(255,255,255,0.08)',color:'rgba(255,255,255,0.6)',borderRadius:20,padding:'4px 12px',fontFamily:"'Teko',sans-serif",fontSize:11,letterSpacing:2,cursor:'pointer'}}>SALIR ✕</button>
            </div>
            {/* Zona central: si el contenido es más alto que la pantalla, hace
                scroll AQUÍ DENTRO — la cabecera, los puntos y los botones no se
                mueven nunca y SIGUIENTE siempre queda a la vista. */}
            <div key={slide} style={{flex:1,minHeight:0,overflowY:'auto',display:'flex',animation:'galaIn 0.5s ease',WebkitOverflowScrolling:'touch'}}>
                <div style={{maxWidth:380,width:'100%',margin:'auto',padding:'10px 0'}}>
                    {cargando && slide > 0 ? <p style={{textAlign:'center',fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(255,255,255,0.5)'}}>Cargando…</p> : slides[slide]()}
                </div>
            </div>
            <div style={{display:'flex',justifyContent:'center',gap:6,marginBottom:10,flexShrink:0,paddingTop:8}}>
                {slides.map(function(_, i) {
                    return <span key={i} style={{width:i===slide?18:7,height:7,borderRadius:4,background:i===slide?'#FFD700':'rgba(255,255,255,0.2)',transition:'all 0.3s'}} />;
                })}
            </div>
            <div style={{display:'flex',gap:10,flexShrink:0}}>
                {slide > 0 && (
                    <button onClick={function(){ setSlide(slide - 1); }}
                        style={{flex:1,border:'1px solid rgba(255,255,255,0.2)',background:'transparent',color:'rgba(255,255,255,0.6)',borderRadius:30,padding:11,fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:2,cursor:'pointer'}}>ATRÁS</button>
                )}
                <button onClick={function(){ if (esUltima) onClose(); else setSlide(slide + 1); }}
                    style={{flex:2,border:'none',background:'#FFD700',color:'#001F6B',borderRadius:30,padding:11,fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:2,fontWeight:700,cursor:'pointer',boxShadow:'0 6px 18px rgba(255,215,0,0.35)'}}>
                    {slide === 0 ? '🎬 EMPEZAR' : esUltima ? 'CERRAR LA GALA 🏁' : 'SIGUIENTE →'}
                </button>
            </div>
        </div>
        </CapaEmergente>
    );
};

const LaJornadaScreen = ({ userProfiles, onlineUsers, teamLogos }) => {
    var G = styles.colors;
    var [mostrarGala, setMostrarGala] = useState(false);
    var [jornada, setJornada] = useState(null);
    var [participantes, setParticipantes] = useState([]);
    var [elOtroTodos, setElOtroTodos] = useState({});
    var [partidosPrimera, setPartidosPrimera] = useState([]);
    var [proximaUDLP, setProximaUDLP] = useState(null);
    var [ultimosUDLP, setUltimosUDLP] = useState([]);
    var [detalleFixtureActual, setDetalleFixtureActual] = useState(null);
    // OJO: aquí NO se puede usar new Date().toISOString() como valor por
    // defecto — cambia en cada render, el useEffect que depende de esta
    // variable se re-dispara en bucle y la pantalla refetchea y "salta"
    // constantemente. El valor por defecto se resuelve DENTRO del efecto.
    var fechaJornadaLJ = jornada ? fechaAString(getFechaPartidoISO(jornada) || jornada.fecha) : '';
    var fixtureIdLJ = jornada && jornada.fixtureId ? jornada.fixtureId : null;

    useEffect(function() {
        var base = fechaJornadaLJ || new Date().toISOString();
        buscarJornadaCompletaPrimera(base, 8).then(function(r){setPartidosPrimera(r||[]);}).catch(function(){});
        buscarProximoPartidoUDLP().then(setProximaUDLP).catch(function(){});
        buscarUltimosPartidosUDLP(3).then(setUltimosUDLP).catch(function(){});
    }, [fechaJornadaLJ]);

    useEffect(function(){
        setDetalleFixtureActual(null);
        if(!fixtureIdLJ || !API_FOOTBALL_KEY) return;
        fetch('https://v3.football.api-sports.io/fixtures?id='+fixtureIdLJ,{headers:{'x-apisports-key':API_FOOTBALL_KEY}})
            .then(function(r){return r.json();})
            .then(function(d){if(d.response&&d.response[0])setDetalleFixtureActual(d.response[0]);})
            .catch(function(){});
    }, [fixtureIdLJ]);
    var [clasifEstrellas, setClasifEstrellas] = useState([]);
    var [seleccionesEstrellasJornada, setSeleccionesEstrellasJornada] = useState([]); // para la comparativa en vivo
    var [loading, setLoading] = useState(true);
    // Lista completa de jugadores registrados — para que se vea a todo el
    // grupo aquí, no solo a quien ya ha apostado.
    var [jugadoresAprobadosLJ, setJugadoresAprobadosLJ] = useState([]);
    var [jugadoresInactivosLJ, setJugadoresInactivosLJ] = useState([]);
    var JUGADORES_TODOS_LJ = Array.from(new Set(JUGADORES_FUNDADORES.concat(jugadoresAprobadosLJ)));
    var JUGADORES_ACTIVOS_LJ = JUGADORES_TODOS_LJ.filter(function(j) { return jugadoresInactivosLJ.indexOf(j) === -1; });

    useEffect(function() {
        var unsub = onSnapshot(doc(db, 'configuracion', 'jugadoresAprobados'), function(snap) {
            setJugadoresAprobadosLJ(snap.exists() ? (snap.data().nombres || []) : []);
        });
        return function() { unsub(); };
    }, []);
    useEffect(function() {
        var unsub = onSnapshot(doc(db, 'configuracion', 'jugadoresInactivos'), function(snap) {
            setJugadoresInactivosLJ(snap.exists() ? (snap.data().nombres || []) : []);
        });
        return function() { unsub(); };
    }, []);

    useEffect(function() {
        var unsubEst = onSnapshot(collection(db, "clasificacion_estrellas"), function(snap) {
            var datos = snap.docs.map(function(d) { return { id: d.id, ...d.data() }; })
                .sort(function(a,b) { return (b.puntosEstrellas||0) - (a.puntosEstrellas||0); });
            setClasifEstrellas(datos);
        });
        return function() { unsubEst(); };
    }, []);

    useEffect(function() {
        // Los listeners de pronósticos/estrellas se recrean cada vez que el
        // snapshot de jornadas dispara. Antes se creaban SIN darse de baja los
        // anteriores: se acumulaban listeners duplicados que pisaban el estado
        // entre sí y provocaban los saltos de imagen. Ahora se guarda la
        // referencia y solo se resuscribe si cambia la jornada seleccionada.
        var unsubPron = null;
        var unsubEstSel = null;
        var jornadaSuscrita = null;
        var q = query(collection(db, "jornadas"), orderBy("numeroJornada","desc"), limit(50));
        var unsub = onSnapshot(q, function(snap) {
            var lista = snap.docs.map(function(d){ return {id:d.id,...d.data()}; });
            var activa = lista.find(function(j){ return j.estado === 'Abierta' || j.estado === 'En vivo'; });
            var reciente = lista.find(function(j){ return j.estado === 'Finalizada' && jornadaDentroVentana72h(j, Date.now()); });
            var j = activa || reciente || null;
            setJornada(j);
            if (j) {
                if (jornadaSuscrita !== j.id) {
                    if (unsubPron) { unsubPron(); unsubPron = null; }
                    if (unsubEstSel) { unsubEstSel(); unsubEstSel = null; }
                    jornadaSuscrita = j.id;
                    unsubPron = onSnapshot(collection(db, "pronosticos", j.id, "jugadores"), function(ps) {
                        setParticipantes(ps.docs.map(function(d) { return { id: d.id, ...d.data() }; }));
                    }, function(){});
                    unsubEstSel = onSnapshot(collection(db, "estrellas_seleccion", j.id, "jugadores"), function(es) {
                        setSeleccionesEstrellasJornada(es.docs.map(function(d) { return { id: d.id, ...d.data() }; }));
                    }, function(){});
                }
            } else {
                if (unsubPron) { unsubPron(); unsubPron = null; }
                if (unsubEstSel) { unsubEstSel(); unsubEstSel = null; }
                jornadaSuscrita = null;
                setParticipantes([]);
                setSeleccionesEstrellasJornada([]);
            }
            setLoading(false);
        });
        // El Otro Equipo de todos los jugadores
        var unsubOtro = onSnapshot(collection(db, "elOtro"), function(snap) {
            var m = {};
            snap.forEach(function(d) { m[d.id] = d.data(); });
            setElOtroTodos(m);
        });
        return function() {
            unsub();
            unsubOtro();
            if (unsubPron) unsubPron();
            if (unsubEstSel) unsubEstSel();
        };
    }, []);

    if (loading) return <LoadingSkeleton />;

    // Blindaje: durante la ventana entre jornadas puede no existir una jornada
    // activa ni una finalizada dentro de las últimas 48h. En ese caso NO se
    // puede continuar renderizando usando jornada.estado porque jornada es null.
    // Mostramos igualmente la información útil de la siguiente jornada/histórico.
    if (!jornada && !proximaUDLP) {
        return (
            <div style={{paddingBottom:40}}>
                <h2 style={styles.title}>LA JORNADA</h2>
                <div style={{background:'#fff',border:'1px solid rgba(0,31,107,.08)',borderRadius:18,padding:22,textAlign:'center',marginBottom:16}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:18,letterSpacing:2,color:'#001F6B',marginBottom:6}}>JORNADA EN PREPARACIÓN</p>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(0,31,107,.55)',lineHeight:1.6,margin:0}}>Estamos actualizando la información de la próxima jornada. Vuelve a entrar en unos minutos.</p>
                </div>
                {ultimosUDLP.length>0 && <div style={{background:'#fff',borderRadius:16,border:'1px solid rgba(0,31,107,.08)',overflow:'hidden'}}>
                    <div style={{padding:'12px 16px',background:'rgba(0,31,107,.04)'}}><p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:3,color:G.deepBlue,opacity:.5}}>HISTÓRICO RECIENTE</p></div>
                    {ultimosUDLP.map(function(p){return <div key={p.fixtureId} style={{display:'flex',alignItems:'center',gap:10,padding:'10px 16px',borderBottom:'1px solid rgba(0,31,107,.05)'}}>
                        <span style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(0,31,107,.4)',minWidth:84}}>{new Date(p.fecha).toLocaleDateString('es-ES',{day:'numeric',month:'short',timeZone:'Atlantic/Canary'})}</span>
                        <span style={{flex:1,fontFamily:"'Teko',sans-serif",fontSize:14,color:G.deepBlue}}>{p.local} — {p.visitante}</span>
                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:15,fontWeight:700,color:G.deepBlue}}>{p.golesLocal}—{p.golesVisitante}</span>
                    </div>;})}
                </div>}
            </div>
        );
    }

    // Solo cuando NO hay jornada seleccionable (ni activa ni finalizada en
    // ventana de 72h) se muestra el atajo de "próxima jornada". Antes también
    // entraba aquí la jornada Finalizada y se ocultaba toda la información
    // post-partido (marcador, pronósticos, estrellas, ganadores) que es
    // exactamente lo que procede ver durante esas 72 horas.
    if (!jornada && proximaUDLP) {
        var fp=new Date(proximaUDLP.fecha);
        return <div style={{paddingBottom:40}}>
            <h2 style={styles.title}>LA JORNADA</h2>
            <div style={{background:'#001F6B',borderRadius:20,padding:24,textAlign:'center',marginBottom:16}}>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:4,color:'rgba(255,255,255,.4)',textTransform:'uppercase',marginBottom:8}}>PRÓXIMA JORNADA</p>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:24,fontWeight:700,color:'#fff',marginBottom:6}}>{proximaUDLP.local} — {proximaUDLP.visitante}</p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'#FFD700'}}>{fp.toLocaleString('es-ES',{weekday:'long',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit',timeZone:'Atlantic/Canary'})}</p>
                {proximaUDLP.estadio && <p style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(255,255,255,.4)',marginTop:4}}>🏟️ {proximaUDLP.estadio}</p>}
            </div>
            {ultimosUDLP.length>0 && <div style={{background:'#fff',borderRadius:16,border:'1px solid rgba(0,31,107,.08)',overflow:'hidden'}}>
                <div style={{padding:'12px 16px',background:'rgba(0,31,107,.04)'}}><p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:3,color:G.deepBlue,opacity:.5}}>HISTÓRICO RECIENTE</p></div>
                {ultimosUDLP.map(function(p){return <div key={p.fixtureId} style={{display:'flex',alignItems:'center',gap:10,padding:'10px 16px',borderBottom:'1px solid rgba(0,31,107,.05)'}}>
                    <span style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(0,31,107,.4)',minWidth:84}}>{new Date(p.fecha).toLocaleDateString('es-ES',{day:'numeric',month:'short',timeZone:'Atlantic/Canary'})}</span>
                    <span style={{flex:1,fontFamily:"'Teko',sans-serif",fontSize:14,color:G.deepBlue}}>{p.local} — {p.visitante}</span>
                    <span style={{fontFamily:"'Teko',sans-serif",fontSize:15,fontWeight:700,color:G.deepBlue}}>{p.golesLocal}—{p.golesVisitante}</span>
                </div>;})}
            </div>}
        </div>;
    }

    var abierta = jornada.estado === 'Abierta';
    var udlpEsLocal = jornada.equipoLocal === 'UD Las Palmas';
    var live = jornada.liveData;
    var isLive = jornada.estado === 'En vivo' && live && live.isLive;
    var gL = isLive ? live.golesLocal : (jornada.estado==='Finalizada' ? jornada.resultadoLocal : null);
    var gV = isLive ? live.golesVisitante : (jornada.estado==='Finalizada' ? jornada.resultadoVisitante : null);

    var coste = jornada.esVip ? APUESTA_VIP : APUESTA_NORMAL;
    var bote = parseFloat(jornada.bote || 0) + participantes.length * coste;
    var ganadoresExactos = participantes.filter(function(p) {
        return gL !== null && gV !== null && parseInt(p.golesLocal)===parseInt(gL) && parseInt(p.golesVisitante)===parseInt(gV);
    });

    return (
        <div style={{paddingBottom:40}}>
            <h2 style={styles.title}>LA JORNADA</h2>

            {/* 🔧 SOLO ADMIN · diagnóstico del EN VIVO */}
            {window.__usuarioApp === 'Juanma' && (
                <div style={{background:'rgba(255,215,0,0.1)',border:'1px dashed rgba(255,215,0,0.5)',borderRadius:8,padding:'6px 10px',marginBottom:10}}>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'#b8860b',marginBottom:5}}>
                        🔧 SOLO ADMIN · Última sync: {window.__liveDiag ? window.__liveDiag.hora + ' · ' + (window.__liveDiag.ok ? '✅ fixture ' + window.__liveDiag.fixtureId + ' · ' + window.__liveDiag.estado + ' · ' + window.__liveDiag.marcador : '❌ sin partido encontrado') : 'aún ninguna (salta cada 15 min con jornada Abierta, cada 2 min En vivo — abre Mi Jornada para forzar el ciclo)'}
                    </p>
                    <button onClick={async function(){
                        try {
                            var r = await fetch('https://v3.football.api-sports.io/fixtures?team=' + API_TEAM_ID_UDLP + '&live=all', { headers: { 'x-apisports-key': API_FOOTBALL_KEY } });
                            var restan = r.headers.get('x-ratelimit-requests-remaining');
                            var d = await r.json();
                            var p = d.response && d.response[0];
                            alert(p ? '🔴 PARTIDO EN VIVO ENCONTRADO\n\n' + p.teams.home.name + ' ' + p.goals.home + '-' + p.goals.away + ' ' + p.teams.away.name + '\nMinuto: ' + (p.fixture.status.elapsed || '?') + '\'\nFixture: ' + p.fixture.id + '\n\n📊 Peticiones restantes: ' + (restan || '¿?') + '/100' : '⚠️ La API dice que la UDLP NO tiene partido en vivo AHORA MISMO.\n\n📊 Peticiones restantes: ' + (restan || '¿?') + '/100\nErrores: ' + JSON.stringify(d.errors || {}));
                        } catch(e) { alert('❌ SIN CONEXIÓN: ' + e.message); }
                    }} style={{width:'100%',border:'none',borderRadius:6,padding:'6px 8px',background:'#001F6B',color:'#FFD700',fontFamily:"'Teko',sans-serif",fontSize:11,letterSpacing:1,cursor:'pointer'}}>🔴 ¿HAY PARTIDO EN VIVO AHORA? (1 petición)</button>
                </div>
            )}

            <CuentaAtrasJornada jornada={jornada} />

            {/* 📣 CAPTACIÓN — plazas libres y equipos de Primera sin dueño */}
            <BannerPlazasLibres />

            {/* 🎬 GALA · Cierre de la Jornada 1 */}
            {mostrarGala && <PresentacionGalaJ1 userProfiles={userProfiles} onClose={function(){ setMostrarGala(false); }} />}
            <button onClick={function(){ setMostrarGala(true); }}
                style={{width:'100%',border:'1px solid rgba(255,215,0,0.45)',borderRadius:16,padding:'13px 16px',marginBottom:16,cursor:'pointer',
                    background:'linear-gradient(120deg,#0d1b3e,#001F6B 60%,#0d1b3e)',color:'#FFD700',
                    fontFamily:"'Teko',sans-serif",fontSize:15,letterSpacing:3,display:'flex',alignItems:'center',justifyContent:'center',gap:10,
                    boxShadow:'0 4px 16px rgba(0,31,107,0.3)'}}>
                🎬 LA GALA · CIERRE DE LA JORNADA 1 <span style={{fontSize:11,opacity:0.6}}>▶ VER</span>
            </button>

            {/* 📣 Cierre extendido de la J1 — visible hasta el 20/08/2026 22:00 (Canarias) */}
            {Date.now() < 1787259600000 && <CierreExtendidoJ1 userProfiles={userProfiles} currentUser={null} />}

            {/* Banner resultado */}
            <div style={{background:'#001F6B',borderRadius:20,padding:24,marginBottom:20,textAlign:'center'}}>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:11,letterSpacing:4,color:'rgba(255,255,255,0.4)',textTransform:'uppercase',marginBottom:4}}>
                    Jornada {jornada.numeroJornada} {jornada.esVip?'⭐ VIP':''} {jornada.derbi?'🔥':''}
                </p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(255,255,255,0.42)',marginBottom:16}}>
                    {(detalleFixtureActual && detalleFixtureActual.fixture && detalleFixtureActual.fixture.date)
                        ? new Date(detalleFixtureActual.fixture.date).toLocaleString('es-ES',{weekday:'long',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit',timeZone:'Atlantic/Canary'})
                        : formatearFechaJornada(getFechaPartidoISO(jornada) || jornada.fecha)}
                    {jornada.estadio ? ' · '+jornada.estadio : ''}
                </p>
                {/* Marcador con escudos */}
                <div style={{display:'flex',alignItems:'center',justifyContent:'center',gap:12}}>
                    <div style={{display:'flex',flexDirection:'column',alignItems:'center',gap:8,flex:1}}>
                        <img src={getLogoEquipo(jornada.equipoLocal, teamLogos)} alt={jornada.equipoLocal}
                                style={{width:52,height:52,objectFit:'contain',filter:'drop-shadow(0 2px 8px rgba(0,0,0,0.3))'}}
                                onError={function(e){e.target.src='https://placehold.co/60x60/001F6B/FFD700?text=UDLP';}} />
                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:13,color:'rgba(255,255,255,0.6)',letterSpacing:1,textTransform:'uppercase'}}>
                            {udlpEsLocal ? 'UD Las Palmas' : jornada.equipoLocal}
                        </span>
                    </div>
                    <div style={{textAlign:'center',flexShrink:0}}>
                        {gL !== null && gV !== null ? (
                            <p style={{fontFamily:"'Teko',sans-serif",fontSize:52,fontWeight:700,color:'#FFD700',letterSpacing:4,lineHeight:1}}>
                                {gL} — {gV}
                            </p>
                        ) : (
                            <p style={{fontFamily:"'Teko',sans-serif",fontSize:36,color:'rgba(255,255,255,0.2)',letterSpacing:4}}>vs</p>
                        )}
                        <div style={{marginTop:8}}>
                            {isLive && (
                                <>
                                    <span style={{fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:3,color:'#e63946',padding:'4px 12px',background:'rgba(230,57,70,0.2)',borderRadius:10,animation:'blink-live 1.5s infinite'}}>EN VIVO</span>
                                    {live && live.minuto && (
                                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:14,color:'rgba(255,255,255,0.5)',marginTop:6}}>{live.minuto}'</p>
                                    )}
                                </>
                            )}
                            {!isLive && <span style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(255,255,255,0.3)'}}>{jornada.estado}</span>}
                        </div>
                    </div>
                    <div style={{display:'flex',flexDirection:'column',alignItems:'center',gap:8,flex:1}}>
                        <img src={getLogoEquipo(jornada.equipoVisitante, teamLogos)} alt={jornada.equipoVisitante}
                            style={{width:52,height:52,objectFit:'contain',filter:'drop-shadow(0 2px 8px rgba(0,0,0,0.3))'}}
                            onError={function(e){e.target.src='https://placehold.co/60x60/001F6B/FFD700?text=' + encodeURIComponent((jornada.equipoVisitante||'?').substring(0,3));}} />
                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:13,color:'rgba(255,255,255,0.6)',letterSpacing:1,textTransform:'uppercase'}}>
                            {udlpEsLocal ? jornada.equipoVisitante : 'UD Las Palmas'}
                        </span>
                    </div>
                </div>
                {/* Estadísticas del partido en vivo — métricas de estadio */}
                {isLive && live && live.estadisticas && (
                    <div style={{marginTop:12,display:'grid',gridTemplateColumns:'1fr 1fr',gap:8}}>
                        {[
                            {label:'Posesión', local: live.estadisticas.posesionLocal, visitante: live.estadisticas.posesionVisitante, sufijo:'%'},
                            {label:'Tiros', local: live.estadisticas.tirosLocal, visitante: live.estadisticas.tirosVisitante},
                            {label:'A puerta', local: live.estadisticas.tirosApuertaLocal, visitante: live.estadisticas.tirosApuertaVisitante},
                            {label:'Corners', local: live.estadisticas.cornersLocal, visitante: live.estadisticas.cornersVisitante},
                        ].map(function(stat) {
                            if (stat.local === undefined && stat.visitante === undefined) return null;
                            return (
                                <div key={stat.label} style={{background:'rgba(255,255,255,0.06)',borderRadius:10,padding:'6px 10px',textAlign:'center'}}>
                                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:9,color:'rgba(255,255,255,0.35)',letterSpacing:1,textTransform:'uppercase',marginBottom:2}}>{stat.label}</p>
                                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:16,color:'#fff'}}>
                                        {stat.local || 0}{stat.sufijo||''} — {stat.visitante || 0}{stat.sufijo||''}
                                    </p>
                                </div>
                            );
                        })}
                    </div>
                )}

                {/* Bote */}
                <div style={{marginTop:16,display:'flex',justifyContent:'center',gap:24}}>
                    <div style={{textAlign:'center'}}>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:24,fontWeight:700,color:'#FFD700'}}>{bote.toFixed(2)}€</p>
                        <p style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(255,255,255,0.35)',letterSpacing:2,textTransform:'uppercase'}}>Bote</p>
                    </div>
                    <div style={{textAlign:'center'}}>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:24,fontWeight:700,color:'rgba(255,255,255,0.6)'}}>{participantes.length}</p>
                        <p style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(255,255,255,0.35)',letterSpacing:2,textTransform:'uppercase'}}>Apuestas</p>
                    </div>
                </div>
            </div>

            {!abierta && jornada && jornada.estado === 'Finalizada' && !jornada.cierreDefinitivo && (
                <div style={{background:'linear-gradient(135deg,#fff9e6,#fff)',border:'1px solid rgba(212,175,55,.4)',borderRadius:16,padding:18,marginBottom:18}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:17,letterSpacing:2,color:'#8a6a00',textTransform:'uppercase',fontWeight:700,marginBottom:6}}>⏳ JORNADA EN CIERRE</p>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(0,31,107,.7)',lineHeight:1.6,marginBottom:6}}>El resultado de la Porra y el reparto económico ya están resueltos. Los puntos mostrados son <strong>provisionales</strong> hasta que termine la jornada de Primera.</p>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,.5)',lineHeight:1.5}}>No se muestran equipos ni multiplicadores de El Otro para mantener la competición en secreto. El cierre definitivo aplicará todo de una vez.</p>
                </div>
            )}
            {jornada && jornada.estado === 'Finalizada' && jornada.cierreDefinitivo && (
                <div style={{background:'rgba(16,185,129,.08)',border:'1px solid rgba(16,185,129,.25)',borderRadius:16,padding:14,marginBottom:18}}><p style={{fontFamily:"'Teko',sans-serif",fontSize:15,letterSpacing:2,color:'#0f8a61',textTransform:'uppercase',fontWeight:700,margin:0}}>✅ JORNADA CERRADA DEFINITIVAMENTE</p></div>
            )}

            {/* Pronósticos */}
            <div style={{background:'#fff',borderRadius:16,border:'1px solid rgba(0,31,107,0.08)',overflow:'hidden'}}>
                <div style={{background:'rgba(0,31,107,0.04)',padding:'12px 16px',borderBottom:'1px solid rgba(0,31,107,0.06)'}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:3,color:G.deepBlue,opacity:.5,textTransform:'uppercase'}}>
                        {abierta ? 'APUESTAS SECRETAS HASTA EL CIERRE' : 'PRONÓSTICOS'}
                    </p>
                </div>

                {abierta ? (
                    <div style={{padding:24,textAlign:'center'}}>
                        <p style={{fontSize:36,marginBottom:8}}>🔒</p>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:18,letterSpacing:2,color:G.deepBlue,textTransform:'uppercase',marginBottom:4}}>
                            Apuestas en curso
                        </p>
                        <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:G.deepBlue,opacity:.5,marginBottom:16}}>
                            Los pronósticos se revelarán cuando cierren las apuestas.
                        </p>

                        {/* Estadísticas agregadas — solo visibles con 5+ apuestas */}
                        {participantes.length >= 5 && (function() {
                            var conteoMarcadores = {};
                            // Los votos se guardan como 'Gana' / 'Empata' / 'Pierde'
                            // (siempre respecto a la UDLP) — contar '1'/'X'/'2'
                            // dejaba la gráfica a 0.
                            var conteo1X2 = { Gana: 0, Empata: 0, Pierde: 0 };
                            participantes.forEach(function(p) {
                                var clave = p.golesLocal + '-' + p.golesVisitante;
                                conteoMarcadores[clave] = (conteoMarcadores[clave] || 0) + 1;
                                var voto = p.resultado1x2 === 'Empate' ? 'Empata' : p.resultado1x2;
                                if (voto && conteo1X2[voto] !== undefined) conteo1X2[voto]++;
                            });
                            var marcadoresOrdenados = Object.keys(conteoMarcadores)
                                .map(function(k) { return { marcador: k, n: conteoMarcadores[k] }; })
                                .sort(function(a,b) { return b.n - a.n; })
                                .slice(0, 5);
                            var maxN = marcadoresOrdenados.length > 0 ? marcadoresOrdenados[0].n : 1;
                            var total1X2 = conteo1X2.Gana + conteo1X2.Empata + conteo1X2.Pierde;
                            var pct = function(v) { return total1X2 > 0 ? Math.round(v / total1X2 * 100) : 0; };

                            return (
                                <div style={{marginBottom:20}}>
                                    <div style={{display:'flex',gap:8,justifyContent:'center',marginBottom:16}}>
                                        {[
                                            { label: 'GANA LA UD', key: 'Gana', color: '#10b981' },
                                            { label: 'EMPATA', key: 'Empata', color: '#FFD700' },
                                            { label: 'PIERDE', key: 'Pierde', color: '#e63946' },
                                        ].map(function(item) {
                                            return (
                                                <div key={item.key} style={{flex:1,textAlign:'center'}}>
                                                    <div style={{height:60,display:'flex',alignItems:'flex-end',justifyContent:'center',marginBottom:4}}>
                                                        <div style={{width:28,borderRadius:'6px 6px 0 0',background:item.color,opacity:0.8,
                                                            height: Math.max(8, pct(conteo1X2[item.key]) * 0.55) + 'px',
                                                            transition:'height 0.5s ease'}} />
                                                    </div>
                                                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:20,fontWeight:700,color:item.color}}>{pct(conteo1X2[item.key])}%</p>
                                                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:9,color:'rgba(0,31,107,0.4)',letterSpacing:1}}>{item.label}</p>
                                                </div>
                                            );
                                        })}
                                    </div>
                                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(0,31,107,0.35)',letterSpacing:1,textTransform:'uppercase',marginBottom:8}}>Marcadores más repetidos</p>
                                    <div style={{display:'flex',flexDirection:'column',gap:6,maxWidth:240,margin:'0 auto'}}>
                                        {marcadoresOrdenados.map(function(m) {
                                            return (
                                                <div key={m.marcador} style={{display:'flex',alignItems:'center',gap:10}}>
                                                    <span style={{fontFamily:"'Teko',sans-serif",fontSize:16,fontWeight:700,color:G.deepBlue,width:40,textAlign:'center'}}>{m.marcador}</span>
                                                    <div style={{flex:1,height:14,background:'rgba(0,31,107,0.06)',borderRadius:7,overflow:'hidden'}}>
                                                        <div style={{height:'100%',borderRadius:7,background:'linear-gradient(90deg,#001F6B,#FFD700)',
                                                            width: Math.round(m.n / maxN * 100) + '%', transition:'width 0.5s ease'}} />
                                                    </div>
                                                    <span style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,0.5)',width:20}}>{m.n}</span>
                                                </div>
                                            );
                                        })}
                                    </div>
                                </div>
                            );
                        })()}

                        {participantes.length > 0 && participantes.length < 5 && (
                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,0.3)',marginBottom:16}}>
                                Las estadísticas se muestran a partir de 5 apuestas ({participantes.length}/{5})
                            </p>
                        )}

                        {/* Todo el grupo, no solo quien ya ha apostado — atenuados
                            quienes todavía no lo han hecho, para que se vean entre
                            ellos de un vistazo. La burbuja de El Otro Equipo aquí
                            es la de ESTA jornada en concreto (activado o no), no
                            si tienen equipo elegido para toda la temporada. */}
                        <div style={{display:'flex',flexWrap:'wrap',gap:14,justifyContent:'center',marginTop:20}}>
                            {JUGADORES_ACTIVOS_LJ.map(function(nombre) {
                                var apuesta = participantes.find(function(p) { return p.id === nombre; });
                                var haApostado = !!apuesta;
                                var perf = userProfiles[nombre] || {};
                                var otro = elOtroTodos[nombre];
                                var tieneEquipoOtro = !!(otro && otro.equipo);
                                var activadoEstaJornada = haApostado && apuesta.elOtroActivado;
                                return (
                                    <div key={nombre} style={{opacity: haApostado ? 1 : 0.35, display:'flex', flexDirection:'column', alignItems:'center', gap:4, transition:'opacity .2s'}}>
                                        <div style={{position:'relative'}}>
                                            <div style={{border: '2px solid rgba(0,31,107,0.15)', borderRadius:'50%', boxShadow: '0 2px 8px rgba(0,31,107,0.12)'}}>
                                                <IconoPerfilClickable nombre={nombre} perfil={perf} size={44} />
                                            </div>
                                            {tieneEquipoOtro && (
                                                <div style={{
                                                    position:'absolute', top:-6, right:-6, width:20, height:20, borderRadius:'50%',
                                                    background: activadoEstaJornada ? '#001F6B' : 'rgba(0,31,107,0.15)',
                                                    border: activadoEstaJornada ? '1.5px solid #FFD700' : '1.5px solid rgba(0,31,107,0.2)',
                                                    display:'flex', alignItems:'center', justifyContent:'center', fontSize:9,
                                                }} title={activadoEstaJornada ? 'Ha activado El Otro Equipo esta jornada' : 'No ha activado El Otro Equipo esta jornada'}>
                                                    🛡️❓
                                                </div>
                                            )}
                                        </div>
                                        <span style={{fontFamily:"'Inter',sans-serif",fontSize:9,color:G.deepBlue,opacity:.6,maxWidth:50,textAlign:'center',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>
                                            {nombreVisible(nombre, perf)}
                                        </span>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                ) : (
                    <div style={{padding:'8px 0'}}>
                        {JUGADORES_ACTIVOS_LJ
                            .map(function(nombre) { return participantes.find(function(p) { return p.id === nombre; }) || { id: nombre, sinApuesta: true }; })
                            .sort(function(a,b) { return (b.puntosObtenidos||0)-(a.puntosObtenidos||0); })
                            .map(function(p) {
                            var ganador = ganadoresExactos.find(function(g) { return g.id === p.id; });
                            var perf = userProfiles[p.id] || {};
                            var otro = elOtroTodos[p.id];
                            var elOtroActivado = p.elOtroActivado;
                            return (
                                <div key={p.id} style={{display:'flex',alignItems:'center',gap:12,padding:'14px 16px',
                                    borderBottom:'1px solid rgba(0,31,107,0.05)', opacity: p.sinApuesta ? 0.4 : 1,
                                    background: ganador ? 'rgba(255,215,0,0.06)' : 'transparent'}}>
                                    {/* Avatar con burbuja El Otro Equipo */}
                                    <PlayerAvatar name={p.id} perfil={perf} elOtroData={otro} size={40} showElOtro={true} teamLogos={teamLogos} />
                                    <div style={{flex:1}}>
                                        {p.sinApuesta ? (
                                            <span style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(0,31,107,0.4)',fontStyle:'italic'}}>
                                                No apostó esta jornada
                                            </span>
                                        ) : (
                                        <div style={{display:'flex',alignItems:'center',gap:8,flexWrap:'wrap'}}>
                                            <span style={{
                                                fontFamily:"'Teko',sans-serif",fontSize:18,fontWeight:700,
                                                color: ganador ? G.golden : G.deepBlue,
                                                background: ganador ? 'rgba(255,215,0,0.12)' : 'rgba(0,31,107,0.06)',
                                                padding:'3px 10px',borderRadius:8,letterSpacing:1}}>
                                                {p.golesLocal}-{p.golesVisitante}
                                            </span>
                                            <span style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,0.5)'}}>
                                                {p.resultado1x2}
                                            </span>
                                            <span style={{fontFamily:"'Inter',sans-serif",fontSize:10,
                                                background: elOtroActivado ? 'rgba(0,31,107,0.08)' : 'rgba(0,31,107,0.03)',
                                                color: elOtroActivado ? G.deepBlue : 'rgba(0,31,107,0.35)',
                                                padding:'2px 8px',borderRadius:10}}>
                                                {elOtroActivado && otro ? ('El Otro ' + (otro.revelado ? '· ' + otro.equipo : '🛡️')) : 'El Otro sin activar'}
                                            </span>
                                            {ganador && <span style={{fontSize:14}}>🏆</span>}
                                        </div>
                                        )}
                                    </div>
                                    {/* Puntos: en vivo los PROVISIONALES que va
                                        consiguiendo según el marcador actual;
                                        finalizada, los definitivos. Nunca un 0 fijo. */}
                                    {!p.sinApuesta && jornada.estado === 'Finalizada' && (function(){
                                        var ptsMostrar = puntosMostrarPronostico(p, jornada, null);
                                        return (
                                            <span style={{fontFamily:"'Teko',sans-serif",fontSize:22,fontWeight:700,color: ganador?G.golden:(ptsMostrar>0?G.deepBlue:'rgba(0,31,107,0.25)')}}>
                                                {ptsMostrar > 0 ? '+' + ptsMostrar : ptsMostrar}
                                            </span>
                                        );
                                    })()}
                                    {!p.sinApuesta && isLive && (function(){
                                        var ptsVivo = calculateProvisionalPoints(p, live, jornada);
                                        return (
                                            <span style={{fontFamily:"'Teko',sans-serif",fontSize:22,fontWeight:700,textAlign:'right',
                                                color: ptsVivo > 0 ? '#10b981' : 'rgba(0,31,107,0.2)'}}>
                                                {ptsVivo > 0 ? '+' + ptsVivo : '—'}
                                            </span>
                                        );
                                    })()}
                                </div>
                            );
                        })}
                        {participantes.length === 0 && (
                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:13,color:G.deepBlue,opacity:.4,padding:24,textAlign:'center'}}>
                                Nadie apostó en esta jornada.
                            </p>
                        )}
                    </div>
                )}
            </div>

            {/* Clasificación EN VIVO de la porra — quién va ganando durante
                el partido, con indicadores de quién acierta marcador/1X2 */}
            {isLive && live && participantes.length > 0 && (function() {
                var marcadorLive = gL + '-' + gV;
                var resultado1x2Live = parseInt(gL) > parseInt(gV) ? '1' : (parseInt(gL) < parseInt(gV) ? '2' : 'X');
                var rankingVivo = participantes.filter(function(p){return !p.sinApuesta;}).map(function(p) {
                    var pts = calculateProvisionalPoints(p, live, jornada);
                    var marcadorApostado = p.golesLocal + '-' + p.golesVisitante;
                    var aciertaMarcador = marcadorApostado === marcadorLive;
                    var acierta1x2 = p.resultado1x2 === resultado1x2Live;
                    return { id: p.id, puntos: pts, marcador: marcadorApostado, aciertaMarcador: aciertaMarcador, acierta1x2: acierta1x2 };
                }).sort(function(a,b) { return b.puntos - a.puntos; });
                var acertaronExacto = rankingVivo.filter(function(r){ return r.aciertaMarcador; }).length;
                return (
                    <div style={{marginTop:16}}>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:3,color:'#e63946',opacity:.8,textTransform:'uppercase',marginBottom:10,display:'flex',alignItems:'center',gap:8}}>
                            <span style={{animation:'blink-live 1.5s infinite'}}>🔴</span> Quién va ganando
                        </p>
                        {acertaronExacto > 0 && (
                            <div style={{background:'rgba(255,215,0,0.1)',border:'1px solid rgba(212,175,55,0.3)',borderRadius:10,padding:'8px 14px',marginBottom:10,textAlign:'center'}}>
                                <p style={{fontFamily:"'Teko',sans-serif",fontSize:14,color:G.golden}}>
                                    🎯 {acertaronExacto === 1 ? '¡1 jugador clava el marcador!' : acertaronExacto + ' jugadores clavan el marcador!'}
                                    {acertaronExacto === 1 ? ' → se lleva el bote' : ' → bote repartido'}
                                </p>
                            </div>
                        )}
                        <div style={{background:'rgba(230,57,70,0.04)',border:'1px solid rgba(230,57,70,0.15)',borderRadius:14,overflow:'hidden'}}>
                            {rankingVivo.map(function(r, idx) {
                                var perf = userProfiles[r.id] || {};
                                return (
                                    <div key={r.id} style={{display:'flex',alignItems:'center',gap:8,padding:'8px 12px',
                                        borderBottom: idx < rankingVivo.length-1 ? '1px solid rgba(0,31,107,0.05)' : 'none',
                                        background: r.aciertaMarcador ? 'rgba(255,215,0,0.08)' : 'transparent'}}>
                                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:14,color: idx === 0 ? G.golden : 'rgba(0,31,107,0.3)',width:18,textAlign:'center',fontWeight:700}}>{idx+1}</span>
                                        <IconoPerfil perfil={perf} size={26} />
                                        <span style={{flex:1,fontFamily:"'Inter',sans-serif",fontSize:12,color:G.deepBlue,fontWeight: idx === 0 ? 700 : 400}}>{nombreVisible(r.id, perf)}</span>
                                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:13,color:'rgba(0,31,107,0.4)',width:35,textAlign:'center'}}>{r.marcador}</span>
                                        {r.aciertaMarcador && <span style={{fontSize:11}} title="Acierta marcador">🎯</span>}
                                        {!r.aciertaMarcador && r.acierta1x2 && <span style={{fontSize:11}} title="Acierta 1X2">✓</span>}
                                        {!r.aciertaMarcador && !r.acierta1x2 && <span style={{fontSize:11,opacity:0.3}} title="Falla">✗</span>}
                                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:18,fontWeight:700,color: idx === 0 ? G.golden : r.puntos > 0 ? G.deepBlue : 'rgba(0,31,107,0.25)',minWidth:24,textAlign:'right'}}>{r.puntos > 0 ? '+' + r.puntos : '—'}</span>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                );
            })()}

            {/* Estrellas EN VIVO — comparativa provisional durante el partido, NO definitiva */}
            {isLive && jornada.liveEstrellas && jornada.liveEstrellas.puntosPorNombre && seleccionesEstrellasJornada.length > 0 && (function() {
                var puntosLive = jornada.liveEstrellas.puntosPorNombre;
                var ranking = seleccionesEstrellasJornada.map(function(sel) {
                    var total = (sel.jugadores || []).reduce(function(acc, j) { return acc + (puntosLive[j.nombre] || 0); }, 0);
                    return { id: sel.id, total: total };
                }).sort(function(a,b) { return b.total - a.total; });
                return (
                    <div style={{background:'#fff',borderRadius:16,border:'1px solid rgba(230,57,70,0.15)',overflow:'hidden',marginTop:16}}>
                        <div style={{background:'rgba(230,57,70,0.06)',padding:'12px 16px',borderBottom:'1px solid rgba(230,57,70,0.08)',display:'flex',justifyContent:'space-between',alignItems:'center'}}>
                            <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:3,color:G.danger,opacity:.8,textTransform:'uppercase'}}>
                                🔴 Estrellas EN VIVO
                            </p>
                            <span style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:G.danger,opacity:.5}}>Provisional — no cuenta todavía</span>
                        </div>
                        <div style={{padding:'6px 0'}}>
                            {ranking.slice(0,5).map(function(p, i) {
                                var perf = userProfiles[p.id] || {};
                                return (
                                    <div key={p.id} style={{display:'flex',alignItems:'center',gap:12,padding:'10px 16px',
                                        borderBottom: i < 4 ? '1px solid rgba(0,31,107,0.05)' : 'none'}}>
                                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:16,color: i===0 ? G.danger : 'rgba(0,31,107,0.3)',minWidth:18,textAlign:'center'}}>
                                            {i+1}
                                        </span>
                                        <PlayerAvatar name={p.id} perfil={perf} size={32} />
                                        <span style={{flex:1,fontFamily:"'Inter',sans-serif",fontSize:13,color:G.deepBlue,fontWeight: i===0?600:400}}>
                                            {p.id}
                                        </span>
                                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:18,fontWeight:700,color: i===0 ? G.danger : G.deepBlue}}>
                                            {p.total}⭐
                                        </span>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                );
            })()}

            {/* Clasificación de Estrellas — quién va ganando */}
            {clasifEstrellas.length > 0 && (
                <div style={{background:'#fff',borderRadius:16,border:'1px solid rgba(0,31,107,0.08)',overflow:'hidden',marginTop:16}}>
                    <div style={{background:'rgba(255,215,0,0.06)',padding:'12px 16px',borderBottom:'1px solid rgba(0,31,107,0.06)',display:'flex',justifyContent:'space-between',alignItems:'center'}}>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:3,color:G.deepBlue,opacity:.6,textTransform:'uppercase'}}>
                            ⭐ Estrellas — Liga Paralela
                        </p>
                        <span style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:G.deepBlue,opacity:.35}}>Acumulado temporada</span>
                    </div>
                    <div style={{padding:'6px 0'}}>
                        {clasifEstrellas.slice(0,5).map(function(p, i) {
                            var perf = userProfiles[p.id] || {};
                            return (
                                <div key={p.id} style={{display:'flex',alignItems:'center',gap:12,padding:'10px 16px',
                                    borderBottom: i < 4 ? '1px solid rgba(0,31,107,0.05)' : 'none',
                                    background: i===0 ? 'rgba(255,215,0,0.07)' : 'transparent'}}>
                                    <span style={{fontFamily:"'Teko',sans-serif",fontSize:16,color: i===0 ? G.golden : 'rgba(0,31,107,0.3)',minWidth:18,textAlign:'center'}}>
                                        {i+1}
                                    </span>
                                    <PlayerAvatar name={p.id} perfil={perf} size={32} />
                                    <span style={{flex:1,fontFamily:"'Inter',sans-serif",fontSize:13,color:G.deepBlue,fontWeight: i===0?600:400}}>
                                        {p.id}
                                    </span>
                                    {i===0 && <span style={{fontSize:13}}>🏆</span>}
                                    <span style={{fontFamily:"'Teko',sans-serif",fontSize:18,fontWeight:700,color: i===0 ? G.golden : G.deepBlue}}>
                                        {p.puntosEstrellas || 0}⭐
                                    </span>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Resumen de jornada finalizada — puntos, ganadores, bote */}
            {jornada.estado === 'Finalizada' && participantes.length > 0 && (function() {
                var resumenOrdenado = participantes.filter(function(p){return !p.sinApuesta;})
                    .map(function(p){ return { ...p, ptsVista: puntosMostrarPronostico(p, jornada, null) }; })
                    .sort(function(a,b) { return (b.ptsVista||0) - (a.ptsVista||0); });
                var maxPtos = resumenOrdenado.length > 0 ? (resumenOrdenado[0].ptsVista || 0) : 0;
                // 1º el reparto OFICIAL guardado al finalizar (fuente de verdad).
                // 2º si no existe, se calcula contando SOLO a los contabilizados
                //    (los que pagaron), no a todo el que apostó.
                var ganadoresOficiales = Array.isArray(jornada.ganadores) ? jornada.ganadores : null;
                var acertaronExacto = ganadoresOficiales
                    ? participantes.filter(function(p) { return ganadoresOficiales.indexOf(p.id) !== -1; })
                    : participantes.filter(function(p) {
                        return !p.sinApuesta && !p.noContabilizado &&
                            parseInt(p.golesLocal) === parseInt(jornada.resultadoLocal) &&
                            parseInt(p.golesVisitante) === parseInt(jornada.resultadoVisitante);
                    });
                var contabilizados = participantes.filter(function(p){ return !p.sinApuesta && !p.noContabilizado; });
                var boteJornada = jornada.boteTotal !== undefined
                    ? Number(jornada.boteTotal)
                    : parseFloat(jornada.bote || 0) + contabilizados.length * (jornada.esVip ? APUESTA_VIP : APUESTA_NORMAL);
                var premioPorGanador = jornada.premioPorGanador !== undefined
                    ? Number(jornada.premioPorGanador).toFixed(2)
                    : (acertaronExacto.length > 0 ? (boteJornada / acertaronExacto.length).toFixed(2) : '0.00');

                return (
                    <div style={{marginTop:20,background:'linear-gradient(135deg,#001F6B,#003a9e)',borderRadius:16,padding:20}}>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:16,letterSpacing:3,color:'#FFD700',textTransform:'uppercase',marginBottom:14}}>
                            📊 Resumen Jornada {jornada.numeroJornada}
                        </p>
                        <div style={{display:'flex',gap:16,justifyContent:'center',marginBottom:16}}>
                            <div style={{textAlign:'center'}}>
                                <p style={{fontFamily:"'Teko',sans-serif",fontSize:22,fontWeight:700,color:'#FFD700'}}>{Number(boteJornada).toFixed(2)}€</p>
                                <p style={{fontFamily:"'Inter',sans-serif",fontSize:9,color:'rgba(255,255,255,0.4)',letterSpacing:1}}>RECAUDADO{jornada.jugadoresContabilizados !== undefined ? ' · ' + jornada.jugadoresContabilizados + ' PAGADAS' : ''}</p>
                            </div>
                            {acertaronExacto.length > 0 && (
                                <div style={{textAlign:'center'}}>
                                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:22,fontWeight:700,color:'#FFD700'}}>{premioPorGanador}€</p>
                                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:9,color:'rgba(255,255,255,0.4)',letterSpacing:1}}>POR GANADOR</p>
                                </div>
                            )}
                        </div>
                        {acertaronExacto.length > 0 && (
                            <div style={{background:'rgba(255,215,0,0.15)',borderRadius:10,padding:10,marginBottom:14,textAlign:'center'}}>
                                <p style={{fontFamily:"'Teko',sans-serif",fontSize:14,color:'#FFD700'}}>
                                    🎯 {acertaronExacto.length === 1 ? '¡' + nombreVisible(acertaronExacto[0].id, userProfiles[acertaronExacto[0].id]) + ' clava el marcador!' : acertaronExacto.length + ' jugadores clavan el marcador'}
                                </p>
                            </div>
                        )}
                        <div style={{display:'flex',flexDirection:'column',gap:4}}>
                            {resumenOrdenado.map(function(p, idx) {
                                var perf = userProfiles[p.id] || {};
                                var exacto = parseInt(p.golesLocal) === parseInt(jornada.resultadoLocal) && parseInt(p.golesVisitante) === parseInt(jornada.resultadoVisitante);
                                return (
                                    <div key={p.id} style={{display:'flex',alignItems:'center',gap:8,padding:'6px 10px',
                                        background: exacto ? 'rgba(255,215,0,0.1)' : 'rgba(255,255,255,0.04)',borderRadius:8}}>
                                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:13,color: idx === 0 ? '#FFD700' : 'rgba(255,255,255,0.3)',width:18,fontWeight:700}}>{idx+1}</span>
                                        <IconoPerfil perfil={perf} size={24} />
                                        <span style={{flex:1,fontFamily:"'Inter',sans-serif",fontSize:11,color:'#fff'}}>{nombreVisible(p.id, perf)}</span>
                                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:12,color:'rgba(255,255,255,0.4)',width:35,textAlign:'center'}}>{p.golesLocal}-{p.golesVisitante}</span>
                                        {exacto && <span style={{fontSize:10}}>🎯</span>}
                                        {p.elOtroActivado && <span style={{fontSize:10}}>🛡️</span>}
                                        {(p.puntosEstrellas||0) > 0 && <span style={{fontFamily:"'Inter',sans-serif",fontSize:9,color:'rgba(255,215,0,0.7)',background:'rgba(255,215,0,0.15)',padding:'1px 5px',borderRadius:6}}>{p.puntosEstrellas}⭐</span>}
                                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:16,fontWeight:700,color: (p.ptsVista||0) > 0 ? '#FFD700' : 'rgba(255,255,255,0.25)',minWidth:24,textAlign:'right'}}>{(p.ptsVista||0) > 0 ? '+' + p.ptsVista : 0}</span>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                );
            })()}

            {/* Estrellas de la jornada finalizada — muestra el ranking de
                estrellas con desglose, visible después del partido */}
            {jornada && jornada.estado === 'Finalizada' && seleccionesEstrellasJornada.length > 0 && (
                <div style={{marginTop:20,background:'linear-gradient(135deg,#001F6B,#003a9e)',borderRadius:16,padding:20}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:3,color:'#FFD700',textTransform:'uppercase',marginBottom:14}}>
                        ⭐ 5 Estrellas · Jornada {jornada.numeroJornada}
                    </p>
                    <div style={{display:'flex',flexDirection:'column',gap:6}}>
                        {seleccionesEstrellasJornada.sort(function(a,b) { return (b.puntosEstrellas||0)-(a.puntosEstrellas||0); }).map(function(sel, idx) {
                            var perf = userProfiles[sel.id] || {};
                            var ptsE = sel.puntosEstrellas || 0;
                            var jugadores = sel.jugadores || [];
                            return (
                                <div key={sel.id} style={{background:'rgba(255,255,255,0.04)',borderRadius:10,padding:'8px 12px'}}>
                                    <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:4}}>
                                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:13,color: idx < 3 ? '#FFD700' : 'rgba(255,255,255,0.3)',width:18,fontWeight:700}}>{idx+1}</span>
                                        <IconoPerfil perfil={perf} size={22} />
                                        <span style={{flex:1,fontFamily:"'Inter',sans-serif",fontSize:11,color:'#fff'}}>{nombreVisible(sel.id, perf)}</span>
                                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:16,fontWeight:700,color:'#FFD700'}}>{ptsE}⭐</span>
                                    </div>
                                    <div style={{display:'flex',gap:4,flexWrap:'wrap',marginLeft:26}}>
                                        {jugadores.map(function(j) {
                                            var ptJ = (sel.desglosePorJugador && sel.desglosePorJugador[j.nombre]) || 0;
                                            return (
                                                <span key={j.nombre} style={{fontFamily:"'Inter',sans-serif",fontSize:9,
                                                    background: ptJ > 0 ? 'rgba(16,185,129,0.15)' : 'rgba(255,255,255,0.05)',
                                                    color: ptJ > 0 ? '#10b981' : 'rgba(255,255,255,0.4)',
                                                    padding:'2px 6px',borderRadius:6}}>{j.nombre} {ptJ > 0 ? '+'+ptJ : '0'}</span>
                                            );
                                        })}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Partidos de Primera relevantes — los que afectan a jugadores
                del grupo que tienen equipo elegido en El Otro, para que se
                vea de un vistazo qué partidos importan esta jornada. */}
            {partidosPrimera.length > 0 && (
                <div style={{marginTop:24}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:3,color:G.deepBlue,opacity:.4,textTransform:'uppercase',marginBottom:10}}>
                        Partidos de Primera · El Otro Equipo
                    </p>
                    <div style={{background:'#fff',border:'1px solid rgba(0,31,107,0.1)',borderRadius:16,overflow:'hidden'}}>
                        {partidosPrimera.map(function(p) {
                            var fechaObj = new Date(p.fecha);
                            var fechaTexto = fechaObj.toLocaleString('es-ES', {weekday:'short', day:'numeric', month:'short', hour:'2-digit', minute:'2-digit', timeZone:'Atlantic/Canary'});
                            var finalizado = p.estadoCorto === 'FT' || p.estadoCorto === 'AET' || p.estadoCorto === 'PEN';
                            var enVivo = p.estadoCorto === '1H' || p.estadoCorto === '2H' || p.estadoCorto === 'HT';
                            return (
                                <div key={p.fixtureId} style={{display:'flex',alignItems:'center',gap:10,padding:'10px 14px',borderBottom:'1px solid rgba(0,31,107,0.05)',flexWrap:'wrap'}}>
                                    <span style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(0,31,107,0.4)',minWidth:100}}>{fechaTexto}</span>
                                    <span style={{fontFamily:"'Teko',sans-serif",fontSize:14,color:G.deepBlue,flex:1}}>{p.local} vs {p.visitante}</span>
                                    {finalizado && (
                                        <span style={{fontFamily:"'Teko',sans-serif",fontSize:14,fontWeight:700,color:'#10b981'}}>{p.golesLocal}-{p.golesVisitante}</span>
                                    )}
                                    {enVivo && (
                                        <span style={{fontFamily:"'Inter',sans-serif",fontSize:10,background:'rgba(230,57,70,0.1)',color:'#e63946',padding:'2px 8px',borderRadius:10}}>EN VIVO {p.golesLocal}-{p.golesVisitante}</span>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Con la jornada ya Finalizada, además del resumen completo se
                enseña abajo cuál es el siguiente partido de la UDLP. */}
            {jornada.estado === 'Finalizada' && proximaUDLP && (function() {
                var fpn = new Date(proximaUDLP.fecha);
                return (
                    <div style={{marginTop:24,background:'#001F6B',borderRadius:18,padding:20,textAlign:'center'}}>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:11,letterSpacing:4,color:'rgba(255,255,255,.4)',textTransform:'uppercase',marginBottom:6}}>🔜 PRÓXIMA JORNADA</p>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:22,fontWeight:700,color:'#fff',marginBottom:5}}>{proximaUDLP.local} — {proximaUDLP.visitante}</p>
                        <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'#FFD700',margin:0}}>{fpn.toLocaleString('es-ES',{weekday:'long',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit',timeZone:'Atlantic/Canary'})}</p>
                        {proximaUDLP.estadio && <p style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(255,255,255,.4)',marginTop:4}}>🏟️ {proximaUDLP.estadio}</p>}
                    </div>
                );
            })()}
        </div>
    );
};


const ElCaminoScreen = ({ user, userProfiles, onlineUsers }) => {
    const [config, setConfig] = useState(null); 
    const [apuesta, setApuesta] = useState(''); 
    const [hasBet, setHasBet] = useState(false);
    const [allBets, setAllBets] = useState([]);
    const [timeLeft, setTimeLeft] = useState('');
    const [stats, setStats] = useState({});

    useEffect(() => { 
        const unsubConfig = onSnapshot(doc(db, "configuracion", "playoff"), (d) => { if(d.exists()) setConfig(d.data()); }); 
        getDoc(doc(db, "apuestasExtra", user)).then(d => { if(d.exists()){ setApuesta(d.data().equipo); setHasBet(true); }}); 
        const unsubBets = onSnapshot(collection(db, "apuestasExtra"), (snap) => { 
            let fetchedBets = snap.docs.map(d => ({id: d.id, ...d.data()}));
            
            // --- INYECCIÓN AUTOMÁTICA DEL MÁLAGA (Para Carlos, Carmelo, José) ---
            const faltan = ['Carlos', 'Carmelo', 'José'];
            faltan.forEach(nombre => {
                if (!fetchedBets.find(b => b.id === nombre)) {
                    fetchedBets.push({ id: nombre, equipo: 'Málaga CF', inyectado: true });
                }
            });

            setAllBets(fetchedBets);

            // --- CÁLCULO DE GRÁFICA DE PORCENTAJES ---
            const conteo = {};
            fetchedBets.forEach(b => { conteo[b.equipo] = (conteo[b.equipo] || 0) + 1; });
            setStats(conteo);
        });
        return () => { unsubConfig(); unsubBets(); };
    }, [user]);

    useEffect(() => {
        if (!config?.fechaCierreApuestaExtra?.seconds) return;
        const timer = setInterval(() => {
            const target = new Date(config.fechaCierreApuestaExtra.seconds * 1000);
            const now = new Date();
            const diff = target - now;
            if (diff <= 0) { setTimeLeft('CERRADO'); clearInterval(timer); } 
            else {
                const d = Math.floor(diff / (1000 * 60 * 60 * 24));
                const h = Math.floor((diff / (1000 * 60 * 60)) % 24);
                const m = Math.floor((diff / 1000 / 60) % 60);
                const s = Math.floor((diff / 1000) % 60);
                setTimeLeft(`${d}d ${h}h ${m}m ${s}s`);
            }
        }, 1000);
        return () => clearInterval(timer);
    }, [config]);

    const handleBet = async (eq) => { 
        if(hasBet || config?.bloqueado) return; 
        if(window.confirm(`¿Apostar por ${eq}? Sumarás +5 puntos si asciende.`)) { 
            await setDoc(doc(db, "apuestasExtra", user), { equipo: eq }); setApuesta(eq); setHasBet(true); 
        }
    };

    const isSecreto = config?.fechaCierreApuestaExtra && new Date() < new Date(config.fechaCierreApuestaExtra.seconds * 1000);
    const totalVotes = allBets.length;

    return (
        <div>
            <h2 style={styles.title}>EL CAMINO AL ASCENSO</h2>
            <div style={styles.bracketContainer}>
                <div style={styles.bracketMatchup}><div style={{...styles.bracketTeam, ...(config?.semi1_ganador === 'UD Almería' ? styles.bracketWinner : {})}}>UD Almería</div><span style={{color: styles.colors.silver, fontSize: '1.2rem', fontFamily: "'Oswald', sans-serif"}}>VS</span><div style={{...styles.bracketTeam, ...(config?.semi1_ganador === 'CD Castellón' ? styles.bracketWinner : {})}}>CD Castellón</div></div>
                <div style={styles.bracketMatchup}><div style={{...styles.bracketTeam, ...(config?.semi2_ganador === 'Málaga CF' ? styles.bracketWinner : {})}}>Málaga CF</div><span style={{color: styles.colors.silver, fontSize: '1.2rem', fontFamily: "'Oswald', sans-serif"}}>VS</span><div style={{...styles.bracketTeam, ...(config?.semi2_ganador === 'UD Las Palmas' ? styles.bracketWinner : {})}}>UD Las Palmas</div></div>
                <div style={styles.bracketFinal}><h4 style={{fontFamily: "'Oswald', sans-serif", color: styles.colors.golden, marginBottom: '15px', fontSize: '1.5rem', letterSpacing: '2px'}}>GRAN FINAL</h4><p style={{fontSize: '1.2rem', fontWeight: '600', color: styles.colors.lightText}}>{config?.semi1_ganador || '???'} vs {config?.semi2_ganador || '???'}</p>{config?.ascendido && <h3 style={{fontFamily: "'Oswald', sans-serif", color: styles.colors.success, marginTop: '20px', fontSize: '2rem', textShadow: '0 0 20px rgba(16,185,129,0.5)'}}>🎉 ASCIENDE: {config.ascendido} 🎉</h3>}</div>
            </div>
            
            <div style={{...styles.form, textAlign: 'center'}}>
                <h3 style={{fontFamily: "'Oswald', sans-serif", color: styles.colors.golden, marginBottom: '10px', fontSize: '1.4rem', letterSpacing: '1px'}}>APUESTA EXTRA <span style={styles.oddsBadge}>+5 PTS</span></h3>
                <p style={{marginBottom: '20px', color: styles.colors.silver, fontSize: '0.9rem'}}>¿Qué equipo logrará el ansiado ascenso a Primera?</p>
                
                {isSecreto && !config?.bloqueado && timeLeft !== 'CERRADO' && (
                    <div style={{marginBottom: '25px', padding: '15px', backgroundColor: 'rgba(230,57,70,0.1)', border: `1px solid rgba(230,57,70,0.3)`, borderRadius: '12px'}}>
                        <p style={{color: styles.colors.silver, fontWeight: 'bold', textTransform: 'uppercase', fontSize: '0.85rem', marginBottom: '5px', letterSpacing: '1px'}}>Cierre de Apuestas en:</p>
                        <p style={{color: styles.colors.danger, fontSize: '2rem', fontWeight: 'bold', fontFamily: "'Oswald', sans-serif", letterSpacing: '2px', textShadow: '0 0 10px rgba(230,57,70,0.4)'}}>{timeLeft}</p>
                    </div>
                )}

                {!hasBet && (!config || !config.bloqueado) && timeLeft !== 'CERRADO' ? (
                    <div style={{display: 'flex', gap: '15px', flexWrap: 'wrap', justifyContent: 'center'}}>
                        {["UD Almería", "Málaga CF", "UD Las Palmas", "CD Castellón"].map(eq => (<button key={eq} onClick={() => handleBet(eq)} style={{...styles.secondaryButton, padding: '12px 20px', fontSize: '1rem'}}>{eq}</button>))}
                    </div>
                ) : (
                    <div style={{padding: '20px', backgroundColor: 'rgba(212,175,55,0.05)', borderRadius: '16px', border: `1px solid rgba(212,175,55,0.3)`}}>
                        <p style={{fontWeight: '600', fontSize: '1.1rem', color: styles.colors.silver}}>Tu apuesta: <span style={{color: styles.colors.golden, fontFamily: "'Oswald', sans-serif", fontSize: '1.4rem', letterSpacing: '1px', marginLeft: '10px'}}>{apuesta || 'No apostaste'}</span></p>
                        {config?.ascendido && apuesta && <p style={{marginTop: '15px', fontWeight: 'bold', fontSize: '1.1rem', color: config.ascendido === apuesta ? styles.colors.success : styles.colors.danger}}>{config.ascendido === apuesta ? '¡HAS GANADO +5 PUNTOS!' : 'Apuesta Fallada'}</p>}
                    </div>
                )}
            </div>

            {/* --- GRÁFICA DE FAVORITOS --- */}
            {totalVotes > 0 && (
                <div style={styles.graphContainer}>
                    <h4 style={{fontFamily: "'Oswald', sans-serif", color: styles.colors.golden, marginBottom: '20px', textAlign: 'center', letterSpacing: '1px', fontSize: '1.2rem'}}>📊 FAVORITOS DE LA PEÑA</h4>
                    {Object.keys(stats).sort((a,b) => stats[b] - stats[a]).map(equipo => {
                        const pct = Math.round((stats[equipo] / totalVotes) * 100);
                        return (
                            <div key={equipo} style={styles.graphBarWrapper}>
                                <div style={styles.graphBarLabel}>
                                    <strong style={{color: '#fff'}}>{equipo}</strong>
                                    <span>{pct}% ({stats[equipo]} votos)</span>
                                </div>
                                <div style={styles.graphBarBg}>
                                    <div style={{...styles.graphBarFill, width: `${pct}%`}}></div>
                                </div>
                            </div>
                        )
                    })}
                </div>
            )}

            <div style={{marginTop: '40px'}}>
                <h4 style={styles.formSectionTitle}>APUESTAS DE LOS JUGADORES</h4>
                <div style={{backgroundColor: 'rgba(0,0,0,0.2)', padding: '20px', borderRadius: '16px', border: `1px solid rgba(255,215,0,0.15)`}}>
                    {allBets.length > 0 ? (
                        <ul style={{listStyle: 'none', padding: 0}}>
                            {allBets.map(b => (
                                <li key={b.id} style={{padding: '12px 0', borderBottom: `1px solid rgba(255,255,255,0.05)`, display: 'flex', justifyContent: 'space-between', alignItems: 'center'}}>
                                    <PlayerProfileDisplay name={b.id} profile={userProfiles[b.id]} isOnline={onlineUsers ? onlineUsers[b.id] : false} />
                                    {b.id === user ? ( <span style={{fontWeight: 'bold', color: styles.colors.golden, fontFamily: "'Oswald', sans-serif", letterSpacing: '1px', fontSize: '1.1rem'}}>{b.equipo}</span> ) : (
                                        isSecreto ? <span style={styles.secrecyBadge}>Secreta 🤫</span> : <span style={{fontWeight: '600', color: styles.colors.silver, fontFamily: "'Oswald', sans-serif", letterSpacing: '1px', fontSize: '1.1rem'}}>{b.equipo} {b.inyectado ? '(Auto)' : ''}</span>
                                    )}
                                </li>
                            ))}
                        </ul>
                    ) : (<p style={{textAlign: 'center', color: styles.colors.silver, fontStyle: 'italic'}}>Aún no hay apuestas.</p>)}
                </div>
            </div>
        </div>
    );
};

const PorraAnualScreen = ({ userProfiles, onlineUsers }) => {
    const [apuestasAnuales, setApuestasAnuales] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const q = query(collection(db, "porraAnual")); 
        const unsubscribe = onSnapshot(q, (snap) => {
            const data = snap.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            setApuestasAnuales(data);
            setLoading(false);
        });
        return () => unsubscribe();
    }, []);

    if (loading) return <LoadingSkeleton />;

    return (
        <div>
            <h2 style={styles.title}>PORRA ANUAL</h2>
            <p style={{textAlign: 'center', marginBottom: '25px', color: styles.colors.silver, fontSize: '0.9rem', lineHeight: 1.5}}>
                Apuestas de principio de temporada.<br/>
                <span style={{color: styles.colors.golden, fontWeight: 'bold'}}>+5 Pts Ascenso | +10 Pts Posición Exacta | +20 Pts Pleno</span>
            </p>
            
            {apuestasAnuales.length === 0 ? (
                <div style={styles.placeholder}>Aún no se han cargado los datos o la colección está vacía.</div>
            ) : (
                <div style={{display: 'flex', flexDirection: 'column', gap: '15px'}}>
                    {apuestasAnuales.map(apuesta => (
                        <div key={apuesta.id} style={{backgroundColor: 'rgba(0,0,0,0.4)', padding: '20px', borderRadius: '16px', borderLeft: `4px solid ${styles.colors.golden}`, boxShadow: '0 4px 10px rgba(0,0,0,0.2)'}}>
                            <div style={{marginBottom: '10px'}}><PlayerProfileDisplay name={apuesta.id} profile={userProfiles[apuesta.id]} isOnline={onlineUsers ? onlineUsers[apuesta.id] : false} /></div>
                            <div style={{display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', backgroundColor: 'rgba(255,255,255,0.05)', padding: '15px', borderRadius: '12px'}}>
                                <div>
                                    <p style={{color: styles.colors.silver, fontSize: '0.8rem', textTransform: 'uppercase'}}>Posición Final:</p>
                                    <p style={{color: styles.colors.golden, fontSize: '1.2rem', fontWeight: 'bold', fontFamily: "'Oswald', sans-serif"}}>{apuesta.posicion || '---'}</p>
                                </div>
                                <div>
                                    <p style={{color: styles.colors.silver, fontSize: '0.8rem', textTransform: 'uppercase'}}>¿Asciende?:</p>
                                    <p style={{color: (apuesta.asciende === 'Sí' || apuesta.asciende === true) ? styles.colors.success : styles.colors.danger, fontSize: '1.2rem', fontWeight: 'bold', fontFamily: "'Oswald', sans-serif"}}>{apuesta.asciende !== undefined ? String(apuesta.asciende) : '---'}</p>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};
// ============================================================================
// --- PANTALLAS SECUNDARIAS ---
// ============================================================================

const LigaRegularScreen = ({ userProfiles, onlineUsers }) => {
    const [clasificacion, setClasificacion] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const qClasificacion = query(collection(db, "clasificacion"));
        const unsubscribe = onSnapshot(qClasificacion, (snap) => {
            const data = snap.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            setClasificacion(data.sort((a, b) => (b.puntosTotales || 0) - (a.puntosTotales || 0)));
            setLoading(false);
        });
        return () => unsubscribe();
    }, []);

    if (loading) return <LoadingSkeleton />;

    return (
        <div>
            <h2 style={styles.title} className="app-title">LIGA REGULAR</h2>
            <p style={{textAlign: 'center', marginBottom: '25px', color: styles.colors.silver, fontSize: '0.9rem', lineHeight: 1.5}}>Clasificación consolidada de la Fase Regular.<br/>Esta es la base de puntos para la batalla del Playoff.</p>
            <div style={{overflowX: 'auto', backgroundColor: 'rgba(0,0,0,0.25)', borderRadius: '20px', border: `1px solid rgba(255,215,0,0.15)`, padding: '10px', backdropFilter: 'blur(5px)'}}>
                <table style={styles.table}>
                    <thead><tr><th style={styles.th}>POS</th><th style={styles.th}>JUGADOR</th><th style={{...styles.th, textAlign: 'center'}}>PUNTOS BASE</th></tr></thead>
                    <tbody>
                        {clasificacion.map((jugador, index) => (
                            <tr key={jugador.id} style={styles.tr}>
                                <td style={styles.tdRank}>{index + 1}º</td>
                                <td style={styles.td}><PlayerProfileDisplay name={jugador.id} profile={userProfiles[jugador.id]} isOnline={onlineUsers ? onlineUsers[jugador.id] : false} /></td>
                                <td style={styles.tdTotalPoints}>{jugador.puntosTotales || 0}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

const ClasificacionScreen = ({ currentUser, userProfiles, onlineUsers, pagos }) => {
    const [clasificacion, setClasificacion] = useState([]); 
    const [loading, setLoading] = useState(true); 
    const [campeonInvierno, setCampeonInvierno] = useState(null);
    const [jugadoresInactivosCL, setJugadoresInactivosCL] = useState([]); // para no contar en el bote a quien pagó y luego se retiró
    // Jugadores ARCHIVADOS: se fueron y ya no forman parte de la porra. No
    // aparecen en ninguna lista ni clasificación; su dinero queda en el bote.
    const [archivadosCL, setArchivadosCL] = useState([]);
    useEffect(() => {
        var unsubArch = onSnapshot(doc(db, 'configuracion', 'jugadoresArchivados'), function(snap) {
            setArchivadosCL(snap.exists() ? (snap.data().nombres || []) : []);
        }, function(){});
        return function() { unsubArch(); };
    }, []);
    // Desglose por jugador: ⭐ puntos de 5 Estrellas, 🛡️ ganado con ×, 🛡️ perdido con ÷
    const [extrasClasif, setExtrasClasif] = useState({});
    const [otroPendienteCL, setOtroPendienteCL] = useState(false);
    // El asterisco sale SOLO si el motor oficial dejó algo sin resolver.
    useEffect(() => {
        var u = onSnapshot(doc(db, 'configuracion', 'estadoPuntos'), function(s) {
            setOtroPendienteCL(s.exists() ? !!s.data().hayPendientes : false);
        }, function(){});
        return function() { u(); };
    }, []);

    useEffect(() => {
        var activo = true;
        (async function() {
            try {
                var ex = {};
                var asegurar = function(uid) { if (!ex[uid]) ex[uid] = { estrellas: 0, estrellasPend: 0, basePend: 0, ganadoOtro: 0, perdidoOtro: 0, porra: 0, unoX2: 0 }; return ex[uid]; };
                var acumularPronosticos = function(docs, cierreHecho, jd) {
                    docs.forEach(function(d) {
                        var p = d.data() || {};
                        if (p.noContabilizado) return;
                        // Los campos guardados (puntosResultadoExacto,
                        // puntosGoleador) faltan o están a 0 en muchos
                        // pronósticos, y eso hacía que TODO el base cayera en
                        // la columna 1X2. Se recalculan aquí con la fórmula
                        // real, que es la única fuente fiable.
                        var calc = calcularBasePronosticoJornada(p, jd);
                        var base = Number(p.puntosBaseSinOtro !== undefined ? p.puntosBaseSinOtro : calc.base);
                        var exacto = calc.exacto;
                        var goleador = calc.goleador;
                        var reg = asegurar(d.id);
                        reg.porra += exacto + goleador;                            // marcador exacto + goleador
                        reg.unoX2 += Math.max(0, calc.base - exacto - goleador);   // 1X2 / pasa-no pasa
                        // Mientras la jornada no tenga cierre definitivo, sus
                        // puntos NO están en clasificacion.puntosTotales: se
                        // suman aquí para que la tabla enseñe YA lo ganado.
                        // Si El Otro ya está resuelto, se suma el valor DESPUÉS
                        // del multiplicador o divisor, no la base.
                        if (!cierreHecho) {
                            var trasOtro = base;
                            if (p.elOtroAplicado && p.elOtroResultado) {
                                trasOtro = aplicarMultiplicadorOtro(base, p.elOtroResultado, Number(p.elOtroMultiplicador || 2));
                            }
                            reg.basePend += trasOtro;
                        }
                    });
                };
                var docsParaEfectoOtro = [];
                var acumularEstrellasJornada = function(docs, cierreHecho) {
                    docs.forEach(function(d) {
                        var ptsRk = Number((d.data() || {}).puntosRanking || 0);
                        var reg = asegurar(d.id);
                        reg.estrellas += ptsRk;
                        // Si la jornada aún no pasó por el cierre definitivo, estos
                        // puntos de Estrellas todavía NO están dentro de
                        // clasificacion.puntosTotales: se suman aquí para que la
                        // tabla los muestre YA, sin esperar a la animación del +.
                        if (!cierreHecho) reg.estrellasPend += ptsRk;
                    });
                };
                var jSnap = await getDocs(query(collection(db, 'jornadas'), where('estado', '==', 'Finalizada')));
                for (var i = 0; i < jSnap.docs.length; i++) {
                    var jid = jSnap.docs[i].id;
                    var jd = { id: jid, ...(jSnap.docs[i].data() || {}) };
                    var rSnap = await getDocs(collection(db, 'estrellas_resultados', jid, 'jugadores'));
                    acumularEstrellasJornada(rSnap.docs, !!jd.cierreDefinitivo);
                    var pSnap = await getDocs(collection(db, 'pronosticos', jid, 'jugadores'));
                    acumularPronosticos(pSnap.docs, !!jd.cierreDefinitivo, jd);
                    docsParaEfectoOtro.push(pSnap.docs);
                }
                // Efecto de El Otro: se calcula de los propios pronósticos ya
                // resueltos (fuente fiable), no del historial, que puede estar
                // incompleto si la resolución se hizo a mano.
                var acumularEfectoOtro = function(docs) {
                    docs.forEach(function(d) {
                        var p = d.data() || {};
                        if (!p.elOtroAplicado || !p.elOtroResultado || p.noContabilizado) return;
                        var b = Number(p.puntosBaseSinOtro || 0);
                        var tras = aplicarMultiplicadorOtro(b, p.elOtroResultado, Number(p.elOtroMultiplicador || 2));
                        var delta = tras - b;
                        var reg = asegurar(d.id);
                        if (delta > 0) reg.ganadoOtro += delta;
                        else if (delta < 0) reg.perdidoOtro += -delta;
                    });
                };
                docsParaEfectoOtro.forEach(function(ds) { acumularEfectoOtro(ds); });
                if (activo) setExtrasClasif(ex);
            } catch(e) { console.warn('Extras clasificación:', e.message); }
        })();
        return function() { activo = false; };
    }, []);

    useEffect(() => { 
        const qClasificacion = query(collection(db, "clasificacion")); 
        const unsubscribe = onSnapshot(qClasificacion, (querySnapshot) => { 
            const data = querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })); 
            setClasificacion(data.sort((a,b) => (b.puntosTotales || 0) - (a.puntosTotales || 0))); 
            setLoading(false); 
        }); 
        return () => unsubscribe();
    }, []);

    useEffect(() => {
        const unsub = onSnapshot(doc(db, 'configuracion', 'campeonInvierno'), (snap) => {
            setCampeonInvierno(snap.exists() ? snap.data() : null);
        });
        return () => unsub();
    }, []);

    useEffect(() => {
        const unsub = onSnapshot(doc(db, 'configuracion', 'jugadoresInactivos'), (snap) => {
            setJugadoresInactivosCL(snap.exists() ? (snap.data().nombres || []) : []);
        });
        return () => unsub();
    }, []);

    if (loading) return <LoadingSkeleton />; 

    // Bote real, calculado a partir de las inscripciones pagadas de verdad —
    // no una cifra fija, porque el nº de jugadores todavía puede cambiar
    // (mínimo 15, objetivo 20). Contamos jugadores únicos, por si alguien
    // pagó la inscripción de varios a la vez, y EXCLUIMOS a quien haya
    // pagado pero luego se haya retirado — antes se seguía contando su
    // inscripción para siempre, inflando el bote con gente que ya no juega.
    const inscritos = Array.from(new Set(
        (pagos || []).filter(function(p) { return p.tipo === 'inscripcion' && pagoCuentaComoValido(p); })
            .map(function(p) { return p.jugador; })
    )).filter(function(nombre) { return jugadoresInactivosCL.indexOf(nombre) === -1 && archivadosCL.indexOf(nombre) === -1; });
    const boteActual = inscritos.length * 5;
    const premio1 = (boteActual * 0.65).toFixed(2);
    const premio2 = (boteActual * 0.25).toFixed(2);
    const premio3 = (boteActual * 0.10).toFixed(2);

    // Filtrar jugadores inactivos y FUSIONAR con la lista real de inscritos
    // que han pagado — antes solo mostraba quien ya tenía un documento en la
    // colección 'clasificacion', así que los nuevos (que pagaron pero todavía
    // no habían sumado puntos) no aparecían nunca.
    var clasificacionMapa = {};
    clasificacion.forEach(function(j) { clasificacionMapa[j.id] = j; });

    var clasificacionCompleta = inscritos.map(function(nombre) {
        var datos = clasificacionMapa[nombre] || {};
        var extra = extrasClasif[nombre] || {};
        // Los puntos de las 5 Estrellas de jornadas todavía sin cierre
        // definitivo se suman al total MOSTRADO desde ya.
        // El motor oficial ya escribe el total absoluto: no se suman capas.
        var totalMostrado = Number(datos.puntosTotales || 0);
        return {
            id: nombre,
            puntosTotales: totalMostrado,
            puntosResultadoExacto: datos.puntosResultadoExacto || 0,
        };
    }).sort(function(a, b) {
        return (b.puntosTotales || 0) - (a.puntosTotales || 0);
    });

    return (
        <div>
            <h2 style={styles.title} className="app-title">CLASIFICACIÓN</h2>

            {campeonInvierno && campeonInvierno.top3 && campeonInvierno.top3[0] && (
                <div style={{background:'linear-gradient(135deg,#0091FF,#001F6B)',borderRadius:16,padding:'16px 18px',marginBottom:18,textAlign:'center'}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:3,color:'rgba(255,255,255,0.6)',textTransform:'uppercase',marginBottom:4}}>❄️ Campeón de Invierno</p>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:26,fontWeight:700,color:'#fff',letterSpacing:1}}>{campeonInvierno.top3[0].nombre}</p>
                </div>
            )}

            {/* Ranking — estilo La Jornada, no tabla antigua */}
            <div style={{background:'#fff',border:'1px solid rgba(0,31,107,0.1)',borderRadius:16,overflow:'hidden',marginBottom:20}}>
                {/* Cabecera de columnas — estilo periódico deportivo */}
                <div style={{display:'flex',alignItems:'center',gap:4,padding:'7px 8px',background:'rgba(0,31,107,0.05)',borderBottom:'1px solid rgba(0,31,107,0.08)'}}>
                    <span style={{width:18,fontFamily:"'Teko',sans-serif",fontSize:9,color:'rgba(0,31,107,0.45)',textAlign:'center'}}>#</span>
                    <span style={{flex:1,fontFamily:"'Teko',sans-serif",fontSize:9,letterSpacing:1,color:'rgba(0,31,107,0.45)',paddingLeft:30}}>JUGADOR</span>
                    <span style={{width:40,fontFamily:"'Teko',sans-serif",fontSize:9,letterSpacing:1,color:'rgba(0,31,107,0.6)',textAlign:'right',fontWeight:700}}>PTS{otroPendienteCL ? '*' : ''}</span>
                    <span style={{width:28,fontFamily:"'Teko',sans-serif",fontSize:9,color:'rgba(0,31,107,0.5)',textAlign:'center'}} title="Puntos por marcador exacto y goleador">POR</span>
                    <span style={{width:28,fontFamily:"'Teko',sans-serif",fontSize:9,color:'rgba(0,31,107,0.5)',textAlign:'center'}} title="Puntos por 1X2 / pasa-no pasa">1X2</span>
                    <span style={{width:24,fontFamily:"'Teko',sans-serif",fontSize:10,color:'rgba(0,31,107,0.5)',textAlign:'center'}} title="Puntos de 5 Estrellas">⭐</span>
                    <span style={{width:26,fontFamily:"'Teko',sans-serif",fontSize:10,color:'rgba(0,31,107,0.5)',textAlign:'center'}} title="Ganado con multiplicador">🛡️×</span>
                    <span style={{width:26,fontFamily:"'Teko',sans-serif",fontSize:10,color:'rgba(0,31,107,0.5)',textAlign:'center'}} title="Perdido por división">🛡️÷</span>
                </div>
                {clasificacionCompleta.map(function(jugador, index) {
                    var esMio = jugador.id === currentUser;
                    var perf = userProfiles[jugador.id] || {};
                    var isOnline = onlineUsers ? onlineUsers[jugador.id] : false;
                    var pts = jugador.puntosTotales || 0;
                    var exactos = jugador.puntosResultadoExacto || 0;
                    var ext = extrasClasif[jugador.id] || { estrellas: 0, ganadoOtro: 0, perdidoOtro: 0, porra: 0, unoX2: 0 };
                    return (
                        <div key={jugador.id} style={{display:'flex',alignItems:'center',gap:4,padding:'9px 8px',
                            borderBottom:'1px solid rgba(0,31,107,0.06)',
                            background: esMio ? 'rgba(255,215,0,0.08)' : index < 3 ? 'rgba(0,31,107,0.02)' : 'transparent'}}>
                            <span style={{fontFamily:"'Teko',sans-serif",fontSize:14,fontWeight:700,width:18,textAlign:'center',
                                color: index === 0 ? '#FFD700' : index === 1 ? '#C0C0C0' : index === 2 ? '#CD7F32' : 'rgba(0,31,107,0.3)'}}>
                                {index === 0 ? '🥇' : index === 1 ? '🥈' : index === 2 ? '🥉' : (index+1)}
                            </span>
                            <div style={{flex:1,minWidth:0,display:'flex',alignItems:'center',gap:6}}>
                                <IconoPerfilClickable nombre={jugador.id} perfil={perf} size={26} />
                                <span style={{fontFamily:"'Inter',sans-serif",fontSize:11,fontWeight: esMio ? 700 : 500,color:'#001F6B',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>
                                    {nombreVisible(jugador.id, perf)}
                                    {isOnline && <span style={{width:5,height:5,backgroundColor:'#10b981',borderRadius:'50%',display:'inline-block',marginLeft:4,boxShadow:'0 0 5px #10b981'}}></span>}
                                    {exactos > 0 && <span style={{fontFamily:"'Inter',sans-serif",fontSize:8,color:'rgba(0,31,107,0.4)',marginLeft:4}}>{exactos}🎯</span>}
                                </span>
                            </div>
                            {/* PTS TOTALES — pegados al nombre, en grande */}
                            <span style={{width:40,textAlign:'right',fontFamily:"'Teko',sans-serif",fontSize:21,fontWeight:700,lineHeight:1,
                                color: index === 0 ? '#FFD700' : pts > 0 ? '#001F6B' : 'rgba(0,31,107,0.25)'}}>
                                {pts}{otroPendienteCL ? <span style={{fontSize:11,color:'rgba(0,31,107,0.4)'}}>*</span> : null}
                            </span>
                            <span style={{width:28,textAlign:'center',fontFamily:"'Teko',sans-serif",fontSize:13,fontWeight:700,color: ext.porra > 0 ? '#001F6B' : 'rgba(0,31,107,0.22)'}}>{ext.porra}</span>
                            <span style={{width:28,textAlign:'center',fontFamily:"'Teko',sans-serif",fontSize:13,fontWeight:700,color: ext.unoX2 > 0 ? '#001F6B' : 'rgba(0,31,107,0.22)'}}>{ext.unoX2}</span>
                            <span style={{width:24,textAlign:'center',fontFamily:"'Teko',sans-serif",fontSize:13,fontWeight:700,color: ext.estrellas > 0 ? '#b8860b' : 'rgba(0,31,107,0.22)'}}>{ext.estrellas}</span>
                            <span style={{width:26,textAlign:'center',fontFamily:"'Teko',sans-serif",fontSize:12,fontWeight:700,color: ext.ganadoOtro > 0 ? '#0f8a61' : 'rgba(0,31,107,0.22)'}}>{ext.ganadoOtro > 0 ? '+' + ext.ganadoOtro : '0'}{otroPendienteCL ? '*' : ''}</span>
                            <span style={{width:26,textAlign:'center',fontFamily:"'Teko',sans-serif",fontSize:12,fontWeight:700,color: ext.perdidoOtro > 0 ? '#e63946' : 'rgba(0,31,107,0.22)'}}>{ext.perdidoOtro > 0 ? '−' + ext.perdidoOtro : '0'}{otroPendienteCL ? '*' : ''}</span>
                        </div>
                    );
                })}
            </div>

            {/* Leyenda de columnas */}
            <div style={{background:'rgba(0,31,107,0.035)',border:'1px dashed rgba(0,31,107,0.18)',borderRadius:12,padding:'10px 14px',marginBottom:16}}>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:11,letterSpacing:2,color:'rgba(0,31,107,0.5)',textTransform:'uppercase',marginBottom:5,fontWeight:700}}>📖 CÓMO LEER LA TABLA</p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:10.5,color:'rgba(0,31,107,0.65)',lineHeight:1.7,margin:0}}>
                    · <strong>PTS</strong> (número grande): puntos TOTALES de la clasificación general — ya incluyen todo lo de la derecha.<br/>
                    · <strong>POR</strong>: puntos de la PORRA (marcador exacto y goleador).<br/>
                    · <strong>1X2</strong>: puntos por acertar el 1X2 / pasa-no pasa.<br/>
                    · <strong>⭐</strong>: puntos aportados por las 5 Estrellas (5/4/3/2/1 según el ranking de cada jornada).<br/>
                    · <strong>🛡️×</strong>: puntos EXTRA ganados al multiplicar con El Otro Equipo.<br/>
                    · <strong>🛡️÷</strong>: puntos PERDIDOS por división al fallar El Otro Equipo.<br/>
                    {otroPendienteCL ? <span>· <strong>*</strong>: hay jornadas con El Otro aún SIN resolver — último dato actualizado; puede variar al cerrarse la jornada de Primera.</span> : null}
                </p>
            </div>

            {/* Premios y bote — al final, como pediste */}
            <div style={{background:'linear-gradient(135deg,#001F6B,#003a9e)',borderRadius:16,padding:20,marginBottom:16}}>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:3,color:'rgba(255,255,255,0.5)',textTransform:'uppercase',marginBottom:10}}>
                    Bote de la porra
                </p>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:36,fontWeight:700,color:'#FFD700',textAlign:'center',marginBottom:6}}>
                    {boteActual}€
                </p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(255,255,255,0.45)',textAlign:'center',marginBottom:16}}>
                    {inscritos.length} inscritos · solo de inscripciones
                </p>
                <div style={{display:'flex',gap:8,justifyContent:'center'}}>
                    {[
                        {emoji:'🥇', label:'1º (65%)', valor: premio1},
                        {emoji:'🥈', label:'2º (25%)', valor: premio2},
                        {emoji:'🥉', label:'3º (10%)', valor: premio3},
                    ].map(function(p) {
                        return (
                            <div key={p.label} style={{flex:1,textAlign:'center',background:'rgba(255,255,255,0.06)',borderRadius:10,padding:'10px 6px'}}>
                                <p style={{fontSize:20,marginBottom:2}}>{p.emoji}</p>
                                <p style={{fontFamily:"'Teko',sans-serif",fontSize:18,fontWeight:700,color:'#FFD700'}}>{p.valor}€</p>
                                <p style={{fontFamily:"'Inter',sans-serif",fontSize:9,color:'rgba(255,255,255,0.4)'}}>{p.label}</p>
                            </div>
                        );
                    })}
                </div>
            </div>

            <div style={{background:'rgba(255,215,0,0.06)',border:'1px solid rgba(255,215,0,0.25)',borderRadius:16,padding:'16px 18px'}}>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:15,letterSpacing:2,color:'#FFD700',textTransform:'uppercase',marginBottom:8,fontWeight:700}}>
                    🎁 Y todavía hay más en juego
                </p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(255,255,255,0.7)',lineHeight:1.7,margin:0}}>
                    ❄️ <strong>Campeón de Invierno</strong> — quien vaya primero a mitad de temporada.<br/>
                    🎟️ <strong>Rifas</strong> durante la temporada, con sus propios premios.<br/>
                    ⭐ Ganador de la <strong>Liga de Estrellas</strong> — premio aparte de alto valor.
                </p>
            </div>
        </div>
    );
};

const PagosScreen = ({ currentUser, contextoPago, onContextoPagoUsado }) => {
    var G = styles.colors;
    var [jugadoresInactivos, setJugadoresInactivos] = useState([]);
    var [jugadoresAprobados, setJugadoresAprobados] = useState([]);
    var JUGADORES_TODOS = Array.from(new Set(JUGADORES_FUNDADORES.concat(jugadoresAprobados)));
    var JUGADORES_LISTA = JUGADORES_TODOS.filter(function(j) { return jugadoresInactivos.indexOf(j) === -1; });
    var [paso, setPaso] = useState('inicio');
    var [pagos, setPagos] = useState([]);
    var [jornadas, setJornadas] = useState([]);
    var [tipoPago, setTipoPago] = useState('inscripcion');
    var [jornadaSel, setJornadaSel] = useState('');
    var [jugadoresPagando, setJugadoresPagando] = useState([currentUser]);
    var [jugadoresPendientes, setJugadoresPendientes] = useState([]);
    var [error, setError] = useState('');
    var [bizumInfo, setBizumInfo] = useState({ nombre: 'Juanma', telefono: '' });
    var [copiado, setCopiado] = useState(false);
    var [heEnviado, setHeEnviado] = useState(false);

    useEffect(function() {
        var unsub = onSnapshot(doc(db, 'configuracion', 'bizum'), function(snap) {
            if (snap.exists()) setBizumInfo(snap.data());
        });
        return function() { unsub(); };
    }, []);

    // Si llegamos aquí desde el aviso de "falta pagar esta jornada" en Mi
    // Jornada, viene con el tipo y la jornada ya decididos — saltamos
    // directos al paso de selección, ya rellena, en vez de obligar a elegir
    // todo desde cero otra vez.
    useEffect(function() {
        if (!contextoPago) return;
        setTipoPago(contextoPago.tipo);
        setJornadaSel(contextoPago.jornada);
        setJugadoresPagando([currentUser]);
        setPaso('seleccion');
        if (onContextoPagoUsado) onContextoPagoUsado();
    }, [contextoPago, currentUser, onContextoPagoUsado]);

    useEffect(function() {
        var unsub = onSnapshot(doc(db, 'configuracion', 'jugadoresInactivos'), function(snap) {
            setJugadoresInactivos(snap.exists() ? (snap.data().nombres || []) : []);
        });
        return function() { unsub(); };
    }, []);

    useEffect(function() {
        var unsub = onSnapshot(doc(db, 'configuracion', 'jugadoresAprobados'), function(snap) {
            setJugadoresAprobados(snap.exists() ? (snap.data().nombres || []) : []);
        });
        return function() { unsub(); };
    }, []);

    useEffect(function() {
        var unsub = onSnapshot(query(collection(db, 'pagos'), orderBy('creadoEn','desc')),
            function(snap) { setPagos(snap.docs.map(function(d){return{id:d.id,...d.data()};})); }
        );
        return function(){unsub();};
    }, []);

    useEffect(function() {
        var unsub = onSnapshot(query(collection(db,'jornadas'),orderBy('numeroJornada','asc')),
            function(snap){setJornadas(snap.docs.map(function(d){return{id:d.id,...d.data()};}));}
        );
        return function(){unsub();};
    }, []);

    // Calcular jugadores con apuesta sin pagar (para que Laura pueda pagarles)
    useEffect(function() {
        if (tipoPago === 'inscripcion') {
            var sinInscripcion = JUGADORES_LISTA.filter(function(j) {
                return !pagos.some(function(p){ return p.jugador===j && p.tipo==='inscripcion' && p.estado!=='fallido' && p.estado!=='cancelado' && p.estado!=='rechazado'; });
            });
            setJugadoresPendientes(sinInscripcion);
        } else if (jornadaSel) {
            var sinJornada = JUGADORES_LISTA.filter(function(j) {
                return !pagos.some(function(p){ return p.jugador===j && p.jornada===jornadaSel && p.estado!=='fallido' && p.estado!=='cancelado' && p.estado!=='rechazado'; });
            });
            setJugadoresPendientes(sinJornada);
        }
    }, [pagos, tipoPago, jornadaSel]); // eslint-disable-line react-hooks/exhaustive-deps

    var toggleJugadorPagando = function(j) {
        setJugadoresPagando(function(prev) {
            var ya = prev.indexOf(j) > -1;
            if (ya) return prev.filter(function(x){return x!==j;});
            return prev.concat([j]);
        });
    };

    var precioUnitario = tipoPago==='inscripcion' ? 5 : tipoPago==='jornada_normal' ? 1 : 2;
    var total = jugadoresPagando.length * precioUnitario;

    var iniciarPago = function() {
        if (jugadoresPagando.length === 0) { setError('Selecciona al menos un jugador'); return; }
        if (tipoPago !== 'inscripcion' && !jornadaSel) { setError('Selecciona la jornada'); return; }
        setError('');
        setPaso('bizum');
    };

    var confirmarEnvioBizum = async function() {
        setPaso('procesando');
        try {
            var batch = jugadoresPagando.map(function(j) {
                return addDoc(collection(db,'pagos'), {
                    jugador: j,
                    pagoBy: currentUser,
                    tipo: tipoPago,
                    jornada: jornadaSel || null,
                    importe: precioUnitario,
                    descripcion: tipoPago==='inscripcion' ? 'Inscripción 26/27' : ('Jornada '+(tipoPago==='jornada_vip'?'VIP ':'')+ jornadaSel),
                    metodo: 'bizum',
                    estado: 'pendiente_confirmacion', // el admin lo confirma tras verlo en su banco
                    creadoEn: serverTimestamp(),
                });
            });
            await Promise.all(batch);
            setPaso('ok');
        } catch(e) {
            setError('Error: ' + e.message);
            setPaso('bizum');
        }
    };

    var misPagos = pagos.filter(function(p){return p.jugador===currentUser||p.pagoBy===currentUser;});
    var inscripcionPagada = jugadorHaPagado(currentUser, pagos);
    var S = {
        card: {background:'#fff',border:'1px solid rgba(0,31,107,0.1)',borderRadius:16,padding:18,marginBottom:14},
        label: {fontFamily:"'Teko',sans-serif",fontSize:11,letterSpacing:2,color:'rgba(0,31,107,0.5)',textTransform:'uppercase',display:'block',marginBottom:6},
        select: {width:'100%',padding:'11px 14px',border:'1.5px solid rgba(0,31,107,0.15)',borderRadius:12,fontFamily:"'Inter',sans-serif",fontSize:14,color:'#001F6B',outline:'none',marginBottom:14,background:'#f8f9ff'},
        btnPrimary: {width:'100%',fontFamily:"'Teko',sans-serif",fontSize:'1.1rem',letterSpacing:3,background:'#001F6B',color:'#FFD700',border:'none',borderRadius:30,padding:'14px',cursor:'pointer',textTransform:'uppercase',boxShadow:'0 6px 24px rgba(0,31,107,0.2)'},
        btnSec: {width:'100%',fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:2,background:'rgba(0,31,107,0.06)',color:'#001F6B',border:'1px solid rgba(0,31,107,0.12)',borderRadius:12,padding:'11px',cursor:'pointer',textTransform:'uppercase',marginTop:10},
        tag: function(c){return{background:c+'20',color:c,border:'1px solid '+c+'40',borderRadius:8,padding:'3px 10px',fontFamily:"'Inter',sans-serif",fontSize:10,fontWeight:600};},
        jugBtn: function(sel){return{padding:'8px 14px',borderRadius:10,border:'none',cursor:'pointer',fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:1,background:sel?'#001F6B':'rgba(0,31,107,0.06)',color:sel?'#FFD700':'#001F6B',transition:'all .15s',fontWeight:sel?700:400};},
    };

    // ── INICIO ─────────────────────────────────────────────────────────────
    if (paso === 'inicio') return (
        <div style={{paddingBottom:40}}>
            <h2 style={{fontFamily:"'Teko',sans-serif",fontSize:22,letterSpacing:3,color:'#001F6B',textTransform:'uppercase',marginBottom:6,fontWeight:700}}>💳 PAGOS</h2>
            <p style={{fontFamily:"'Inter',sans-serif",fontSize:13,color:'rgba(0,31,107,0.5)',marginBottom:20,lineHeight:1.6}}>
                Paga tu inscripción y las jornadas. Puedes pagar por otros jugadores en un solo cobro.
            </p>

            {/* Estado inscripción propia */}
            <div style={{...S.card,border:inscripcionPagada?'1.5px solid #10b981':'1.5px solid rgba(255,215,0,0.5)',background:inscripcionPagada?'rgba(16,185,129,0.04)':'rgba(255,215,0,0.04)'}}>
                <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:inscripcionPagada?0:14}}>
                    <div>
                        <p style={{fontFamily:"'Teko',sans-serif",fontSize:18,letterSpacing:1,color:'#001F6B',marginBottom:2}}>Tu inscripción 26/27</p>
                        <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(0,31,107,0.5)'}}>5€ · Pago único para toda la temporada</p>
                    </div>
                    {inscripcionPagada
                        ? <span style={S.tag('#10b981')}>✅ Pagada</span>
                        : <span style={S.tag('#FFD700')}>⚠️ Pendiente</span>}
                </div>
                {!inscripcionPagada && (
                    <button onClick={function(){setTipoPago('inscripcion');setJugadoresPagando([currentUser]);setPaso('seleccion');}} style={S.btnPrimary}>
                        Pagar mi inscripción — 5€ →
                    </button>
                )}
            </div>

            {/* Pagar por otros */}
            <div style={S.card}>
                <p style={{fontFamily:"'Teko',sans-serif",fontSize:18,letterSpacing:1,color:'#001F6B',marginBottom:4}}>Pagar por alguien más</p>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(0,31,107,0.5)',marginBottom:14,lineHeight:1.5}}>
                    ¿Quieres pagar la inscripción o una jornada de otro jugador? Selecciona aquí y se hace en un solo cobro.
                </p>
                <button onClick={function(){setTipoPago('inscripcion');setJugadoresPagando([]);setPaso('seleccion');}} style={S.btnPrimary}>
                    Pagar por otros →
                </button>
            </div>

            {/* Mis pagos */}
            {misPagos.length > 0 && (
                <div>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:2,color:'rgba(0,31,107,0.4)',textTransform:'uppercase',marginBottom:10}}>Mis pagos</p>
                    {misPagos.slice(0,8).map(function(p) {
                        var color = p.estado==='completado'?'#10b981':p.estado==='fallido'?'#e63946':'rgba(0,31,107,0.4)';
                        return (
                            <div key={p.id} style={{...S.card,display:'flex',alignItems:'center',gap:10,padding:'12px 16px',marginBottom:8}}>
                                <div style={{flex:1}}>
                                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:15,color:'#001F6B',letterSpacing:1}}>{p.descripcion}</p>
                                    {p.pagoBy && p.pagoBy!==p.jugador && <p style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(0,31,107,0.4)'}}>Pagado por {p.pagoBy}</p>}
                                </div>
                                <span style={{fontFamily:"'Teko',sans-serif",fontSize:18,fontWeight:700,color:'#001F6B'}}>{p.importe}€</span>
                                <span style={S.tag(color)}>{p.estado||'ok'}</span>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
    );

    // ── SELECCIÓN DE QUIÉN PAGA ─────────────────────────────────────────────
    if (paso === 'seleccion') return (
        <div style={{paddingBottom:40}}>
            <button onClick={function(){setPaso('inicio');}} style={{background:'none',border:'none',fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:2,color:'rgba(0,31,107,0.5)',cursor:'pointer',marginBottom:16,textTransform:'uppercase'}}>← Volver</button>
            <h2 style={{fontFamily:"'Teko',sans-serif",fontSize:20,letterSpacing:3,color:'#001F6B',textTransform:'uppercase',marginBottom:20,fontWeight:700}}>¿Qué pagas?</h2>

            <div style={S.card}>
                <label style={S.label}>Tipo de pago</label>
                <select style={S.select} value={tipoPago} onChange={function(e){setTipoPago(e.target.value);setJugadoresPagando([currentUser]);}}>
                    <option value="inscripcion">Inscripción temporada — 5€/persona</option>
                    <option value="jornada_normal">Jornada normal — 1€/persona</option>
                    <option value="jornada_vip">Jornada VIP — 2€/persona</option>
                </select>

                {tipoPago !== 'inscripcion' && (
                    <div>
                        <label style={S.label}>Jornada</label>
                        <select style={S.select} value={jornadaSel} onChange={function(e){setJornadaSel(e.target.value);}}>
                            <option value="">Selecciona jornada...</option>
                            {jornadas.map(function(j){
                                return <option key={j.id} value={'J'+j.numeroJornada}>J{j.numeroJornada} — {j.equipoLocal} vs {j.equipoVisitante}</option>;
                            })}
                        </select>
                    </div>
                )}

                <label style={S.label}>¿Por quién pagas? (Toca para seleccionar)</label>
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,0.4)',marginBottom:10,lineHeight:1.5}}>
                    Solo aparecen los que aún no han pagado esto. Puedes pagar por varios en un solo cobro.
                </p>
                <div style={{display:'flex',flexWrap:'wrap',gap:8,marginBottom:16}}>
                    {jugadoresPendientes.map(function(j) {
                        var sel = jugadoresPagando.indexOf(j) > -1;
                        return (
                            <button key={j} onClick={function(){toggleJugadorPagando(j);}} style={S.jugBtn(sel)}>
                                {sel ? '✓ ' : ''}{j}
                            </button>
                        );
                    })}
                    {jugadoresPendientes.length === 0 && (
                        <p style={{fontFamily:"'Inter',sans-serif",fontSize:13,color:'rgba(0,31,107,0.4)'}}>
                            Todos han pagado esto ✅
                        </p>
                    )}
                </div>

                {/* Resumen del total */}
                {jugadoresPagando.length > 0 && (
                    <div style={{background:'rgba(0,31,107,0.05)',borderRadius:12,padding:'12px 16px',marginBottom:16}}>
                        <div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}>
                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:13,color:'rgba(0,31,107,0.7)'}}>
                                {jugadoresPagando.join(', ')}
                            </p>
                            <p style={{fontFamily:"'Teko',sans-serif",fontSize:24,fontWeight:700,color:'#001F6B'}}>
                                {total}€
                            </p>
                        </div>
                        <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,0.4)',marginTop:4}}>
                            {jugadoresPagando.length} persona{jugadoresPagando.length>1?'s':''} × {precioUnitario}€
                        </p>
                    </div>
                )}

                {error && <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'#e63946',marginBottom:12,textAlign:'center'}}>{error}</p>}

                <button onClick={iniciarPago} disabled={jugadoresPagando.length===0} style={{...S.btnPrimary,opacity:jugadoresPagando.length===0?0.5:1}}>
                    Continuar — pagar {total}€ →
                </button>
            </div>
        </div>
    );

    // ── BIZUM ─────────────────────────────────────────────────────────────
    if (paso === 'bizum') return (
        <div style={{paddingBottom:40}}>
            <button onClick={function(){setPaso('seleccion');setHeEnviado(false);}} style={{background:'none',border:'none',fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:2,color:'rgba(0,31,107,0.5)',cursor:'pointer',marginBottom:16,textTransform:'uppercase'}}>← Volver</button>
            <h2 style={{fontFamily:"'Teko',sans-serif",fontSize:20,letterSpacing:3,color:'#001F6B',textTransform:'uppercase',marginBottom:20,fontWeight:700}}>Pagar {total}€ por Bizum</h2>

            <div style={S.card}>
                <div style={{background:'rgba(0,31,107,0.04)',borderRadius:10,padding:'10px 14px',marginBottom:16}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:1,color:'#001F6B',marginBottom:2}}>
                        {tipoPago==='inscripcion'?'Inscripción 26/27':'Jornada '+(tipoPago==='jornada_vip'?'VIP ':'')+jornadaSel}
                    </p>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,0.5)'}}>
                        Para: {jugadoresPagando.join(', ')}
                    </p>
                </div>

                {/* Paso 1: enviar el Bizum */}
                <div style={{background:'rgba(0,145,255,0.05)',border:'1px solid rgba(0,145,255,0.15)',borderRadius:14,padding:18,marginBottom:16,textAlign:'center'}}>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:2,color:'#0091FF',textTransform:'uppercase',marginBottom:10}}>
                        1 · Envía {total}€ por Bizum a
                    </p>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:28,fontWeight:700,color:'#001F6B',letterSpacing:1,marginBottom:4}}>
                        {bizumInfo.telefono || '(número pendiente de configurar)'}
                    </p>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(0,31,107,0.5)',marginBottom:14}}>
                        {bizumInfo.nombre}
                    </p>
                    {bizumInfo.telefono && (
                        <button onClick={function() {
                            navigator.clipboard.writeText(bizumInfo.telefono);
                            setCopiado(true); setTimeout(function(){setCopiado(false);}, 2000);
                        }} style={{fontFamily:"'Teko',sans-serif",fontSize:13,letterSpacing:2,background:'#0091FF',color:'#fff',
                            border:'none',borderRadius:20,padding:'8px 20px',cursor:'pointer',textTransform:'uppercase'}}>
                            {copiado ? '✓ Copiado' : '📋 Copiar número'}
                        </button>
                    )}
                </div>

                {/* Paso 2: confirmar que se ha enviado */}
                <div style={{marginBottom:16}}>
                    <label style={{display:'flex',alignItems:'center',gap:10,cursor:'pointer',padding:'10px 4px'}}>
                        <input type="checkbox" checked={heEnviado} onChange={function(e){setHeEnviado(e.target.checked);}}
                            style={{width:20,height:20,accentColor:'#001F6B'}} />
                        <span style={{fontFamily:"'Inter',sans-serif",fontSize:13,color:'#001F6B'}}>
                            Ya he enviado el Bizum de {total}€
                        </span>
                    </label>
                </div>

                {error && <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'#e63946',marginBottom:12,textAlign:'center'}}>{error}</p>}

                <button onClick={confirmarEnvioBizum} disabled={!heEnviado} style={{...S.btnPrimary,opacity:heEnviado?1:0.5}}>
                    Confirmar pago →
                </button>

                <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,color:'rgba(0,31,107,0.4)',textAlign:'center',marginTop:12,lineHeight:1.5}}>
                    Tu pago quedará "pendiente" hasta que {bizumInfo.nombre} lo confirme al verlo en el banco — normalmente el mismo día.
                </p>
            </div>
        </div>
    );

    // ── PROCESANDO ────────────────────────────────────────────────────────────
    if (paso === 'procesando') return (
        <div style={{display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',padding:60,textAlign:'center'}}>
            <div style={{fontSize:52,marginBottom:16}}>⏳</div>
            <p style={{fontFamily:"'Teko',sans-serif",fontSize:20,letterSpacing:3,color:'#001F6B',textTransform:'uppercase'}}>Guardando confirmación...</p>
        </div>
    );

    // ── OK ─────────────────────────────────────────────────────────────────
    if (paso === 'ok') return (
        <div style={{display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',padding:40,textAlign:'center'}}>
            <div style={{fontSize:64,marginBottom:16}}>✅</div>
            <p style={{fontFamily:"'Teko',sans-serif",fontSize:24,letterSpacing:3,color:'#001F6B',textTransform:'uppercase',marginBottom:8}}>¡Pago confirmado!</p>
            <p style={{fontFamily:"'Inter',sans-serif",fontSize:14,color:'rgba(0,31,107,0.6)',marginBottom:8,lineHeight:1.7}}>
                {total}€ pagados por {currentUser}
            </p>
            <p style={{fontFamily:"'Inter',sans-serif",fontSize:13,color:'rgba(0,31,107,0.5)',marginBottom:24,lineHeight:1.6}}>
                Para: <strong>{jugadoresPagando.join(', ')}</strong>
            </p>
            <button onClick={function(){setPaso('inicio');setJugadoresPagando([currentUser]);setJornadaSel('');}} style={{fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:2,background:'#001F6B',color:'#FFD700',border:'none',borderRadius:12,padding:'12px 28px',cursor:'pointer',textTransform:'uppercase'}}>
                Volver a pagos
            </button>
        </div>
    );

    return null;
};

// ============================================================================
// --- ESTADÍSTICAS ───────────────────────────────────────────────────────────
// ============================================================================
const EstadisticasScreen = ({ userProfiles, onlineUsers, pagos }) => {
    var G = styles.colors;
    var [clasificacion, setClasificacion] = useState([]);
    var [jornadas, setJornadas] = useState([]);
    var [historico, setHistorico] = useState(false);
    var [jugadoresInactivosEst, setJugadoresInactivosEst] = useState([]);

    useEffect(function() {
        var unsub = onSnapshot(collection(db, 'clasificacion'), function(snap) {
            var data = snap.docs.map(function(d) { return { id: d.id, ...d.data() }; });
            setClasificacion(data);
        });
        return function(){unsub();};
    }, []);

    useEffect(function() {
        var unsub = onSnapshot(query(collection(db,'jornadas'),orderBy('numeroJornada','asc')),
            function(snap){setJornadas(snap.docs.map(function(d){return{id:d.id,...d.data()};}));});
        return function(){unsub();};
    }, []);

    useEffect(function() {
        var unsub = onSnapshot(doc(db, 'configuracion', 'jugadoresInactivos'), function(snap) {
            setJugadoresInactivosEst(snap.exists() ? (snap.data().nombres || []) : []);
        });
        return function(){unsub();};
    }, []);

    // Lista real de inscritos activos — fusionada con los datos de
    // clasificación que existan, para que aparezcan TODOS los que han pagado.
    var inscritosEst = Array.from(new Set(
        (pagos || []).filter(function(p) { return p.tipo === 'inscripcion' && pagoCuentaComoValido(p); })
            .map(function(p) { return p.jugador; })
    )).filter(function(nombre) { return jugadoresInactivosEst.indexOf(nombre) === -1; });

    var clasificacionMapa = {};
    clasificacion.forEach(function(j) { clasificacionMapa[j.id] = j; });

    var clasificacionActiva = inscritosEst.map(function(nombre) {
        var datos = clasificacionMapa[nombre] || {};
        return { id: nombre, puntosTotales: datos.puntosTotales || 0, puntosResultadoExacto: datos.puntosResultadoExacto || 0 };
    }).sort(function(a,b) { return (b.puntosTotales||0) - (a.puntosTotales||0); });

    var medallaColor = ['#FFD700','#C0C0C0','#CD7F32'];

    // ⏸️ TEMPORAL: con solo una jornada disputada aún no hay muestra
    // suficiente para elaborar estadísticas con sentido. Cambiar a true
    // cuando haya 3-4 jornadas y la pantalla completa vuelve tal cual.
    var ESTADISTICAS_ACTIVAS = false;
    if (!ESTADISTICAS_ACTIVAS) {
        return (
            <div style={{paddingBottom:40}}>
                <h2 style={styles.title}>📊 ESTADÍSTICAS</h2>
                <div style={{background:'#fff',border:'1px solid rgba(0,31,107,0.08)',borderRadius:18,padding:'34px 22px',textAlign:'center'}}>
                    <p style={{fontSize:42,marginBottom:12}}>📈</p>
                    <p style={{fontFamily:"'Teko',sans-serif",fontSize:20,letterSpacing:2,color:'#001F6B',marginBottom:8}}>AÚN NO HAY DATOS SUFICIENTES</p>
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'rgba(0,31,107,0.55)',lineHeight:1.7,margin:0}}>
                        Con una sola jornada disputada, las estadísticas todavía no cuentan nada fiable.<br/>
                        En cuanto se acumulen unas cuantas jornadas, esta pantalla se activará con rachas, medias, aciertos exactos y mucho más. 📊
                    </p>
                </div>
            </div>
        );
    }

    return (
        <div style={{paddingBottom:40}}>
            <h2 style={{fontFamily:"'Teko',sans-serif",fontSize:22,letterSpacing:3,color:G.deepBlue,textTransform:'uppercase',marginBottom:16,fontWeight:700}}>
                📊 ESTADÍSTICAS
            </h2>
            <p style={{fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:3,color:'rgba(0,31,107,0.4)',textTransform:'uppercase',marginBottom:10}}>
                Clasificación 26/27
            </p>
            <div style={{background:'#fff',border:'1px solid rgba(0,31,107,0.1)',borderRadius:16,overflow:'hidden',marginBottom:18}}>
                {clasificacion.length === 0 ? (
                    <p style={{fontFamily:"'Inter',sans-serif",fontSize:13,color:'rgba(0,31,107,0.4)',padding:20,textAlign:'center'}}>
                        La clasificación se actualizará al cerrar la primera jornada
                    </p>
                ) : clasificacionActiva.map(function(j, idx) {
                    var online = onlineUsers && onlineUsers[j.id];
                    var perfil = userProfiles && userProfiles[j.id];
                    return (
                        <div key={j.id} style={{display:'flex',alignItems:'center',gap:12,padding:'12px 16px',
                            borderBottom:idx<clasificacion.length-1?'1px solid rgba(0,31,107,0.06)':'none',
                            background:idx===0?'rgba(255,215,0,0.04)':'#fff'}}>
                            <span style={{fontFamily:"'Teko',sans-serif",fontSize:20,fontWeight:700,
                                color:idx<3?medallaColor[idx]:'rgba(0,31,107,0.25)',minWidth:24,textAlign:'center'}}>
                                {idx<3?['🥇','🥈','🥉'][idx]:idx+1}
                            </span>
                            <div style={{width:34,height:34,borderRadius:'50%',background:'rgba(0,31,107,0.08)',
                                display:'flex',alignItems:'center',justifyContent:'center',
                                fontFamily:"'Teko',sans-serif",fontSize:16,color:G.deepBlue,flexShrink:0,
                                border:online?'2px solid #10b981':'2px solid transparent'}}>
                                {perfil&&perfil.emoji?perfil.emoji:(j.id||'?')[0].toUpperCase()}
                            </div>
                            <span style={{fontFamily:"'Teko',sans-serif",fontSize:18,color:G.deepBlue,letterSpacing:1,flex:1}}>{j.id}</span>
                            <div style={{textAlign:'right'}}>
                                <span style={{fontFamily:"'Teko',sans-serif",fontSize:22,fontWeight:700,color:G.deepBlue}}>{j.puntos||0}</span>
                                <span style={{fontFamily:"'Inter',sans-serif",fontSize:10,color:'rgba(0,31,107,0.4)',marginLeft:4}}>pts</span>
                            </div>
                        </div>
                    );
                })}
            </div>
            <button onClick={function(){setHistorico(function(h){return !h;});}}
                style={{width:'100%',background:'rgba(0,31,107,0.06)',border:'1px solid rgba(0,31,107,0.12)',
                    borderRadius:12,padding:'11px',fontFamily:"'Teko',sans-serif",fontSize:14,
                    letterSpacing:2,color:G.deepBlue,cursor:'pointer',textTransform:'uppercase',marginBottom:14}}>
                {historico?'▲ Ocultar':'▼ Ver'} historial de jornadas
            </button>
            {historico && jornadas.filter(function(j){return j.estado==='Finalizada';}).map(function(j) {
                return (
                    <div key={j.id} style={{background:'#fff',border:'1px solid rgba(0,31,107,0.1)',borderRadius:14,padding:'14px 16px',marginBottom:8}}>
                        <div style={{display:'flex',alignItems:'center',gap:10}}>
                            <span style={{fontFamily:"'Teko',sans-serif",fontSize:16,fontWeight:700,color:G.deepBlue,minWidth:28}}>J{j.numeroJornada}</span>
                            <span style={{fontFamily:"'Teko',sans-serif",fontSize:14,letterSpacing:1,color:G.deepBlue,flex:1,textTransform:'uppercase'}}>{j.equipoLocal} {j.resultadoFinal||''} {j.equipoVisitante}</span>
                            {j.esVip&&<span style={{background:'rgba(255,215,0,0.15)',color:'#001F6B',border:'1px solid rgba(255,215,0,0.3)',borderRadius:8,padding:'2px 8px',fontFamily:"'Teko',sans-serif",fontSize:11}}>VIP</span>}
                        </div>
                        {j.ganadorBote&&<p style={{fontFamily:"'Inter',sans-serif",fontSize:12,color:'#10b981',marginTop:4}}>🏆 Bote ganado por {j.ganadorBote}</p>}
                    </div>
                );
            })}
            {historico&&jornadas.filter(function(j){return j.estado==='Finalizada';}).length===0&&(
                <p style={{fontFamily:"'Inter',sans-serif",fontSize:13,color:'rgba(0,31,107,0.4)',textAlign:'center',padding:16}}>Aún no hay jornadas finalizadas</p>
            )}
        </div>
    );
};

