const CalendarioScreen = ({ teamLogos }) => {
    var G = styles.colors;
    var [jornadas, setJornadas] = useState([]);
    var [loading, setLoading] = useState(true);

    useEffect(function() { 
        var q = query(collection(db, "jornadas"), orderBy("numeroJornada")); 
        var unsub = onSnapshot(q, function(snap) {
            setJornadas(snap.docs.map(function(d) { return { id: d.id, ...d.data() }; }));
            setLoading(false);
        }); 
        return function() { unsub(); };
    }, []);

    if (loading) return <LoadingSkeleton />;

    var estadoColor = function(estado) {
        if (estado === 'Abierta') return '#10b981';
        if (estado === 'En vivo') return '#e63946';
        if (estado === 'Finalizada') return G.deepBlue;
        return 'rgba(0,31,107,0.25)';
    };

    return (
        <div>
            <h2 style={styles.title}>CALENDARIO 26/27</h2>
            <div style={{display:'flex', flexDirection:'column', gap:8}}>
                {jornadas.map(function(j) {
                    var live = j.liveData;
                    var esFinalizada = j.estado === 'Finalizada';
                    var esVivo = j.estado === 'En vivo' || (live && live.isLive);
                    var tieneResultado = esFinalizada || (live && live.golesLocal !== null && live.golesLocal !== undefined);
                    var gLocal = esFinalizada ? j.resultadoLocal : (live ? live.golesLocal : null);
                    var gVis   = esFinalizada ? j.resultadoVisitante : (live ? live.golesVisitante : null);

                    return (
                        <div key={j.id} style={{
                            background: esVivo ? '#001F6B' : '#fff',
                            borderRadius: 14,
                            border: '1px solid ' + (esVivo ? 'transparent' : 'rgba(0,31,107,0.08)'),
                            padding: '14px 16px',
                            boxShadow: esVivo ? '0 4px 20px rgba(0,31,107,0.2)' : 'none',
                        }}>
                            <div style={{display:'flex', alignItems:'center', gap:8, marginBottom:tieneResultado?8:0}}>
                                <span style={{fontFamily:"'Teko',sans-serif",fontSize:13,fontWeight:700,
                                    color: esVivo ? 'rgba(255,255,255,0.4)' : 'rgba(0,31,107,0.35)',
                                    letterSpacing:2, minWidth:30}}>J{j.numeroJornada}</span>
                                <span style={{flex:1, fontFamily:"'Teko',sans-serif", fontSize:15, fontWeight:600,
                                    letterSpacing:1, textTransform:'uppercase',
                                    color: esVivo ? '#fff' : G.deepBlue}}>
                                    {j.equipoLocal} vs {j.equipoVisitante}
                                    {j.derbi && ' 🔥'}
                                </span>
                                {esVivo ? (
                                    <span style={{fontFamily:"'Teko',sans-serif",fontSize:12,letterSpacing:2,
                                        color:'#e63946',background:'rgba(230,57,70,0.15)',padding:'3px 10px',borderRadius:10,
                                        animation:'blink-live 1.5s infinite'}}>EN VIVO</span>
                                ) : (
                                    <span style={{fontFamily:"'Inter',sans-serif",fontSize:10,
                                        color: estadoColor(j.estado), background: estadoColor(j.estado) + '15',
                                        padding:'3px 10px',borderRadius:10}}>{j.estado}</span>
                                )}
                            </div>
                            <p style={{fontFamily:"'Inter',sans-serif",fontSize:11,
                                color: esVivo ? 'rgba(255,255,255,0.35)' : 'rgba(0,31,107,0.4)',
                                marginBottom: tieneResultado ? 8 : 0}}>
                                {formatearFechaJornada(j.fecha)} · {j.estadio}
                            </p>
                            {tieneResultado && (
                                <div style={{display:'flex', alignItems:'center', gap:12, marginTop:6}}>
                                    <span style={{fontFamily:"'Teko',sans-serif", fontSize:28, fontWeight:700,
                                        color: esVivo ? '#FFD700' : G.deepBlue, letterSpacing:2}}>
                                        {gLocal} — {gVis}
                                    </span>
                                    {(live && live.primerGoleador) && (
                                        <span style={{fontFamily:"'Inter',sans-serif",fontSize:11,
                                            color: esVivo ? 'rgba(255,255,255,0.5)' : 'rgba(0,31,107,0.4)'}}>
                                            ⚽ {live.primerGoleador}
                                        </span>
                                    )}
                                    {esFinalizada && j.ganadores && j.ganadores.length > 0 && (
                                        <span style={{fontFamily:"'Inter',sans-serif",fontSize:11,
                                            color:'#10b981', marginLeft:'auto'}}>
                                            🏆 {j.ganadores.join(', ')}
                                        </span>
                                    )}
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

// ============================================================================
// --- ADMINISTRADOR Y CIERRE ---
// ============================================================================

// ============================================================================
// --- CÁLCULO AUTOMÁTICO DE ESTRELLAS — vía API-Football (fixtures/players) ---
// Se dispara al finalizar una jornada desde el panel admin. Aislado del
// cálculo de puntos de la porra principal: si falla, no afecta a esos puntos.
// ============================================================================
// Función pura: calcula los puntos de Estrellas de toda la plantilla a partir
// de las estadísticas de la API para un fixture, en cualquier momento (en vivo
// o finalizado). Reutilizada tanto por el cálculo definitivo (admin, al cerrar
// la jornada) como por la estimación en directo durante el partido.
function calcularPuntosPlantillaDesdeStats(statsPorApiId, plantilla, porteriaACero) {
    var jugadoresSinApiId = [];
    var puntosPorNombre = {};
    var detallesPorNombre = {};

    function veces(valor, umbral) {
        return Math.floor(Number(valor || 0) / umbral);
    }

    plantilla.forEach(function(jug) {
        if (!jug.apiId) {
            jugadoresSinApiId.push(jug.nombre);
            puntosPorNombre[jug.nombre] = 0;
            detallesPorNombre[jug.nombre] = { puntosBase:0, extras:{} };
            return;
        }

        var st = statsPorApiId[jug.apiId];
        if (!st) {
            puntosPorNombre[jug.nombre] = 0;
            detallesPorNombre[jug.nombre] = { puntosBase:0, extras:{}, sinEstadisticas:true };
            return;
        }

        var pts = 0;
        var extras = {};
        var minutos = Number((st.games && st.games.minutes) || 0);
        var titular = !!(st.games && st.games.substitute === false && minutos > 0);
        var suplenteJugo = !!(st.games && st.games.substitute === true && minutos > 0);

        if (titular && minutos >= 60) { pts += 2; extras.titular60 = 2; }
        else if (suplenteJugo) { pts += 1; extras.suplente = 1; }

        var goles = Number((st.goals && st.goals.total) || 0);
        if (goles > 0) {
            var ptsPorGol = (jug.posicion === 'Portero' || jug.posicion === 'Defensa') ? 8
                : (jug.posicion === 'Centrocampista' || jug.posicion === 'Mediapunta') ? 6 : 5;
            pts += goles * ptsPorGol;
            extras.goles = goles * ptsPorGol;
        }

        var asistencias = Number((st.goals && st.goals.assists) || 0);
        pts += asistencias * 3;
        if (asistencias) extras.asistencias = asistencias * 3;

        var amarillas = Number((st.cards && st.cards.yellow) || 0);
        var rojas = Number((st.cards && st.cards.red) || 0);
        pts -= amarillas;
        pts -= rojas * 3;
        if (amarillas) extras.amarillas = -amarillas;
        if (rojas) extras.rojas = -rojas * 3;

        var penFallado = Number((st.penalty && st.penalty.missed) || 0);
        pts -= penFallado * 2;
        if (penFallado) extras.penaltisFallados = -penFallado * 2;

        if (jug.posicion === 'Portero') {
            var penParado = Number((st.penalty && st.penalty.saved) || 0);
            var paradas = Number((st.goals && st.goals.saves) || 0);
            pts += penParado * 5;
            pts += paradas;
            if (penParado) extras.penaltisParados = penParado * 5;
            if (paradas) extras.paradas = paradas;
        }

        if (porteriaACero && minutos > 0) {
            if (jug.posicion === 'Portero') { pts += 4; extras.porteriaCero = 4; }
            else if (jug.posicion === 'Defensa') { pts += 2; extras.porteriaCero = 2; }
        }

        // Baremo fantasy añadido. Se utilizan únicamente campos que API-Football
        // devuelve de forma estructurada en /fixtures/players.
        var rematesAPuerta = Number(st.shots && st.shots.on ? st.shots.on : 0);
        var regatesCompletados = Number(st.dribbles && st.dribbles.success ? st.dribbles.success : 0);
        var tackles = Number(st.tackles && st.tackles.total ? st.tackles.total : 0);
        var intercepciones = Number(st.tackles && st.tackles.interceptions ? st.tackles.interceptions : 0);
        var bloqueos = Number(st.tackles && st.tackles.blocks ? st.tackles.blocks : 0);
        var pasesClave = Number(st.passes && st.passes.key ? st.passes.key : 0);
        // En /fixtures/players, passes.accuracy es el NÚMERO de pases
        // acertados del jugador en ese partido (no un porcentaje).
        var pasesAcertados = Number(st.passes && st.passes.accuracy ? parseInt(st.passes.accuracy) || 0 : 0);
        var duelosGanados = Number(st.duels && st.duels.won ? st.duels.won : 0);

        var eRemates = veces(rematesAPuerta, 2);
        var eRegates = veces(regatesCompletados, 2);
        var eTackles = veces(tackles, 3);
        var eIntercepciones = veces(intercepciones, 3);
        var eBloqueos = veces(bloqueos, 2);
        var ePasesClave = veces(pasesClave, 2);
        var ePasesAcertados = veces(pasesAcertados, 25);
        var eDuelos = veces(duelosGanados, 4);

        if (eRemates) { pts += eRemates; extras.rematesAPuerta = eRemates; }
        if (eRegates) { pts += eRegates; extras.regates = eRegates; }
        if (eTackles) { pts += eTackles; extras.tackles = eTackles; }
        if (eIntercepciones) { pts += eIntercepciones; extras.intercepciones = eIntercepciones; }
        if (eBloqueos) { pts += eBloqueos; extras.bloqueos = eBloqueos; }
        if (ePasesClave) { pts += ePasesClave; extras.pasesClave = ePasesClave; }
        if (ePasesAcertados) { pts += ePasesAcertados; extras.pasesAcertados = ePasesAcertados; }
        if (eDuelos) { pts += eDuelos; extras.duelosGanados = eDuelos; }

        puntosPorNombre[jug.nombre] = pts;
        detallesPorNombre[jug.nombre] = {
            puntosBase: pts,
            extras: extras,
            statsDisponibles: {
                rematesAPuerta, regatesCompletados, tackles, intercepciones,
                bloqueos, pasesClave, pasesAcertados, duelosGanados
            }
        };
    });

    return {
        puntosPorNombre: puntosPorNombre,
        detallesPorNombre: detallesPorNombre,
        jugadoresSinApiId: jugadoresSinApiId
    };
}

// Normaliza un nombre para emparejar con la API (sin tildes ni mayúsculas).
function normalizarNombreJugadorAPI(s) {
    return String(s || '').toLowerCase()
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-z ]/g, ' ').replace(/\s+/g, ' ').trim();
}

// Busca un jugador de nuestra plantilla dentro del squad de la API.
function emparejarNombreEnSquad(squad, objetivo) {
    var partes = objetivo.split(' ');
    return squad.find(function(p) {
        var n = normalizarNombreJugadorAPI(p.name);
        if (n === objetivo) return true;
        var nuestras = partes.filter(function(w){ return w.length >= 3; });
        if (nuestras.length && nuestras.every(function(w){ return n.indexOf(w) !== -1; })) return true;
        var suyas = n.split(' ').filter(function(w){ return w.length >= 3; });
        if (suyas.length && suyas.every(function(w){ return objetivo.indexOf(w) !== -1; })) return true;
        return false;
    });
}

async function calcularEstrellasJornada(jornadaId, fixtureId, plantilla, jornadaInfo) {
    if (!fixtureId) throw new Error('Esta jornada no tiene fixtureId guardado. Sincroniza con la API antes de recalcular.');
    if (!API_FOOTBALL_KEY) throw new Error('Falta configurar REACT_APP_API_FOOTBALL_KEY en el entorno.');

    // ── PASO 0 · AUTORRESOLUCIÓN DE apiIds ─────────────────────────────────
    // Si algún jugador de la plantilla no tiene apiId, se intenta resolver
    // automáticamente contra la plantilla oficial de la API y se guarda en
    // fotosJugadores para siempre. El recálculo deja de depender de que se
    // haya pasado antes por la herramienta manual.
    var plantillaEfectiva = plantilla.map(function(j) { return { ...j }; });
    var sinId = plantillaEfectiva.filter(function(j) { return !(parseInt(j.apiId) > 0); });
    if (sinId.length > 0) {
        try {
            var resSquad = await fetch('https://v3.football.api-sports.io/players/squads?team=' + API_TEAM_ID_UDLP, { headers: { 'x-apisports-key': API_FOOTBALL_KEY } });
            var dataSquad = await resSquad.json();
            var squad = dataSquad.response && dataSquad.response[0] && dataSquad.response[0].players ? dataSquad.response[0].players : [];
            if (squad.length) {
                for (var si = 0; si < sinId.length; si++) {
                    var jugSin = sinId[si];
                    var matchSquad = emparejarNombreEnSquad(squad, normalizarNombreJugadorAPI(jugSin.nombre));
                    if (matchSquad) {
                        jugSin.apiId = matchSquad.id;
                        await setDoc(doc(db, 'fotosJugadores', jugSin.nombre), {
                            apiId: matchSquad.id, actualizadoEn: serverTimestamp(),
                        }, { merge: true });
                    }
                }
            }
        } catch(eSquad) { console.warn('Estrellas: no se pudo autorresolver apiIds:', eSquad.message); }
    }

    var url = 'https://v3.football.api-sports.io/fixtures/players?fixture=' + fixtureId;
    var res = await fetch(url, { headers: { 'x-apisports-key': API_FOOTBALL_KEY } });
    var data = await res.json();
    if (!data.response || data.response.length === 0) {
        throw new Error('La API no tiene todavía las estadísticas de jugadores de este partido. No se ha tocado nada — vuelve a intentarlo en unos minutos.');
    }

    // Mapa apiId -> estadísticas del jugador en este partido concreto.
    // Además se registra el nombre oficial y a qué equipo pertenece cada
    // apiId, para poder DETECTAR jugadores de la UDLP que jugaron sin estar
    // vinculados en nuestra plantilla (p. ej. canteranos recién convocados).
    var statsPorApiId = {};
    var infoApiJugador = {};   // apiId -> { nombre, esUDLP }
    data.response.forEach(function(equipo) {
        var esUDLP = !!(equipo.team && equipo.team.id === API_TEAM_ID_UDLP);
        (equipo.players || []).forEach(function(p) {
            if (p && p.player && p.player.id) {
                statsPorApiId[p.player.id] = (p.statistics && p.statistics[0]) || {};
                infoApiJugador[p.player.id] = { nombre: p.player.name || ('ID ' + p.player.id), esUDLP: esUDLP };
            }
        });
    });

    var udlpEsLocal = jornadaInfo.equipoLocal === 'UD Las Palmas';
    var golesEncajados = parseInt(udlpEsLocal ? jornadaInfo.resultadoVisitante : jornadaInfo.resultadoLocal);
    var porteriaACero = golesEncajados === 0;
    var calculo = calcularPuntosPlantillaDesdeStats(statsPorApiId, plantillaEfectiva, porteriaACero);
    var puntosPorNombre = calculo.puntosPorNombre;
    var detallesPorNombre = calculo.detallesPorNombre;
    var jugadoresSinApiId = calculo.jugadoresSinApiId;

    // Las estrellas de acción (8, 6, 5...) son una competición acumulativa.
    // NO son todavía los puntos de la clasificación general. Primero calculamos
    // las estrellas obtenidas en esta jornada por cada participante y después
    // las convertimos a 5/4/3/2/1 puntos mediante ranking de competición.
    var seleccionesSnap = await getDocs(collection(db, 'estrellas_seleccion', jornadaId, 'jugadores'));
    var resultadosSnap = await getDocs(collection(db, 'estrellas_resultados', jornadaId, 'jugadores'));
    var antiguos = {};
    resultadosSnap.forEach(function(d) { antiguos[d.id] = d.data() || {}; });

    var resultados = [];
    seleccionesSnap.forEach(function(docSnap) {
        var userId = docSnap.id;
        var sel = docSnap.data().jugadores || [];
        var totalEstrellas = 0;
        var desglosePorJugador = {};
        var detalle = sel.map(function(j) {
            var pts = Number(puntosPorNombre[j.nombre] || 0);
            totalEstrellas += pts;
            desglosePorJugador[j.nombre] = pts;
            return { nombre: j.nombre, puntos: pts, detalleStats: detallesPorNombre[j.nombre] || {} };
        });
        resultados.push({
            userId: userId,
            estrellasJornada: totalEstrellas,
            desglosePorJugador: desglosePorJugador,
            detalle: detalle,
        });
    });

    // Ranking de competición: empate en un puesto comparte puntos y salta el
    // puesto siguiente. Ej.: 20,20,13,9,7 => 5,5,3,2,1.
    resultados.sort(function(a,b) {
        if (b.estrellasJornada !== a.estrellasJornada) return b.estrellasJornada - a.estrellasJornada;
        return a.userId.localeCompare(b.userId);
    });
    var anterior = null;
    var puesto = 0;
    resultados.forEach(function(r, index) {
        if (anterior === null || r.estrellasJornada !== anterior) puesto = index + 1;
        r.puestoEstrellas = puesto;
        r.puntosRanking = puesto <= 5 ? (6 - puesto) : 0;
        anterior = r.estrellasJornada;
    });

    // ── ESCUDO ANTI-PISADO ─────────────────────────────────────────────────
    // Si esta jornada YA tenía estrellas guardadas y el cálculo nuevo sale a
    // cero para todo el mundo, es señal inequívoca de un fallo de datos de la
    // API (o de apiIds sin resolver), no de que nadie puntuara. Se aborta SIN
    // escribir nada: los datos buenos nunca se sustituyen por ceros.
    var sumaNueva = 0;
    resultados.forEach(function(r) { sumaNueva += Number(r.estrellasJornada || 0); });
    var sumaAntigua = 0;
    Object.keys(antiguos).forEach(function(uid) {
        var v = antiguos[uid] || {};
        sumaAntigua += Number(v.estrellasJornada !== undefined ? v.estrellasJornada : (v.puntosJornada || 0));
    });
    if (sumaAntigua > 0 && sumaNueva === 0) {
        throw new Error('El nuevo cálculo daba 0 estrellas para todos los participantes, pero esta jornada ya tenía ' + sumaAntigua + ' estrellas guardadas. Se ha ABORTADO sin tocar nada para proteger los datos. Causa probable: la API no devolvió estadísticas o faltan apiIds' + (jugadoresSinApiId.length ? ' (' + jugadoresSinApiId.join(', ') + ')' : '') + '.');
    }

    // Los pronósticos existentes de esta jornada: el ranking 5/4/3/2/1 se
    // vuelca también en el pronóstico de cada jugador (puntosEstrellasJornada),
    // que es el campo que leen los puntos provisionales y el cierre definitivo.
    // ANTES ese campo no se escribía en ningún sitio y por eso las Estrellas
    // nunca llegaban a la clasificación general.
    var pronosticosSnap = await getDocs(collection(db, 'pronosticos', jornadaId, 'jugadores'));
    var pronosticoExiste = {};
    pronosticosSnap.forEach(function(d) { pronosticoExiste[d.id] = true; });

    var batch = writeBatch(db);

    // ── Datos para el TABLERO de la jornada (campo con fichas) ─────────────
    // Se guardan las estrellas de CADA futbolista de la plantilla (los haya
    // elegido alguien o no) y qué apiIds jugaron minutos, para pintar el
    // campo con la alineación y la estrella numerada de cada ficha.
    var jugaronApiIds = [];
    Object.keys(statsPorApiId).forEach(function(idApi) {
        var g = (statsPorApiId[idApi] && statsPorApiId[idApi].games) || {};
        if (Number(g.minutes || 0) > 0) jugaronApiIds.push(parseInt(idApi));
    });
    // Titulares y suplentes de la UDLP deducidos de las propias estadísticas
    // (games.substitute), sin depender del endpoint de alineaciones.
    var titularesApiIds = [];
    var suplentesApiIds = [];
    plantillaEfectiva.forEach(function(j) {
        var idn = parseInt(j.apiId) || 0;
        if (!idn) return;
        var st = statsPorApiId[idn];
        if (!st) return;
        var g = st.games || {};
        if (Number(g.minutes || 0) > 0) {
            if (g.substitute) suplentesApiIds.push(idn); else titularesApiIds.push(idn);
        }
    });
    var puntosJugadoresArr = plantillaEfectiva.map(function(j) {
        var det = detallesPorNombre[j.nombre] || {};
        return {
            nombre: j.nombre,
            apiId: parseInt(j.apiId) || 0,
            estrellas: Number(puntosPorNombre[j.nombre] || 0),
            // Desglose de CÓMO consiguió las estrellas (para el popup de la ficha)
            desglose: det.extras || {},
            datos: det.statsDisponibles || {},
        };
    });
    // 🔎 Jugadores de la UDLP que JUGARON este partido pero cuyo apiId no
    // está en nuestra plantilla: es exactamente el caso "Rafa Cruz" — la API
    // nos da su nombre e ID oficiales para darle de alta con un clic.
    var idsPlantilla = {};
    plantillaEfectiva.forEach(function(j) { var idn = parseInt(j.apiId) || 0; if (idn) idsPlantilla[idn] = true; });
    var jugaronSinVincular = [];
    Object.keys(statsPorApiId).forEach(function(idApi) {
        var info = infoApiJugador[idApi] || {};
        if (!info.esUDLP) return;
        var g = (statsPorApiId[idApi] && statsPorApiId[idApi].games) || {};
        if (Number(g.minutes || 0) > 0 && !idsPlantilla[parseInt(idApi)]) {
            jugaronSinVincular.push({ apiId: parseInt(idApi), nombre: info.nombre, minutos: Number(g.minutes || 0) });
        }
    });
    batch.set(doc(db, 'estrellas_resultados', jornadaId), {
        puntosJugadores: puntosJugadoresArr,
        jugaronApiIds: jugaronApiIds,
        titularesApiIds: titularesApiIds,
        suplentesApiIds: suplentesApiIds,
        jugaronSinVincular: jugaronSinVincular,
        fixtureId: fixtureId,
        calculadoEn: serverTimestamp(),
    }, { merge: true });

    resultados.forEach(function(r) {
        // El acumulado de la Liga de Estrellas YA NO se toca aquí con sumas
        // incrementales (eran la causa de los descuadres al recalcular).
        // Ahora se reconstruye entero desde estrellas_resultados con
        // reconstruirClasificacionEstrellas() justo después de este cálculo.

        batch.set(doc(db, 'estrellas_seleccion', jornadaId, 'jugadores', r.userId), {
            puntosEstrellas: r.estrellasJornada,
            estrellasJornada: r.estrellasJornada,
            desglosePorJugador: r.desglosePorJugador,
            puntosRanking: r.puntosRanking,
            puestoEstrellas: r.puestoEstrellas,
        }, { merge: true });

        batch.set(doc(db, 'estrellas_resultados', jornadaId, 'jugadores', r.userId), {
            puntosJornada: r.puntosRanking,
            estrellasJornada: r.estrellasJornada,
            puntosRanking: r.puntosRanking,
            puestoEstrellas: r.puestoEstrellas,
            detalle: r.detalle,
            recalculoVersion: 2,
            calculadoEn: serverTimestamp(),
        });

        // Solo si el pronóstico existe — no se crean pronósticos fantasma
        // que inflarían el bote y la lista de participantes.
        if (pronosticoExiste[r.userId]) {
            batch.set(doc(db, 'pronosticos', jornadaId, 'jugadores', r.userId), {
                puntosEstrellasJornada: r.puntosRanking,
            }, { merge: true });
        }
    });

    // Si había resultados anteriores para usuarios que ya no tienen selección,
    // se eliminan sus documentos de esta jornada. El acumulado se corrige solo
    // al reconstruir la clasificación después.
    var nuevosIds = {};
    resultados.forEach(function(r){ nuevosIds[r.userId] = true; });
    Object.keys(antiguos).forEach(function(uid){
        if (!nuevosIds[uid]) {
            batch.delete(doc(db, 'estrellas_resultados', jornadaId, 'jugadores', uid));
            batch.delete(doc(db, 'estrellas_seleccion', jornadaId, 'jugadores', uid));
            if (pronosticoExiste[uid]) {
                batch.set(doc(db, 'pronosticos', jornadaId, 'jugadores', uid), {
                    puntosEstrellasJornada: 0,
                }, { merge: true });
            }
        }
    });

    await batch.commit();

    // Marcador de control de la jornada: permite saber que el cálculo de
    // estrellas existe, pero NO bloquea el recálculo posterior.
    await setDoc(doc(db, 'jornadas', jornadaId), {
        estrellasCalculadas: true,
        estrellasCalculadasEn: serverTimestamp(),
        estrellasFixtureId: fixtureId,
    }, { merge: true });

    if (jugadoresSinApiId.length > 0) {
        console.warn('Estrellas: jugadores sin apiId:', jugadoresSinApiId);
    }

    return {
        resumen: resultados.map(function(r) {
            return { userId: r.userId, estrellasJornada: r.estrellasJornada, puestoEstrellas: r.puestoEstrellas, puntosRanking: r.puntosRanking };
        }),
        jugadoresSinApiId: jugadoresSinApiId,
        jugaronSinVincular: jugaronSinVincular,
    };
}

// ============================================================================
// RECONSTRUCCIÓN TOTAL DE LA LIGA DE ESTRELLAS
// ============================================================================
// Suma desde cero las estrellas de TODAS las jornadas leyendo directamente
// estrellas_resultados (la fuente de verdad jornada a jornada) y escribe el
// acumulado como valor ABSOLUTO. Al no usar sumas incrementales es matemática-
// mente imposible que el total se descuadre: recalcular una jornada 20 veces
// da siempre el mismo resultado. Se ejecuta automáticamente tras cada cálculo
// de jornada y también desde el botón global del admin.
async function reconstruirClasificacionEstrellas() {
    var jornadasSnap = await getDocs(collection(db, 'jornadas'));
    var totales = {};        // userId -> estrellas acumuladas
    var jornadasConDatos = 0;

    for (var i = 0; i < jornadasSnap.docs.length; i++) {
        var jid = jornadasSnap.docs[i].id;
        var resSnap = await getDocs(collection(db, 'estrellas_resultados', jid, 'jugadores'));
        if (resSnap.empty) continue;
        jornadasConDatos++;
        resSnap.forEach(function(d) {
            var v = d.data() || {};
            // Formato nuevo: estrellasJornada. Formato antiguo: puntosJornada
            // contenía las estrellas de acción.
            var estrellas = Number(v.estrellasJornada !== undefined ? v.estrellasJornada : (v.puntosJornada || 0));
            totales[d.id] = (totales[d.id] || 0) + estrellas;
        });
    }

    // Usuarios que estaban en el acumulado pero ya no aparecen en ninguna
    // jornada: se ponen a 0 (no se borra el doc para conservar otros campos).
    var clasifSnap = await getDocs(collection(db, 'clasificacion_estrellas'));
    clasifSnap.forEach(function(d) { if (totales[d.id] === undefined) totales[d.id] = 0; });

    var batch = writeBatch(db);
    Object.keys(totales).forEach(function(uid) {
        batch.set(doc(db, 'clasificacion_estrellas', uid), {
            puntosEstrellas: totales[uid],
            reconstruidaEn: serverTimestamp(),
        }, { merge: true });
    });
    await batch.commit();

    return { usuarios: Object.keys(totales).length, jornadasConDatos: jornadasConDatos };
}

async function actualizarPuntosProvisionalesJornada(jornadaId) {
    var snap=await getDocs(collection(db,'pronosticos',jornadaId,'jugadores'));
    // Fuente de verdad del ranking 5/4/3/2/1: estrellas_resultados. Así se
    // corrigen también jornadas calculadas antes de que el campo
    // puntosEstrellasJornada se escribiera en los pronósticos.
    var estSnap=await getDocs(collection(db,'estrellas_resultados',jornadaId,'jugadores'));
    var rankingEstrellas={};
    estSnap.forEach(function(d){ rankingEstrellas[d.id]=Number((d.data()||{}).puntosRanking||0); });
    var batch=writeBatch(db);
    snap.forEach(function(d){
        var p=d.data()||{};
        var base=Number(p.puntosBaseSinOtro!==undefined ? p.puntosBaseSinOtro : 0);
        var estrellas=rankingEstrellas[d.id]!==undefined ? rankingEstrellas[d.id] : Number(p.puntosEstrellasJornada||0);
        batch.set(d.ref,{puntosEstrellasJornada:estrellas,puntosProvisionales:base+estrellas},{merge:true});
    });
    await batch.commit();
}

async function cerrarJornadaDefinitivamenteAdmin(jornadaId) {
    var jSnap=await getDoc(doc(db,'jornadas',jornadaId));
    if(!jSnap.exists()) throw new Error('No se encuentra la jornada.');
    var jornada={id:jSnap.id,...jSnap.data()};
    if(jornada.cierreDefinitivo) return {ok:true,yaCerrada:true};

    // ¿Hay alguien con El Otro activado y SIN resolver? Solo en ese caso hay
    // que esperar a que termine la jornada de Primera. Si nadie lo activó (o
    // ya está todo aplicado), no hay nada que esperar y se cierra igual.
    var pSnapPrev=await getDocs(collection(db,'pronosticos',jornadaId,'jugadores'));
    var hayOtroPendiente=false;
    pSnapPrev.forEach(function(d){
        var p=d.data()||{};
        if(p.elOtroActivado && !p.elOtroAplicado) hayOtroPendiente=true;
    });
    if(hayOtroPendiente){
        var estadoPrimera=await comprobarCierrePrimeraJornada(fechaAString(getFechaPartidoISO(jornada) || jornada.fecha));
        if(!estadoPrimera.ok) return {ok:false,pendientes:estadoPrimera.pendientes,motivo:'primera_sin_terminar'};
    }

    var pSnap=pSnapPrev;
    var clasSnap=await getDocs(collection(db,'clasificacion')); var clas={}; clasSnap.forEach(function(d){clas[d.id]=d.data();});
    var otroSnap=await getDocs(collection(db,'elOtro')); var otro={}; otroSnap.forEach(function(d){otro[d.id]=d.data();});
    // Ranking de Estrellas de la jornada (5/4/3/2/1) leído de su fuente de
    // verdad. Se suma a la clasificación general de TODOS los que puntuaron
    // en Estrellas — también de quien no llegó a echar la porra esa jornada.
    var estCierreSnap=await getDocs(collection(db,'estrellas_resultados',jornadaId,'jugadores'));
    var estrellasCierre={}; estCierreSnap.forEach(function(d){ estrellasCierre[d.id]=Number((d.data()||{}).puntosRanking||0); });
    var fixtureIds=[]; pSnap.forEach(function(d){var p=d.data()||{}; if(p.elOtroActivado&&p.elOtroFixtureId&&fixtureIds.indexOf(p.elOtroFixtureId)===-1)fixtureIds.push(p.elOtroFixtureId);});
    var fxMap={};
    for(var i=0;i<fixtureIds.length;i++){
        try{var rr=await fetch('https://v3.football.api-sports.io/fixtures?id='+fixtureIds[i],{headers:{'x-apisports-key':API_FOOTBALL_KEY}});var dd=await rr.json();var fx=dd.response&&dd.response[0];if(fx){var st=fx.fixture.status.short;fxMap[fixtureIds[i]]={finalizado:['FT','AET','PEN','AWD','WO'].indexOf(st)!==-1,local:fx.teams.home.name,visitante:fx.teams.away.name,gl:fx.goals.home,gv:fx.goals.away};}}catch(e){}}

    var batch=writeBatch(db);
    pSnap.forEach(function(d){
        var p=d.data()||{}, userId=d.id;
        if(p.noContabilizado) return;
        // REGLA: el multiplicador de El Otro afecta SOLO a la base de la
        // porra. Los puntos de Estrellas se suman después, intactos —
        // antes se multiplicaba/dividía el total (base+estrellas) y las
        // Estrellas quedaban alteradas por el multiplicador.
        // Si el pronóstico no tiene guardada su base (jornadas calculadas antes
        // de existir el campo), se RECALCULA en el momento en vez de sumar 0.
        var base=Number(p.puntosBaseSinOtro!==undefined?p.puntosBaseSinOtro:calcularBasePronosticoJornada(p,jornada).base);
        var estrellasJug=estrellasCierre[userId]!==undefined?estrellasCierre[userId]:Number(p.puntosEstrellasJornada||0);
        delete estrellasCierre[userId];
        var baseTrasOtro=base, otroResultado=null, otroMult=null;
        if(p.elOtroActivado&&p.elOtroFixtureId&&p.elOtroEquipoUsado){
            var fx=fxMap[p.elOtroFixtureId];
            if(fx&&fx.finalizado){
                var local=nombresSonSimilares(fx.local,p.elOtroEquipoUsado);var gf=local?fx.gl:fx.gv;var gc=local?fx.gv:fx.gl;
                otroResultado=gf>gc?'gana':gf<gc?'pierde':'empate';
                var prev=(otro[userId]&&otro[userId].activaciones)||0; otroMult=getMultiplicadorOtro(prev);
                baseTrasOtro=aplicarMultiplicadorOtro(base,otroResultado,otroMult);
                batch.set(doc(db,'elOtro',userId),{activaciones:increment(1),historial:arrayUnion({jornada:jornada.numeroJornada,equipo:p.elOtroEquipoUsado,resultado:otroResultado,multiplicador:otroMult,ptosAntes:base,ptosDespues:baseTrasOtro})},{merge:true});
            }
        }
        var definitivo=baseTrasOtro+estrellasJug;
        var c=clas[userId]||{};
        batch.set(doc(db,'clasificacion',userId),{puntosTotales:Number(c.puntosTotales||0)+definitivo,puntosResultadoExacto:Number(c.puntosResultadoExacto||0)+Number(p.puntosResultadoExacto||0)},{merge:true});
        batch.set(d.ref,{puntosObtenidos:definitivo,puntosDefinitivos:definitivo,puntosEstrellasJornada:estrellasJug,puntosProvisionales:base+estrellasJug,elOtroResultado:otroResultado,elOtroMultiplicador:otroMult,elOtroAplicado:!!otroResultado,elOtroPendiente:false,definitivoEn:serverTimestamp()},{merge:true});
    });
    // Jugadores con puntos de Estrellas pero SIN pronóstico esta jornada
    // (o no contabilizados en la porra): sus puntos de Estrellas entran
    // igualmente en la clasificación general — la Liga de Estrellas es una
    // competición aparte y sus puntos no dependen de haber echado la porra.
    Object.keys(estrellasCierre).forEach(function(uid){
        var ptsE=Number(estrellasCierre[uid]||0);
        if(!ptsE) return;
        var cE=clas[uid]||{};
        batch.set(doc(db,'clasificacion',uid),{puntosTotales:Number(cE.puntosTotales||0)+ptsE},{merge:true});
    });
    batch.set(doc(db,'jornadas',jornadaId),{cierreDefinitivo:true,puntosCalculados:true,cierreDefinitivoEn:serverTimestamp(),estado:'Finalizada'},{merge:true});
    await batch.commit();
    return {ok:true,yaCerrada:false,pendientes:[]};
}

